import unittest
import unittest.mock
from contextlib import redirect_stdout
from pathlib import Path

HERE = Path(__file__).resolve().parent

# Telemetry isolation for every case below, before anything can launch a tool: no real ledger
# (~/.council-telemetry) or host seed (~/.config/council-telemetry) is ever touched, and the identity,
# version, network and service probes first in PATH are offline stubs (as in scripts/test-completion.sh):
# ioreg answers a fixed fake platform UUID, claude only --version, curl and opencode fail at once.
_ISOLATED_HOME = tempfile.mkdtemp(prefix="ptools-home-")
os.environ["HOME"] = _ISOLATED_HOME
os.environ["COUNCIL_TELEMETRY_DIR"] = os.path.join(_ISOLATED_HOME, "telemetry-ledger")
for _name in ("COUNCIL_TELEMETRY", "COUNCIL_HANDOVER_GATE", "COUNCIL_HANDOVER_GATE_TIMEOUT"):
    os.environ.pop(_name, None)
_STUBS = os.path.join(_ISOLATED_HOME, "stubbin")
os.mkdir(_STUBS)
for _name, _body in (("ioreg", 'echo "    \\"IOPlatformUUID\\" = \\"0A1B2C3D-4E5F-4A6B-8C7D-9E0F1A2B3C4D\\""'),
                     ("claude", '[ "$1" = --version ] && { echo "2.1.300 (Claude Code)"; exit 0; }\necho "unexpected claude call" >&2; exit 97'),
                     ("curl", 'echo "unexpected network call: curl" >&2; exit 99'),
                     ("opencode", 'echo "unexpected OpenCode service call: opencode" >&2; exit 98')):
    with open(os.path.join(_STUBS, _name), "w") as _f:
        _f.write("#!/bin/sh\n" + _body + "\n")
    os.chmod(os.path.join(_STUBS, _name), 0o755)
os.environ["PATH"] = _STUBS + os.pathsep + os.environ.get("PATH", "")
atexit.register(shutil.rmtree, _ISOLATED_HOME, True)


def load(name):
    spec = importlib.util.spec_from_file_location(name, HERE / (name + ".py"))
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def load_scripts(name):
    spec = importlib.util.spec_from_file_location(name, HERE.parent / (name + ".py"))
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


dedup_check = load("dedup_check")
prompt_report = load("prompt_report")
codemap_report = load("codemap_report")
cm = load_scripts("council_codemap")
map_prepass = load_scripts("council_map_prepass")
splitcheck = load_scripts("council_splitcheck")

EM = "—"  # the em dash council.sh puts in every task header
TAIL_RULE = "Nothing may follow the JSON tail.\n"


def prompt_round_n(task, rnd, candidate_id, candidate, relayed, answers_block="", rules=False):
    """Reproduce the shape council.sh prompt_roundN() emits, for section accounting."""
    out = ""
    if rules:
        out += "You are member A of a council of 3 AI agents.\n...rules...\n" + TAIL_RULE + "\n"
    out += "=== TASK {} {} round {} of 4 ===\n".format(task, EM, rnd)
    out += "Candidate for this round {} proposed by member A. Vote on this EXACT text:\n".format(EM)
    out += "<<<CANDIDATE {}\n{}\n>>>\n\n".format(candidate_id, candidate)
    out += "Posts of the other members in round {}:\n".format(rnd - 1)
    for member, body in relayed:
        out += "--- member {} ---\n{}\n\n".format(member, body)
    if not relayed:
        out += "\n"
    out += answers_block
    out += "Your job this round: reply to the other members.\n"
    return out.encode()


def filler(tag, n):
    """Padding with no internal repeat >= MIN_BYTES, so fixtures test only what they plant."""
    out = []
    while sum(len(x) for x in out) < n:
        out.append("{}-{:06d}-".format(tag, len(out)))
    return "".join(out)[:n]


def post(proposal, prose="Prose."):
    tail = json.dumps({"vote": "propose", "proposal": proposal, "questions": []})
    return "{}\n```json\n{}\n```".format(prose, tail), tail


def make_run(tmp, prompts, state):
    run = Path(tmp)
    (run / "prompts").mkdir(parents=True, exist_ok=True)
    (run / "posts").mkdir(parents=True, exist_ok=True)
    for name, data in prompts.items():
        (run / "prompts" / name).write_bytes(data)
    (run / "state.json").write_text(json.dumps(state))
    return run


def run_cli(script, *args):
    proc = subprocess.run([sys.executable, str(HERE / script)] + [str(a) for a in args],
                          capture_output=True, text=True)
    return proc.returncode, proc.stdout, proc.stderr


def planted(blocks, block, times):
    """The tool reports MAXIMAL repeats, so a planted block may be reported with
    the identical bytes that happen to surround every occurrence. Assert containment."""
    hits = [(b, offs) for b, offs in blocks if block.encode() in b and len(offs) == times]
    return hits


def tree_fingerprint(root):
    out = {}
    for path in sorted(Path(root).rglob("*")):
        if path.is_file():
            out[str(path.relative_to(root))] = path.read_bytes()
    return out


class DedupBlocks(unittest.TestCase):
    """dedup_check.repeated_blocks: the byte-level duplicate finder."""

    def test_empty_input_is_handled(self):
        self.assertEqual(dedup_check.repeated_blocks(b""), [])

    def test_unique_text_has_no_repeats(self):
        data = ("".join("line %04d unique content here\n" % i for i in range(200))).encode()
        self.assertEqual(dedup_check.repeated_blocks(data), [])

    def test_repeat_at_threshold_is_found_with_offsets(self):
        block = ("R" * 100 + "-tail-of-the-repeated-block-0123456789abcdef")[:dedup_check.MIN_BYTES]
        self.assertEqual(len(block), 128)
        data = (filler("A", 300) + block + filler("B", 300) + block + filler("C", 300)).encode()
        blocks = dedup_check.repeated_blocks(data)
        hits = planted(blocks, block, 2)
        self.assertEqual(len(hits), 1, blocks)
        reported, offsets = hits[0]
        self.assertEqual(offsets[1] - offsets[0], len(block) + 300,
                         "the two planted copies are 300 filler bytes apart")
        self.assertIn(block.encode(), reported)

    def test_repeat_below_threshold_is_ignored(self):
        block = filler("z", 127)
        data = (filler("A", 300) + block + filler("B", 300) + block + filler("C", 300)).encode()
        self.assertEqual([b for b in dedup_check.repeated_blocks(data) if b[0] == block.encode()], [])

    def test_three_occurrences_are_all_reported(self):
        block = filler("REPEATED", 150)
        self.assertEqual(len(block), 150)
        data = (filler("x", 200) + block + filler("y", 200) + block + filler("z", 200) + block).encode()
        self.assertEqual(len(planted(dedup_check.repeated_blocks(data), block, 3)), 1)

    def test_sub_block_covered_by_a_larger_repeat_is_not_reported_twice(self):
        block = filler("COVERING", 256)
        data = (filler("a", 300) + block + filler("b", 300) + block).encode()
        blocks = dedup_check.repeated_blocks(data)
        self.assertEqual(len(blocks), 1, blocks)
        self.assertGreaterEqual(len(blocks[0][0]), 256)
        self.assertIn(block.encode(), blocks[0][0])

    def test_overlapping_run_counts_non_overlapping_occurrences_only(self):
        data = b"m" * 300  # every window overlaps every other
        for block, offsets in dedup_check.repeated_blocks(data):
            starts = sorted(offsets)
            for earlier, later in zip(starts, starts[1:]):
                self.assertGreaterEqual(later - earlier, len(block),
                                        "reported occurrences must not overlap")

    def test_multibyte_utf8_is_handled_on_bytes(self):
        block = "café-雪-" * 24  # multi-byte; >=128 bytes
        self.assertGreaterEqual(len(block.encode()), dedup_check.MIN_BYTES)
        data = (filler("A", 200) + block + filler("B", 200) + block).encode()
        hits = planted(dedup_check.repeated_blocks(data), block, 2)
        self.assertEqual(len(hits), 1)
        # the reporting path must not raise on a preview cut inside a code point
        hits[0][0][:100].decode("utf-8", errors="replace")


class DedupCli(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        block = filler("DUP", 200)
        data = (filler("head", 400) + block + filler("mid", 400) + block).encode()
        self.run_dir = make_run(self.tmp, {"t1-r2-A.md": data}, {"config": {"tasks": []}})

    def test_help_exits_zero_with_usage(self):
        code, out, _ = run_cli("dedup_check.py", "-h")
        self.assertEqual(code, 0)
        self.assertIn("dedup_check.py <run-dir>", out)

    def test_missing_argument_exits_nonzero(self):
        code, _, err = run_cli("dedup_check.py")
        self.assertNotEqual(code, 0)
        self.assertIn("usage", err.lower())

    def test_run_dir_without_prompts_exits_nonzero(self):
        empty = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, empty)
        code, _, err = run_cli("dedup_check.py", empty)
        self.assertNotEqual(code, 0)
        self.assertIn("prompts", err)

    def test_reports_the_planted_duplicate_and_summary(self):
        code, out, _ = run_cli("dedup_check.py", self.run_dir)
        self.assertEqual(code, 0)
        self.assertIn("t1-r2-A.md:", out)
        self.assertRegex(out, r"2\d\d bytes x 2")
        self.assertIn("1 prompts;", out)
        self.assertIn("repeated blocks >=128 bytes", out)

    def test_does_not_modify_the_run_directory(self):
        before = tree_fingerprint(self.run_dir)
        run_cli("dedup_check.py", self.run_dir)
        self.assertEqual(tree_fingerprint(self.run_dir), before)


class SectionAccounting(unittest.TestCase):
    """prompt_report.section_bytes: every byte must land in exactly one section."""

    def setUp(self):
        self.state = {"config": {"tasks": [{"id": "t1", "text": "Do the thing.", "execute": False}]},
                      "answers": []}

    def partition_holds(self, data, state=None):
        counts = prompt_report.section_bytes(data, state or self.state)
        self.assertEqual(sum(counts.values()), len(data),
                         "sections must partition every byte")
        return counts

    def test_partition_holds_for_a_round_prompt(self):
        body, _ = post("Some proposal text.")
        data = prompt_round_n("t1", 2, "t1-c1", "CANDIDATE BODY", [("B", body)])
        counts = self.partition_holds(data)
        self.assertGreater(counts["candidate"], 0)
        self.assertGreater(counts["relayed posts"], 0)

    def test_partition_holds_with_rules_and_notes(self):
        data = ("You are member A of a council of 3 AI agents.\n" + TAIL_RULE +
                "\nHandover note from your predecessor session (same member id):\n"
                "<<<HANDOVER\nnote body\n>>>\n\n"
                "=== TASK t1 {} round 2 of 4 ===\nbody\n\nYour job this round: x\n".format(EM)).encode()
        counts = self.partition_holds(data)
        self.assertGreater(counts["rules"], 0)
        self.assertGreater(counts["replacement notes"], 0)

    def test_candidate_bytes_match_the_candidate_block(self):
        candidate = "CANDIDATE BODY\nsecond line"
        body, _ = post("unrelated")
        data = prompt_round_n("t1", 2, "t1-c1", candidate, [("B", body)])
        counts = prompt_report.section_bytes(data, self.state)
        block = "<<<CANDIDATE t1-c1\n{}\n>>>\n".format(candidate).encode()
        self.assertEqual(counts["candidate"], len(block))

    def test_answers_block_is_attributed_to_answers(self):
        state = dict(self.state, answers=[{"task": "t1", "member": "A",
                                           "question": "Q?", "answer": "A!"}])
        block = (prompt_report.ANSWERS.decode() + "- Q (member A): Q?\n  A: A!\n")
        body, _ = post("unrelated")
        data = prompt_round_n("t1", 2, "t1-c1", "CAND", [("B", body)], answers_block=block)
        counts = self.partition_holds(data, state)
        self.assertEqual(counts["answers"], len(block.encode()))

    def test_merged_answer_uses_existing_matcher_and_historical_prefix(self):
        merged = {"id": "q1", "ids": ["q1", "q2", "q3"],
                  "task": "t1", "member": "B, A",
                  "question": "[q1] member B: Q one?\nContinuation\n[q2] member A: Q two?\n[q3] member B: Q three?",
                  "answer": "Verbatim — answer\nsecond line"}
        block = (prompt_report.ANSWERS.decode()
                 + "- Q (member B, A): [q1] member B: Q one?\nContinuation\n"
                 + "[q2] member A: Q two?\n[q3] member B: Q three?\n"
                 + "  A: Verbatim — answer\nsecond line\n")
        body, _ = post("unrelated")
        data = prompt_round_n("t1", 2, "t1-c1", "CAND", [("A", body)],
                              answers_block=block)
        for later in ([], [{"task": "t1", "member": "A",
                            "question": "Later?", "answer": "Later!"}]):
            with self.subTest(later=bool(later)):
                state = dict(self.state, answers=[merged] + later)
                self.assertEqual(self.partition_holds(data, state)["answers"],
                                 len(block.encode()))
        state = dict(self.state, answers=[merged])
        quoted, _ = post("I quote: " + block)
        quote_data = prompt_round_n("t1", 2, "t1-c1", "CAND", [("A", quoted)])
        self.assertEqual(self.partition_holds(quote_data, state)["answers"], 0)
        changed = data.replace(b"second line", b"second Line")
        self.assertEqual(self.partition_holds(changed, state)["answers"], 0)

    def test_quoted_answers_heading_inside_a_post_is_not_an_answers_section(self):
        state = dict(self.state, answers=[{"task": "t1", "member": "A",
                                           "question": "Q?", "answer": "A!"}])
        body, _ = post("I quote: " + prompt_report.ANSWERS.decode() + "- Q (member A): Q?\n  A: A!\n")
        data = prompt_round_n("t1", 2, "t1-c1", "CAND", [("B", body)])
        counts = self.partition_holds(data, state)
        self.assertEqual(counts["answers"], 0, "a member's quotation is member text, not an answers section")

    def test_task_text_counted_only_in_round_one(self):
        text = self.state["config"]["tasks"][0]["text"]
        first = "=== TASK t1 {} round 1 of 4 ===\n{}\n\nYour job this round: x\n".format(EM, text).encode()
        later = "=== TASK t1 {} round 2 of 4 ===\n{}\n\nYour job this round: x\n".format(EM, text).encode()
        self.assertEqual(self.partition_holds(first)["task text"], len(text.encode()))
        self.assertEqual(self.partition_holds(later)["task text"], 0)

    def test_prompt_without_a_task_header_is_all_instructions(self):
        data = b"Your previous reply could not be used: re-send it.\n"
        counts = self.partition_holds(data)
        self.assertEqual(counts["instructions"], len(data))


class MeasureOneReplay(unittest.TestCase):
    """prompt_report.measure_one: the de-duplication saving replay."""

    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.candidate = "CANDIDATE BODY that is long enough to be worth de-duplicating. " * 6
        self.state = {"config": {"tasks": [{"id": "t1", "text": "Do it.", "execute": False}]},
                      "answers": [], "members": [{"id": "A"}, {"id": "B"}],
                      "candidate": {"id": "t1-c1", "member": "A", "text": self.candidate}}

    def build(self, relayed_proposal):
        body, _ = post(relayed_proposal)
        (Path(self.tmp) / "posts").mkdir(parents=True, exist_ok=True)
        (Path(self.tmp) / "posts" / "t1-r1-B.md").write_text(body)
        (Path(self.tmp) / "posts" / "t1-r1-B.json").write_text(
            json.dumps({"vote": "propose", "proposal": relayed_proposal, "questions": []}))
        data = prompt_round_n("t1", 2, "t1-c1", self.candidate, [("B", body)])
        run = make_run(self.tmp, {"t1-r2-A.md": data}, self.state)
        return data, run

    def test_identical_proposal_produces_a_saving_and_keeps_the_text_once(self):
        data, run = self.build(self.candidate)
        after, events = prompt_report.measure_one(data, "t1-r2-A.md", run, self.state)
        self.assertTrue(events, "an exact candidate copy in a relayed post must be de-duplicated")
        saving = sum(e[1] for e in events)
        self.assertGreater(saving, 0)
        self.assertEqual(len(after), len(data) - saving, "reported saving must match the replayed bytes")
        self.assertEqual(after.count(self.candidate.encode()), 1,
                         "the candidate text must survive exactly once")

    def test_different_proposal_is_left_untouched(self):
        data, run = self.build("A completely different proposal. " * 6)
        after, events = prompt_report.measure_one(data, "t1-r2-A.md", run, self.state)
        self.assertEqual(events, [])
        self.assertEqual(after, data)

    def test_one_character_difference_is_not_de_duplicated(self):
        data, run = self.build(self.candidate[:-1] + "!")
        after, events = prompt_report.measure_one(data, "t1-r2-A.md", run, self.state)
        self.assertEqual(events, [], "comparison must be byte-exact")
        self.assertEqual(after, data)


class ReportCli(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        body, _ = post("proposal")
        data = prompt_round_n("t1", 2, "t1-c1", "CAND BODY", [("B", body)])
        self.state = {"config": {"tasks": [{"id": "t1", "text": "Do it.", "execute": False}]},
                      "answers": [], "members": [{"id": "A"}, {"id": "B"}],
                      "candidate": {"id": "t1-c1", "member": "A", "text": "CAND BODY"}}
        self.run_dir = make_run(self.tmp, {"t1-r2-A.md": data}, self.state)
        (Path(self.tmp) / "posts").mkdir(parents=True, exist_ok=True)
        (Path(self.tmp) / "posts" / "t1-r1-B.md").write_text(body)

    def test_help_exits_zero_with_usage(self):
        code, out, _ = run_cli("prompt_report.py", "-h")
        self.assertEqual(code, 0)
        self.assertIn("prompt_report.py <run-dir>", out)

    def test_missing_state_exits_nonzero(self):
        os.remove(Path(self.run_dir) / "state.json")
        code, _, err = run_cli("prompt_report.py", self.run_dir)
        self.assertNotEqual(code, 0)
        self.assertTrue(err.strip())

    def test_run_without_prompts_exits_nonzero(self):
        empty = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, empty)
        (Path(empty) / "state.json").write_text(json.dumps(self.state))
        code, _, err = run_cli("prompt_report.py", empty)
        self.assertNotEqual(code, 0)
        self.assertTrue(err.strip())

    def test_report_prints_totals_and_sections_summing_to_one_hundred(self):
        code, out, _ = run_cli("prompt_report.py", self.run_dir)
        self.assertEqual(code, 0)
        self.assertIn("Prompts:", out)
        percents = [float(line.split()[-1].rstrip("%")) for line in out.splitlines()
                    if line.startswith("  ") and line.rstrip().endswith("%")
                    and any(line.strip().startswith(s.split()[0]) for s in prompt_report.SECTIONS)]
        self.assertAlmostEqual(sum(percents), 100.0, delta=0.05)

    def test_does_not_modify_the_run_directory(self):
        before = tree_fingerprint(self.run_dir)
        run_cli("prompt_report.py", self.run_dir)
        self.assertEqual(tree_fingerprint(self.run_dir), before)


def cm_cli(*args, stdin=None):
    proc = subprocess.run([sys.executable, str(HERE.parent / "council_codemap.py")] + [str(a) for a in args],
                          input=stdin, capture_output=True, text=True)
    return proc.returncode, proc.stdout, proc.stderr


def make_project(tmp):
    proj = Path(tmp) / "proj"
    (proj / "src").mkdir(parents=True)
    return proj


def make_cm_run(tmp, root, **state):
    """A run directory with REAL run state. The helper takes its root from state.config.dir and
    never from an arbitrary --dir, so a fixture without state.json is not a valid fixture."""
    run = Path(tmp) / "run"
    run.mkdir(parents=True, exist_ok=True)
    body = {"config": {"dir": os.path.realpath(str(root))}, "codemap_pending": None}
    body.update(state)
    (run / "state.json").write_text(json.dumps(body))
    return run


def write_launch(run, attempt, member, generation=1, launch_seq=1, launch_id=None):
    """The orchestration-owned pre-launch attribution record. Staging refuses to authenticate a
    reply without one, so any fixture that stages an accepted post must write it first — exactly
    as council.sh does before it launches the member. Each genuinely new launch has its own
    immutable record: the member's first launch in an attempt is stored under its own name, a
    later one (a replacement, a handover, a re-dispatched retry) under its own launch id."""
    d = Path(run) / "codemap" / "attempts" / attempt / "launches"
    d.mkdir(parents=True, exist_ok=True)
    rec = {"member": member, "generation": generation, "attempt": attempt,
           "launched_at": 1000 + launch_seq, "launch_seq": launch_seq}
    if launch_id is not None:
        rec["launch_id"] = launch_id
    (d / ((launch_id or member) + ".json")).write_text(json.dumps(rec))
    return launch_id or member


def staged_payloads(run, attempt, member):
    """Every staged payload for a member in an attempt, oldest file name first."""
    d = Path(run) / "codemap" / "attempts" / attempt / "staged"
    return [json.loads(p.read_bytes()) for p in sorted(d.glob(member + "-*.json"))]


def staged_payload(run, attempt, member):
    """The staged payload for a member's accepted event. Staged files are keyed by the FULL
    accepted-event identity, so a member may legitimately have several across replays."""
    d = Path(run) / "codemap" / "attempts" / attempt / "staged"
    files = sorted(d.glob(member + "-*.json"))
    assert len(files) == 1, "expected exactly one staged event for {}, found {}".format(member, files)
    return json.loads(files[0].read_bytes())


def accepted_meta(run, attempt, event_id):
    """The durable acceptance metadata for ONE accepted event, addressed by its event id — the way
    codemap_archive_posts reaches it, through the association written at acceptance. Member plus
    accepted-tail digest is deliberately NOT accepted as a lookup key here: two launches of the
    same member can produce byte-identical tails, so that pair identifies no single event."""
    p = Path(run) / "codemap" / "attempts" / attempt / "accepted" / (event_id + ".meta.json")
    return json.loads(p.read_bytes()) if p.exists() else None


def post_assoc(run, attempt, post_name):
    """The orchestration-owned association from a live post file to the accepted event it was
    accepted as, written at acceptance and resolved (never searched for) at archival."""
    p = (Path(run) / "codemap" / "attempts" / attempt / "post-assoc" / (post_name + ".assoc.json"))
    return json.loads(p.read_bytes()) if p.exists() else None


class CanonicalIdentity(unittest.TestCase):
    def test_canonical_json_is_deterministic_regardless_of_key_order(self):
        a = cm.canonical_json({"b": 1, "a": 2})
        b = cm.canonical_json({"a": 2, "b": 1})
        self.assertEqual(a, b)
        self.assertEqual(a, b'{"a":2,"b":1}')

    def test_entry_id_is_a_pure_function_of_the_five_fields(self):
        base = dict(root="/r", path="a.py", resolved_path="/r/a.py", source_sha256="s" * 64, byte_range=[0, 5])
        eid = cm.compute_entry_id(**base)
        self.assertEqual(len(eid), 64)
        for field, value in (("root", "/other"), ("path", "b.py"), ("resolved_path", "/r/b.py"),
                             ("source_sha256", "t" * 64), ("byte_range", [1, 5])):
            changed = dict(base, **{field: value})
            self.assertNotEqual(cm.compute_entry_id(**changed), eid, field)
        self.assertEqual(cm.compute_entry_id(**base), eid, "identical inputs are idempotent")

    def test_snapshot_id_has_no_self_referential_id_field(self):
        snap = {"schema_version": 1, "sources": []}
        snap_id = cm.compute_snapshot_id(snap)
        self.assertEqual(len(snap_id), 64)
        # adding an "id" key to the hashed object would change the hash; the store never does this
        self.assertNotEqual(snap_id, cm.sha256_hex(cm.canonical_json(dict(snap, id=snap_id))))


class PathSafetyTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = os.path.realpath(str(make_project(self.tmp)))
        (Path(self.root) / "src" / "a.py").write_text("hello\n")

    def test_absolute_input_path_rejected(self):
        with self.assertRaises(cm.CaptureError) as ctx:
            cm.safe_resolve(self.root, "/etc/passwd")
        self.assertEqual(ctx.exception.reason, "absolute_path")

    def test_traversal_outside_root_rejected(self):
        with self.assertRaises(cm.CaptureError) as ctx:
            cm.safe_resolve(self.root, "../outside.py")
        self.assertEqual(ctx.exception.reason, "traversal")

    def test_in_root_symlink_is_permitted(self):
        os.symlink(str(Path(self.root) / "src" / "a.py"), str(Path(self.root) / "link.py"))
        resolved = cm.safe_resolve(self.root, "link.py")
        self.assertEqual(resolved, str((Path(self.root) / "src" / "a.py").resolve()))

    def test_symlink_escaping_root_is_rejected(self):
        outside = Path(self.tmp) / "outside.py"
        outside.write_text("secret\n")
        os.symlink(str(outside), str(Path(self.root) / "escape.py"))
        with self.assertRaises(cm.CaptureError) as ctx:
            cm.safe_resolve(self.root, "escape.py")
        self.assertEqual(ctx.exception.reason, "escape")

    def test_symlink_retargeted_to_equal_content_is_still_detected_by_resolved_path(self):
        twin = Path(self.root) / "src" / "twin.py"
        twin.write_text("hello\n")  # byte-identical to a.py
        link = Path(self.root) / "link.py"
        os.symlink(str(Path(self.root) / "src" / "a.py"), str(link))
        cap1 = cm.bounded_capture(self.root, "link.py")
        self.assertEqual(cap1.status, "ok")
        first_resolved = cap1.resolved_path
        os.remove(str(link))
        os.symlink(str(twin), str(link))
        cap2 = cm.bounded_capture(self.root, "link.py")
        self.assertEqual(cap2.status, "ok")
        self.assertEqual(cap1.data, cap2.data, "contents match")
        self.assertNotEqual(first_resolved, cap2.resolved_path, "retargeting is visible even when contents match")

    def test_directory_is_not_a_regular_file(self):
        cap = cm.bounded_capture(self.root, "src")
        self.assertEqual(cap.status, "error")
        self.assertEqual(cap.reason, "not_regular")

    def test_missing_file(self):
        cap = cm.bounded_capture(self.root, "src/nope.py")
        self.assertEqual(cap.status, "error", "missing is a definite outcome, never retried into 'unstable'")
        self.assertEqual(cap.reason, "missing")


class BoundedCaptureTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = os.path.realpath(str(make_project(self.tmp)))
        self.path = Path(self.root) / "src" / "a.py"
        self.path.write_text("stable content\n")

    def test_each_of_the_two_complete_reads_is_read_and_hashed_in_its_own_right(self):
        cap = cm.bounded_capture(self.root, "src/a.py")
        self.assertEqual(cap.status, "ok")
        self.assertEqual(cap.data, b"stable content\n")
        # the ratified capture contract is TWO complete reads, each with its own full-file hash,
        # so the stability comparison is digest-vs-digest and the accounting is the work done
        self.assertEqual(cap.bytes_read, len(cap.data) * 2, "two complete reads are two reads")
        self.assertEqual(cap.bytes_hashed, len(cap.data) * 2, "and two full hashes are two hashes")
        self.assertEqual(cap.attempts, 1)

    def test_a_failed_attempt_still_counts_the_work_it_really_did(self):
        real = cm.capture_once
        calls = {"n": 0}

        def flaky(root, rel):
            calls["n"] += 1
            if calls["n"] == 2:                      # the second read of the first attempt fails
                raise cm.CaptureError("unreadable", "transient")
            return real(root, rel)

        with unittest.mock.patch.object(cm, "capture_once", flaky):
            cap = cm.bounded_capture(self.root, "src/a.py")
        self.assertEqual(cap.status, "ok")
        self.assertEqual(cap.attempts, 2)
        n = len(b"stable content\n")
        self.assertEqual(cap.bytes_read, n * 3, "the discarded first read really was read")
        self.assertEqual(cap.bytes_hashed, n * 3, "and really was hashed")

    def test_a_file_mutated_during_a_single_read_is_never_accepted(self):
        """The after-read fstat is the point of this: the bytes were read cleanly, but the file
        they came from no longer matches what it was when the read started."""
        a = self.path
        real_read = os.read
        state = {"mutated": False}

        def mutating_read(fd, n):
            chunk = real_read(fd, n)
            if chunk and not state["mutated"]:
                state["mutated"] = True
                a.write_text("stable content CHANGED\n")   # while the read is in flight
            return chunk

        with unittest.mock.patch("os.read", mutating_read):
            with self.assertRaises(cm.CaptureError) as ctx:
                cm.capture_once(self.root, "src/a.py")
        self.assertEqual(ctx.exception.reason, "mutated_during_read")

    def test_mutation_between_reads_is_unstable_not_silently_current(self):
        real = cm.capture_once
        calls = {"n": 0}

        def flaky(root, rel):
            calls["n"] += 1
            r = real(root, rel)
            if calls["n"] % 2 == 1:
                return r
            return cm.OneRead(r.data + b"MUTATED", cm.sha256_hex(r.data + b"MUTATED"),
                              r.st_before, r.st_after, r.resolved)

        with unittest.mock.patch.object(cm, "capture_once", flaky):
            result = cm.bounded_capture(self.root, "src/a.py")
        self.assertEqual(result.status, "unstable")

    def test_at_most_two_capture_attempts(self):
        real = cm.capture_once
        calls = {"n": 0}

        def counting(root, rel):
            calls["n"] += 1
            return real(root, rel)

        with unittest.mock.patch.object(cm, "capture_once", counting):
            cm.bounded_capture(self.root, "src/a.py")
        self.assertLessEqual(calls["n"], 4, "at most two attempts x two reads each")


class LineRangeTests(unittest.TestCase):
    def test_basic_inclusive_range(self):
        data = b"one\ntwo\nthree\n"
        self.assertEqual(cm.line_range_to_bytes(data, 2, 2), (4, 8))
        self.assertEqual(data[4:8], b"two\n")

    def test_final_lf_does_not_create_a_phantom_line(self):
        data = b"one\ntwo\n"
        self.assertEqual(len(cm.line_spans(data)), 2)

    def test_no_trailing_lf_counts_the_partial_last_line(self):
        data = b"one\ntwo"
        spans = cm.line_spans(data)
        self.assertEqual(len(spans), 2)
        self.assertEqual(data[spans[1][0]:spans[1][1]], b"two")

    def test_empty_file_has_no_valid_line_pair(self):
        with self.assertRaises(ValueError):
            cm.line_range_to_bytes(b"", 1, 1)

    def test_out_of_bounds_is_rejected_not_clamped(self):
        with self.assertRaises(ValueError):
            cm.line_range_to_bytes(b"one\ntwo\n", 1, 5)

    def test_inverted_range_is_rejected(self):
        with self.assertRaises(ValueError):
            cm.line_range_to_bytes(b"one\ntwo\n", 2, 1)

    def test_booleans_are_not_integers(self):
        with self.assertRaises(ValueError):
            cm.line_range_to_bytes(b"one\ntwo\n", True, 2)

    def test_crlf_bytes_are_retained_in_the_line_span(self):
        data = b"one\r\ntwo\r\n"
        spans = cm.line_spans(data)
        self.assertEqual(data[spans[0][0]:spans[0][1]], b"one\r\n")

    def test_non_utf8_source_rejects_line_reporting(self):
        with self.assertRaises(ValueError):
            cm.line_range_to_bytes(b"\xff\xfe\n\x00", 1, 1)

    def test_multibyte_unicode_line_boundaries(self):
        data = "café\n雪\n".encode("utf-8")
        spans = cm.line_spans(data)
        self.assertEqual(len(spans), 2)
        self.assertEqual(data[spans[0][0]:spans[0][1]].decode("utf-8"), "café\n")


class ExcerptEncodingTests(unittest.TestCase):
    def test_utf8_slice_on_a_valid_boundary_is_text(self):
        data = "hello wörld\n".encode("utf-8")
        encoding, content = cm.excerpt_encoding(data, 0, len(data))
        self.assertEqual(encoding, "utf8")
        self.assertEqual(content, data.decode("utf-8"))

    def test_slice_cutting_a_multibyte_character_falls_back_to_base64(self):
        data = "wörld".encode("utf-8")
        cut = data.index("ö".encode("utf-8")) + 1  # inside the 2-byte encoding of "ö"
        encoding, content = cm.excerpt_encoding(data, 0, cut)
        self.assertEqual(encoding, "base64")
        self.assertEqual(base64.b64decode(content), data[:cut])

    def test_binary_source_is_always_base64_never_replacement_chars(self):
        data = b"\xff\xfe\x00binary"
        encoding, content = cm.excerpt_encoding(data, 0, len(data))
        self.assertEqual(encoding, "base64")
        self.assertEqual(base64.b64decode(content), data)


class ContentAddressedStoreTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.store = cm.Store(make_cm_run(self.tmp, self.tmp))

    def test_source_object_round_trips_utf8_and_binary(self):
        self.store.write_source(cm.sha256_hex(b"hello\n"), b"hello\n")
        self.assertEqual(self.store.read_source(cm.sha256_hex(b"hello\n")), b"hello\n")
        binary = b"\xff\xfe\x00\x01"
        self.store.write_source(cm.sha256_hex(binary), binary)
        self.assertEqual(self.store.read_source(cm.sha256_hex(binary)), binary)

    def test_reusing_an_identity_with_different_content_raises(self):
        sha = cm.sha256_hex(b"one")
        path = self.store.sources_dir / (sha + ".json")
        cm.write_content_addressed(path, b'{"tampered":true}')
        with self.assertRaises(cm.CodemapError):
            cm.write_content_addressed(path, b'{"other":true}')

    def test_corrupt_source_object_content_is_detected_against_its_filename_digest(self):
        sha = cm.sha256_hex(b"hello\n")
        self.store.write_source(sha, b"hello\n")
        # simulate corruption: overwrite with content for a different digest but keep the filename
        bogus = json.dumps({"schema_version": 1, "sha256": sha, "size": 5, "encoding": "utf8", "text": "XXXXX"})
        (self.store.sources_dir / (sha + ".json")).write_text(bogus)
        with self.assertRaises(cm.CodemapError):
            self.store.read_source(sha)

    def test_index_publish_is_atomic_and_no_stray_temp_files_remain(self):
        self.store.publish_index(cm.empty_index())
        self.assertTrue(self.store.index_path.exists())
        self.assertEqual(list(self.store.base.glob(".tmp-*")), [])

    def test_publishing_a_new_index_preserves_prior_snapshot_files(self):
        snap1 = self.store.write_snapshot({"a": 1})
        snap2 = self.store.write_snapshot({"a": 2})
        self.assertNotEqual(snap1, snap2)
        self.assertTrue((self.store.snapshots_dir / (snap1 + ".json")).exists())
        self.assertTrue((self.store.snapshots_dir / (snap2 + ".json")).exists())


class RoundOneRawViewTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = str(make_project(self.tmp))
        (Path(self.root) / "src" / "a.py").write_text("one\ntwo\nthree\n")
        self.run = make_cm_run(self.tmp, self.root)

    def stage_one_bound_report(self, task, step):
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                               "--task", task, "--step", step, "--mode", "begin")
        self.assertEqual(rc, 0, err)
        write_launch(self.run, json.loads(out)["attempt"], "A")
        data = (Path(self.root) / "src" / "a.py").read_bytes()
        sha = cm.sha256_hex(data)
        post = Path(self.tmp) / f"post-{task}-{step}.json"
        post.write_text(json.dumps({"vote": "propose", "proposal": "x", "questions": [],
                                     "code_reads": [{"path": "src/a.py", "lines": [1, 1],
                                                      "observed_sha256": sha, "symbol": "foo",
                                                      "conclusion": "claim"}]}))
        rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", task, "--step", step,
                               "--mode", "stage", "--member", "A", "--generation", "1", "--post-json", post)
        self.assertEqual(rc, 0, err)
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", task, "--step", step, "--mode", "end")
        self.assertEqual(rc, 0, err)
        self.assertEqual(json.loads(out)["guard_status"], "current")
        rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", task, "--step", step, "--mode", "publish")
        self.assertEqual(rc, 0, err)
        self.assertEqual(json.loads(out)["status"], "published")

    def test_round1_of_a_later_task_strips_reports_and_symbols_even_though_index_has_claims(self):
        self.stage_one_bound_report("t1", "r2")
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t2", "--step", "r1",
                               "--mode", "begin", "--raw")
        self.assertEqual(rc, 0, err)
        rc, out, err = cm_cli("lookup", "--run-dir", self.run, "--task", "t2", "--step", "r1", stdin="{}")
        self.assertEqual(rc, 0, err)
        result = json.loads(out)
        self.assertEqual(len(result["entries"]), 1)
        self.assertEqual(result["entries"][0]["reports"], [])

    def test_symbol_lookup_is_unavailable_in_round1_raw_view(self):
        self.stage_one_bound_report("t1", "r2")
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t2", "--step", "r1", "--mode", "begin", "--raw")
        rc, out, err = cm_cli("lookup", "--run-dir", self.run, "--task", "t2", "--step", "r1", stdin='{"symbols":["foo"]}')
        self.assertEqual(rc, 0, err)
        result = json.loads(out)
        self.assertIn("unavailable_in_this_view", result.get("diagnostic", ""))

    def test_later_round_exposes_the_full_bound_report(self):
        self.stage_one_bound_report("t1", "r2")
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r3", "--mode", "begin")
        rc, out, err = cm_cli("lookup", "--run-dir", self.run, "--task", "t1", "--step", "r3", stdin='{"symbols":["foo"]}')
        self.assertEqual(rc, 0, err)
        result = json.loads(out)
        self.assertEqual(len(result["entries"]), 1)
        self.assertEqual(result["entries"][0]["reports"][0]["symbol"], "foo")
        self.assertEqual(result["entries"][0]["reports"][0]["reader"]["member"], "A")


class FreshnessGuardTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = str(make_project(self.tmp))
        self.a = Path(self.root) / "src" / "a.py"
        self.a.write_text("one\ntwo\nthree\n")
        self.run = make_cm_run(self.tmp, self.root)

    def stage(self, task, step):
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", task,
                              "--step", step, "--mode", "begin")
        write_launch(self.run, json.loads(out)["attempt"], "A")
        sha = cm.sha256_hex(self.a.read_bytes())
        post = Path(self.tmp) / "post.json"
        post.write_text(json.dumps({"vote": "propose", "proposal": "x", "questions": [],
                                     "code_reads": [{"path": "src/a.py", "observed_sha256": sha}]}))
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", task, "--step", step,
               "--mode", "stage", "--member", "A", "--generation", "1", "--post-json", post)

    def test_unchanged_exposed_source_guard_stays_current(self):
        self.stage("t1", "r2")
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        self.assertEqual(json.loads(out)["guard_status"], "current", err)

    def test_whole_file_change_is_detected_as_changed(self):
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "begin")
        self.stage_existing_entry_as_guard("t1", "r2")
        self.a.write_text("CHANGED\n")
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        self.assertEqual(json.loads(out)["guard_status"], "changed")

    def stage_existing_entry_as_guard(self, task, step):
        # publish a version once so the next attempt's "begin" freezes it as current_at_snapshot
        self.stage(task, step)
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", task, "--step", step, "--mode", "end")
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", task, "--step", step, "--mode", "publish")
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", task, "--step", step, "--mode", "begin")

    def test_deletion_is_detected_as_changed(self):
        self.stage_existing_entry_as_guard("t1", "r3")
        self.a.unlink()
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r3", "--mode", "end")
        self.assertEqual(json.loads(out)["guard_status"], "changed")

    def test_unrelated_new_source_does_not_invalidate_the_guard(self):
        self.stage_existing_entry_as_guard("t1", "r4")
        (Path(self.root) / "src" / "unrelated.py").write_text("new file, irrelevant\n")
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r4", "--mode", "end")
        self.assertEqual(json.loads(out)["guard_status"], "current")

    def test_change_outside_the_excerpt_still_blocks_because_the_guard_is_whole_file(self):
        # the guard tracks whole-file digests, so even a change past a narrow claimed range is caught
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r5", "--mode", "begin")
        sha = cm.sha256_hex(self.a.read_bytes())
        post = Path(self.tmp) / "post5.json"
        post.write_text(json.dumps({"vote": "propose", "proposal": "x", "questions": [],
                                     "code_reads": [{"path": "src/a.py", "lines": [1, 1], "observed_sha256": sha}]}))
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r5",
               "--mode", "stage", "--member", "A", "--generation", "1", "--post-json", post)
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r5", "--mode", "end")
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r5", "--mode", "publish")
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r5", "--mode", "begin")
        self.a.write_text("one\ntwo\nCHANGED THIRD LINE\n")  # line 1 (the claimed excerpt) is untouched
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r5", "--mode", "end")
        self.assertEqual(json.loads(out)["guard_status"], "changed")


class MalformedCodeReadsTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = str(make_project(self.tmp))
        (Path(self.root) / "src" / "a.py").write_text("one\ntwo\n")
        self.run = make_cm_run(self.tmp, self.root)
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", "r2", "--mode", "begin")
        self.attempt = json.loads(out)["attempt"]
        write_launch(self.run, self.attempt, "A")
        write_launch(self.run, self.attempt, "B", launch_seq=2)

    def test_malformed_item_is_a_diagnostic_and_does_not_raise(self):
        post = Path(self.tmp) / "post.json"
        post.write_text(json.dumps({"vote": "propose", "proposal": "x", "questions": [],
                                     "code_reads": [{"path": "src/a.py", "unknown_key": 1},
                                                     {"path": "src/a.py", "lines": [1, 1],
                                                      "observed_sha256": cm.sha256_hex((Path(self.root)/"src"/"a.py").read_bytes())}]}))
        rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2",
                               "--mode", "stage", "--member", "A", "--generation", "1", "--post-json", post)
        self.assertEqual(rc, 0, err)
        result = json.loads(out)
        self.assertEqual(result["diagnostics"], 1, "only the malformed item is diagnosed")
        self.assertEqual(result["entries"], 1, "the valid neighboring item is still retained")
        staged = staged_payload(self.run, self.attempt, "A")
        bad = [d for d in staged["diagnostics"] if d["code"] == "malformed_code_reads_item"]
        self.assertEqual(len(bad), 1)
        self.assertEqual(bad[0]["position"], 0, "the original array position is preserved")
        self.assertEqual(bad[0]["original"], {"path": "src/a.py", "unknown_key": 1},
                         "the original malformed report is preserved verbatim")
        self.assertIn("unknown keys", bad[0]["reason"])

    def test_explicit_null_lines_is_rejected_rather_than_read_as_a_whole_file_claim(self):
        ok, reason = cm.validate_code_reads_item({"path": "a.py", "lines": None})
        self.assertFalse(ok)
        self.assertIn("explicit null", reason)

    def test_without_a_prelaunch_record_nothing_is_authenticated(self):
        """Member Z was never launched by the orchestrator in this attempt. The caller saying
        "this is Z, generation 1" is not evidence of that, so the event is preserved in full but
        none of its claims become attributed findings a later round could rely on."""
        sha = cm.sha256_hex((Path(self.root) / "src" / "a.py").read_bytes())
        post = Path(self.tmp) / "post2.json"
        post.write_text(json.dumps({"vote": "agree", "questions": [],
                                    "code_reads": [{"path": "src/a.py", "lines": [1, 1],
                                                    "observed_sha256": sha, "conclusion": "trust me"}]}))
        rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2",
                              "--mode", "stage", "--member", "Z", "--generation", "1", "--post-json", post)
        self.assertEqual(rc, 0, err)
        staged = staged_payload(self.run, self.attempt, "Z")
        self.assertEqual([d["code"] for d in staged["diagnostics"]], ["no_prelaunch_launch_record"])
        self.assertFalse(staged["attributed"])
        self.assertIsNone(staged["attribution"]["generation"],
                          "the caller-supplied generation is not accepted as authentication")
        self.assertEqual(staged["unbound"][0]["reason"], "unattributed_accepted_event")
        self.assertEqual([r for e in staged["entries"].values() for r in e["reports"]], [],
                         "an unauthenticated event produces no bound, attributed report")
        # the tail bytes and the acceptance itself are still durable
        archive = Path(self.run) / "codemap" / "attempts" / self.attempt / "accepted"
        self.assertTrue((archive / (staged["accepted_sha256"] + ".json")).exists())

    def test_recorded_launch_generation_wins_over_a_later_handover_generation(self):
        post = Path(self.tmp) / "post3.json"
        post.write_text(json.dumps({"vote": "agree", "questions": []}))
        # the orchestrator passes generation 2 (a handover happened after the launch)
        rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2",
                              "--mode", "stage", "--member", "A", "--generation", "2", "--post-json", post)
        self.assertEqual(rc, 0, err)
        staged = staged_payload(self.run, self.attempt, "A")
        self.assertEqual(staged["attribution"]["generation"], 1,
                         "the accepted post belongs to the session that was actually launched")
        self.assertIn("generation_mismatch_with_launch_record",
                      [d["code"] for d in staged["diagnostics"]])
        archived = Path(self.run) / "codemap" / "attempts" / self.attempt / "accepted"
        self.assertTrue((archived / (staged["accepted_sha256"] + ".json")).exists(),
                        "the original accepted tail is archived before any replay can overwrite it")

    def test_two_readers_of_one_version_both_reports_retained_distinctly(self):
        data = (Path(self.root) / "src" / "a.py").read_bytes()
        sha = cm.sha256_hex(data)
        for member, conclusion in (("A", "claim A"), ("B", "claim B")):
            post = Path(self.tmp) / f"post-{member}.json"
            post.write_text(json.dumps({"vote": "propose", "proposal": "x", "questions": [],
                                         "code_reads": [{"path": "src/a.py", "lines": [1, 1],
                                                          "observed_sha256": sha, "symbol": "dup",
                                                          "conclusion": conclusion}]}))
            rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2",
                                   "--mode", "stage", "--member", member, "--generation", "1", "--post-json", post)
            self.assertEqual(rc, 0, err)
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "publish")
        index = json.loads((self.run / "codemap" / "index.json").read_bytes())
        entry = next(iter(index["entries"].values()))
        self.assertEqual(len(entry["reports"]), 2)
        conclusions = {r["conclusion"] for r in entry["reports"]}
        self.assertEqual(conclusions, {"claim A", "claim B"}, "distinct conclusions are never merged/overwritten")

    def test_unbound_report_reason_is_preserved_and_never_retroactively_authenticated(self):
        post = Path(self.tmp) / "post.json"
        post.write_text(json.dumps({"vote": "propose", "proposal": "x", "questions": [],
                                     "code_reads": [{"path": "src/a.py", "lines": [1, 1]}]}))  # no observed_sha256
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2",
               "--mode", "stage", "--member", "A", "--generation", "1", "--post-json", post)
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "publish")
        index = json.loads((self.run / "codemap" / "index.json").read_bytes())
        self.assertEqual(len(index["unbound"]), 1)
        self.assertEqual(index["unbound"][0]["reason"], "no_digest")
        self.assertTrue(index["unbound"][0]["attribution"]["attributed"])
        entry = next(iter(index["entries"].values()))
        self.assertEqual(entry["reports"], [], "a later capture never retroactively binds a digestless claim")


class LookupRequestTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = str(make_project(self.tmp))
        self.run = make_cm_run(self.tmp, self.root)
        items = []
        for n in range(35):
            p = Path(self.root) / "src" / f"f{n:03d}.py"
            p.write_text("x = {}\n".format(n))
            items.append({"path": f"src/f{n:03d}.py"})
        cap = Path(self.tmp) / "cap.json"
        cap.write_text(json.dumps(items))
        rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--capture-json", cap)
        self.assertEqual(rc, 0, err)
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r1", "--mode", "begin", "--raw")

    def test_pagination_is_deterministic_and_terminates(self):
        seen = []
        cursor = None
        for _ in range(10):
            req = {} if cursor is None else {"cursor": cursor}
            rc, out, err = cm_cli("lookup", "--run-dir", self.run, "--task", "t1", "--step", "r1", stdin=json.dumps(req))
            self.assertEqual(rc, 0, err)
            result = json.loads(out)
            self.assertLessEqual(len(result["entries"]), 32)
            seen.extend(e["entry_id"] for e in result["entries"])
            cursor = result["next_cursor"]
            if cursor is None:
                break
        self.assertIsNone(cursor, "pagination must terminate")
        self.assertEqual(len(seen), 35)
        self.assertEqual(len(set(seen)), 35, "no duplicate entries across pages")

    def test_cursor_is_bound_to_its_originating_request(self):
        rc, out, _ = cm_cli("lookup", "--run-dir", self.run, "--task", "t1", "--step", "r1", stdin="{}")
        cursor = json.loads(out)["next_cursor"]
        self.assertIsNotNone(cursor)
        rc, out, err = cm_cli("lookup", "--run-dir", self.run, "--task", "t1", "--step", "r1",
                               stdin=json.dumps({"cursor": cursor, "paths": ["src/f000.py"]}))
        self.assertEqual(rc, 2, "a cursor is not reinterpreted for a different request")

    def test_unknown_request_field_is_rejected(self):
        rc, out, err = cm_cli("lookup", "--run-dir", self.run, "--task", "t1", "--step", "r1", stdin='{"bogus":true}')
        self.assertEqual(rc, 2)

    def test_snapshot_mismatch_is_a_structured_unavailable_result_not_a_crash(self):
        rc, out, err = cm_cli("lookup", "--run-dir", self.run, "--task", "t1", "--step", "r1",
                              stdin=json.dumps({"snapshot_id": "0" * 64}))
        self.assertEqual(rc, 0, err)
        result = json.loads(out)
        self.assertEqual(result["error"], "unavailable_for_this_step")
        self.assertEqual(result["entries"], [])
        self.assertIsNone(result["next_cursor"])

    def test_explicitly_null_typed_request_fields_are_rejected(self):
        for body in ('{"paths":null}', '{"include_evidence":null}', '{"cursor":null}',
                     '{"snapshot_id":null}'):
            rc, out, err = cm_cli("lookup", "--run-dir", self.run, "--task", "t1", "--step", "r1", stdin=body)
            self.assertEqual(rc, 2, body)

    def test_cursor_offset_must_be_a_non_negative_non_boolean_integer(self):
        import base64 as _b64
        snap = json.loads(cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                                 "--task", "t1", "--step", "rX", "--mode", "begin")[1])["snapshot_id"]
        for bad in (-1, True):
            token = _b64.b64encode(cm.canonical_json(
                {"snapshot_id": snap, "request_hash": "x" * 64, "offset": bad})).decode("ascii")
            rc, out, err = cm_cli("lookup", "--run-dir", self.run, "--task", "t1", "--step", "rX",
                                  stdin=json.dumps({"cursor": token}))
            self.assertEqual(rc, 2, bad)


class CaptureJsonOrchestratorTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = str(make_project(self.tmp))
        self.run = make_cm_run(self.tmp, self.root)

    def test_empty_file_zero_range_round_trips(self):
        (Path(self.root) / "src" / "empty.py").write_bytes(b"")
        cap = Path(self.tmp) / "cap.json"
        cap.write_text(json.dumps([{"path": "src/empty.py", "byte_range": [0, 0]}]))
        rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--capture-json", cap)
        self.assertEqual(rc, 0, err)
        self.assertEqual(json.loads(out)["results"][0]["status"], "ok")

    def test_binary_source_round_trips_as_base64_via_lookup_evidence(self):
        data = b"\xff\xfe\x00binary\x01data"
        (Path(self.root) / "src" / "bin.dat").write_bytes(data)
        cap = Path(self.tmp) / "cap.json"
        cap.write_text(json.dumps([{"path": "src/bin.dat"}]))
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--capture-json", cap)
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r1", "--mode", "begin")
        rc, out, err = cm_cli("lookup", "--run-dir", self.run, "--task", "t1", "--step", "r1",
                               stdin='{"include_evidence":true}')
        result = json.loads(out)
        ev = result["entries"][0]["evidence"]
        self.assertEqual(ev["encoding"], "base64")
        self.assertEqual(base64.b64decode(ev["content"]), data)

    def test_does_not_crawl_or_invoke_shell_commands(self):
        (Path(self.root) / "src" / "a.py").write_text("x\n")
        (Path(self.root) / "src" / "b.py").write_text("y\n")
        cap = Path(self.tmp) / "cap.json"
        cap.write_text(json.dumps([{"path": "src/a.py"}]))  # b.py is deliberately not listed
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--capture-json", cap)
        index = json.loads((self.run / "codemap" / "index.json").read_bytes())
        self.assertEqual(len(index["entries"]), 1, "only the explicitly listed path is captured")

    def test_source_tree_is_never_mutated(self):
        (Path(self.root) / "src" / "a.py").write_text("x\n")
        before = tree_fingerprint(self.root)
        cap = Path(self.tmp) / "cap.json"
        cap.write_text(json.dumps([{"path": "src/a.py"}]))
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--capture-json", cap)
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r1", "--mode", "begin")
        cm_cli("locator", "--run-dir", self.run, "--task", "t1", "--step", "r1")
        cm_cli("lookup", "--run-dir", self.run, "--task", "t1", "--step", "r1", stdin="{}")
        self.assertEqual(tree_fingerprint(self.root), before)


class LocatorTests(unittest.TestCase):
    def test_locator_never_dumps_the_index_body(self):
        tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, tmp)
        root = str(make_project(tmp))
        (Path(root) / "src" / "a.py").write_text("x\n")
        run = make_cm_run(tmp, root)
        cm_cli("validate", "--run-dir", run, "--dir", root, "--task", "t1", "--step", "r1", "--mode", "begin", "--raw")
        rc, out, err = cm_cli("locator", "--run-dir", run, "--task", "t1", "--step", "r1")
        self.assertEqual(rc, 0, err)
        self.assertIn("=== CODE MAP ===", out)
        self.assertIn("Inspect the raw evidence", out)
        self.assertNotIn('"entries"', out)
        self.assertNotIn('"sources"', out)


class CodemapReportCliTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = str(make_project(self.tmp))
        (Path(self.root) / "src" / "a.py").write_text("x\ny\n")
        self.run = make_cm_run(self.tmp, self.root)
        (self.run / "prompts").mkdir(parents=True)
        cap = Path(self.tmp) / "cap.json"
        cap.write_text(json.dumps([{"path": "src/a.py"}]))
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--capture-json", cap)

    def run_report(self, *extra):
        return run_cli("codemap_report.py", self.run, *extra)

    def test_help_exits_zero_with_usage(self):
        code, out, _ = self.run_report_help()
        self.assertEqual(code, 0)
        self.assertIn("codemap_report.py <run-dir>", out)

    def run_report_help(self):
        return run_cli("codemap_report.py", "-h")

    def test_reports_distinct_source_identity_not_just_digest_objects(self):
        code, out, _ = self.run_report()
        self.assertEqual(code, 0)
        self.assertIn("Distinct source versions (root+path+resolved_path+digest): 1", out)
        self.assertIn("Distinct display paths: 1", out)
        self.assertIn("Range entries: 1", out)

    def test_captured_and_attested_coverage_are_reported_separately(self):
        code, out, _ = self.run_report()
        captured = [ln for ln in out.splitlines() if ln.startswith("CAPTURED coverage")]
        attested = [ln for ln in out.splitlines() if ln.startswith("ATTESTED coverage")]
        self.assertEqual(len(captured), 1)
        self.assertEqual(len(attested), 1)
        # an orchestrator capture is held evidence, but nobody has attested to reading it
        self.assertIn("4 bytes of indexed ranges", captured[0])
        self.assertIn("0 bytes over 0 versions", attested[0])

    def test_read_and_hashed_bytes_are_counted_separately_from_real_events(self):
        code, out, _ = self.run_report()
        line = [ln for ln in out.splitlines() if ln.startswith("Bytes actually READ")][0]
        # the file is 4 bytes and the capture contract is two complete reads, each hashed
        self.assertIn("READ from sources: 8", line)
        self.assertIn("HASHED: 8", line)

    def test_per_entry_freshness_counts_every_status(self):
        code, out, _ = self.run_report()
        line = [ln for ln in out.splitlines() if ln.startswith("Entry freshness")][0]
        for status in ("current=", "changed=", "missing=", "unreadable=", "unstable=", "unknown="):
            self.assertIn(status, line)

    def test_locator_delivery_counts_only_recorded_boundaries(self):
        # a prompt that merely CONTAINS the delimiter text is never counted: only the boundaries
        # the orchestrator recorded when it actually wrote a locator block are
        (self.run / "prompts" / "t1-r1-A.md").write_text("=== CODE MAP ===\nquoted by an author\n=== END CODE MAP ===\n")
        code, out, _ = self.run_report()
        self.assertIn("Locator delivery: nothing recorded", out)
        self.write_deliveries(
            {"kind": "span", "prompt": "t1-r1-A.md", "offset": 0, "length": 120,
             "attempt": "t1-r1-a1", "site": "prompt"},
            {"kind": "span", "prompt": "t1-r1-A.md", "offset": 500, "length": 120,
             "attempt": "t1-r1-a1", "site": "handover"},
            {"kind": "launched", "prompt": "t1-r1-A.md", "attempt": "t1-r1-a1",
             "prompt_sha256": "a" * 64, "prompt_size": 2000})
        code, out, _ = self.run_report()
        self.assertIn("240 bytes in 2 blocks", out)
        self.assertIn("more than one locator block", out, "duplicate deliveries are counted honestly")
        self.assertIn("handover=120", out)

    def write_deliveries(self, *records):
        (self.run / "codemap" / "deliveries.jsonl").write_text(
            "".join(json.dumps(r) + "\n" for r in records))

    def test_a_prompt_that_was_written_but_never_launched_is_not_delivered(self):
        self.write_deliveries({"kind": "span", "prompt": "t1-r1-A.md", "offset": 0, "length": 120,
                               "attempt": "t1-r1-a1", "site": "prompt"})
        code, out, _ = self.run_report()
        self.assertIn("DELIVERED (recorded span, inside a prompt that was really launched): 0 bytes", out)
        self.assertIn("never launched: 1 (120 bytes)", out)

    def test_a_span_that_does_not_fit_the_launched_prompt_is_reported_as_corrupt(self):
        self.write_deliveries(
            {"kind": "span", "prompt": "t1-r1-A.md", "offset": 9000, "length": 120,
             "attempt": "t1-r1-a1", "site": "prompt"},
            {"kind": "launched", "prompt": "t1-r1-A.md", "attempt": "t1-r1-a1",
             "prompt_sha256": "a" * 64, "prompt_size": 500})
        code, out, _ = self.run_report()
        self.assertIn("do not fit the prompt bytes recorded at launch: 1", out)
        self.assertIn("DELIVERED (recorded span, inside a prompt that was really launched): 0 bytes", out)

    def test_unrecognised_delivery_records_make_the_log_incomplete_not_zero(self):
        self.write_deliveries({"prompt": "t1-r1-A.md", "offset": 0, "length": 120})   # no kind
        code, out, _ = self.run_report()
        self.assertIn("INCOMPLETE", out)

    def test_different_pagination_cursors_are_not_the_same_request(self):
        page1 = {"paths": ["src/a.py"], "cursor": None}
        page2 = {"paths": ["src/a.py"], "cursor": "abc"}
        self.assertNotEqual(codemap_report.normalize_request(page1),
                            codemap_report.normalize_request(page2),
                            "page 2 is a different request, not a repeat of page 1")
        self.assertEqual(codemap_report.normalize_request({"paths": ["src/a.py"]}, "snapA"),
                         codemap_report.normalize_request({"paths": ["src/a.py"], "snapshot_id": "snapA"}),
                         "the effective snapshot a lookup answered from is part of the identity")

    def test_trace_repetition_uses_the_same_normalization_as_lookup(self):
        trace = Path(self.tmp) / "trace2.json"
        trace.write_text(json.dumps({"scope": "test", "complete": True, "requests": [
            {"request": {"paths": ["b", "a"]}, "result": {}},
            {"request": {"paths": ["a", "b"], "include_evidence": False}, "result": {}},
        ]}))
        code, out, _ = self.run_report("--trace", trace)
        self.assertIn("2 total, 1 distinct", out, "order and defaulted fields do not make a new request")

    def test_trace_stale_results_come_from_the_real_response_contract(self):
        trace = Path(self.tmp) / "trace3.json"
        trace.write_text(json.dumps({"scope": "test", "complete": False, "requests": [
            {"request": {"paths": ["a"]},
             "result": {"entries": [{"freshness": {"current_at_snapshot": False}},
                                     {"freshness": {"current_at_snapshot": True}}],
                        "missing": ["z"]}},
            {"request": {"paths": ["q"]}, "result": {"error": "unavailable_for_this_step"}},
        ]}))
        code, out, _ = self.run_report("--trace", trace)
        self.assertIn("1 entries served at a non-current source version (stale), 1 missing selectors, "
                      "1 requests answered 'unavailable'", out)
        self.assertIn("lower bound", out)

    def test_no_trace_is_reported_as_unknown_not_zero(self):
        code, out, _ = self.run_report()
        self.assertIn("UNKNOWN", out)

    def test_trace_supplied_counts_are_reported_with_completeness_label(self):
        trace = Path(self.tmp) / "trace.json"
        trace.write_text(json.dumps({"scope": "test", "complete": True, "requests": [
            {"request": {"paths": ["a"]}, "result": {}},
            {"request": {"paths": ["a"]}, "result": {"missing": ["a"]}},
        ]}))
        code, out, _ = self.run_report("--trace", trace)
        self.assertEqual(code, 0)
        self.assertIn("complete=True", out)
        self.assertIn("2 total, 1 distinct", out)

    def test_never_converts_bytes_to_tokens_or_dollars(self):
        code, out, _ = self.run_report()
        self.assertNotIn("$", out)
        # "token" appears once, only in the disclaimer that no such conversion is performed
        token_lines = [ln for ln in out.lower().splitlines() if "token" in ln]
        self.assertEqual(len(token_lines), 1)
        self.assertIn("never converts byte counts into them", token_lines[0])

    def test_missing_run_dir_exits_nonzero(self):
        code, _, err = run_cli("codemap_report.py", str(Path(self.tmp) / "nope"))
        self.assertNotEqual(code, 0)

    def test_does_not_modify_the_run_directory(self):
        before = tree_fingerprint(self.run)
        self.run_report()
        self.assertEqual(tree_fingerprint(self.run), before)


class PublicationBarrierAndIdempotencyTests(unittest.TestCase):
    """Publication is exactly-once, and only after the recorded completed-step barrier."""

    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = str(make_project(self.tmp))
        self.a = Path(self.root) / "src" / "a.py"
        self.a.write_text("one\ntwo\n")
        self.run = make_cm_run(self.tmp, self.root)

    def begin(self, step, *extra):
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", step, "--mode", "begin", *extra)
        self.assertEqual(rc, 0, err)
        info = json.loads(out)
        self.attempt = info["attempt"]
        return info

    def stage(self, step, member="A", generation=1):
        write_launch(self.run, self.attempt, member, generation)
        post = Path(self.tmp) / "post-{}-{}.json".format(step, member)
        post.write_text(json.dumps({"vote": "propose", "proposal": "x", "questions": [],
                                    "code_reads": [{"path": "src/a.py", "lines": [1, 1],
                                                    "observed_sha256": cm.sha256_hex(self.a.read_bytes()),
                                                    "symbol": "foo", "conclusion": "c"}]}))
        rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1",
                              "--step", step, "--mode", "stage", "--member", member,
                              "--generation", str(generation), "--post-json", post)
        self.assertEqual(rc, 0, err)

    def publish(self, step):
        rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", step, "--mode", "publish")
        self.assertEqual(rc, 0, err)
        return json.loads(out)

    def index(self):
        return json.loads((self.run / "codemap" / "index.json").read_bytes())

    def test_publishing_a_partial_step_is_refused_and_loses_nothing(self):
        self.begin("r2")
        self.stage("r2")
        result = self.publish("r2")
        self.assertEqual(result["status"], "not_publishable")
        self.assertFalse(result["step_complete"])
        self.assertEqual(len(self.index()["entries"]), 0, "nothing was published")
        self.assertTrue(staged_payload(self.run, self.attempt, "A"),
                        "the staged work is retained, not silently dropped")
        # once the step completes and the guard passes, the very same staged work publishes
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        self.assertEqual(self.publish("r2")["status"], "published")
        self.assertEqual(len(self.index()["entries"]), 1)

    def test_pending_verification_never_publishes(self):
        self.begin("r2")
        self.stage("r2")
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        meta_path = self.run / "codemap" / "attempts" / self.attempt / "meta.json"
        meta = json.loads(meta_path.read_bytes())
        meta["status"] = "pending_verification"
        meta_path.write_bytes(cm.canonical_json(meta))
        self.assertEqual(self.publish("r2")["status"], "not_publishable")
        self.assertEqual(len(self.index()["entries"]), 0)

    def test_republishing_the_same_accepted_event_never_duplicates_reports(self):
        self.begin("r2")
        self.stage("r2")
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        self.publish("r2")
        first = self.index()
        self.assertEqual(sum(len(e["reports"]) for e in first["entries"].values()), 1)
        # force a genuine re-merge (not merely the already_published short circuit)
        meta_path = self.run / "codemap" / "attempts" / self.attempt / "meta.json"
        meta = json.loads(meta_path.read_bytes())
        meta["status"] = "guard_ok"
        meta_path.write_bytes(cm.canonical_json(meta))
        self.assertEqual(self.publish("r2")["status"], "published")
        again = self.index()
        self.assertEqual(sum(len(e["reports"]) for e in again["entries"].values()), 1,
                         "the same (accepted event, position) is ingested exactly once")
        self.assertEqual(len(again["unbound"]), len(first["unbound"]))
        self.assertEqual(len(again["diagnostics"]), len(first["diagnostics"]))

    def test_a_new_accepted_event_is_a_distinct_report_even_with_identical_content(self):
        self.begin("r2")
        self.stage("r2", member="A")
        self.stage("r2", member="B")
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        self.publish("r2")
        reports = [r for e in self.index()["entries"].values() for r in e["reports"]]
        self.assertEqual(len(reports), 2)
        self.assertEqual(sorted(r["reader"]["member"] for r in reports), ["A", "B"])

    def test_an_entry_never_borrows_a_validation_that_did_not_cover_it(self):
        """The end-of-step guard covers the sources the frozen view exposed. A source first
        captured DURING the step was not in that guard, so it must not be stamped with that
        validation's id as if it had been verified by it."""
        self.begin("r2")
        self.stage("r2")
        rc, out, _ = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                            "--task", "t1", "--step", "r2", "--mode", "end")
        snap = json.loads(out)["validation_snapshot"]
        self.publish("r2")
        entry = list(self.index()["entries"].values())[0]
        self.assertIsNone(entry["freshness"]["snapshot_id"])
        self.assertEqual(entry["freshness"]["status"], "unverified")
        self.assertNotEqual(entry["freshness"]["snapshot_id"], snap)

    def test_entry_freshness_carries_the_real_validation_snapshot_id(self):
        # publish r2 first, so src/a.py is a known location; the NEXT step's frozen view exposes
        # it, its guard covers it, and that step's end validation really does verify this entry
        self.begin("r2")
        self.stage("r2")
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        self.publish("r2")
        self.begin("r3")
        self.stage("r3")
        rc, out, _ = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                            "--task", "t1", "--step", "r3", "--mode", "end")
        snap = json.loads(out)["validation_snapshot"]
        self.publish("r3")
        entry = list(self.index()["entries"].values())[0]
        self.assertEqual(entry["freshness"]["snapshot_id"], snap)
        self.assertEqual(entry["freshness"]["status"], "current")
        self.assertTrue((self.run / "codemap" / "snapshots" / (snap + ".json")).exists())

    def test_publication_never_references_evidence_the_store_lost(self):
        self.begin("r2")
        self.stage("r2")
        sha = cm.sha256_hex(self.a.read_bytes())
        (self.run / "codemap" / "sources" / (sha + ".json")).unlink()
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        self.publish("r2")
        index = self.index()
        self.assertEqual(len(index["entries"]), 0, "no entry may point at evidence that cannot be produced")
        self.assertIn("missing_staged_source", [d["code"] for d in index["diagnostics"]])

    def test_a_corrupt_stored_object_is_never_repaired_from_todays_file(self):
        self.begin("r2")
        self.stage("r2")
        sha = cm.sha256_hex(self.a.read_bytes())
        obj = self.run / "codemap" / "sources" / (sha + ".json")
        obj.write_text(json.dumps({"schema_version": 1, "sha256": sha, "size": 3,
                                   "encoding": "base64", "data": base64.b64encode(b"zzz").decode()}))
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        self.publish("r2")
        index = self.index()
        self.assertEqual(len(index["entries"]), 0)
        self.assertIn("missing_staged_source", [d["code"] for d in index["diagnostics"]])
        self.assertEqual(json.loads(obj.read_bytes())["data"], base64.b64encode(b"zzz").decode(),
                         "the damaged object is left exactly as found, never rewritten")


class ActiveViewConfinementTests(unittest.TestCase):
    """While a step is owed a decision, every lookup route serves that one frozen view."""

    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = str(make_project(self.tmp))
        self.a = Path(self.root) / "src" / "a.py"
        self.a.write_text("one\ntwo\n")
        self.run = make_cm_run(self.tmp, self.root)
        self.state = {"config": {"dir": self.root}, "codemap_pending": None}
        self.write_state()
        # a published round-2 attempt with a full, attributed report
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "begin")
        post = Path(self.tmp) / "post.json"
        post.write_text(json.dumps({"vote": "propose", "proposal": "x", "questions": [],
                                    "code_reads": [{"path": "src/a.py", "lines": [1, 1],
                                                    "observed_sha256": cm.sha256_hex(self.a.read_bytes()),
                                                    "symbol": "foo", "conclusion": "secret conclusion"}]}))
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2",
               "--mode", "stage", "--member", "A", "--generation", "1", "--post-json", post)
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "publish")
        self.full = json.loads(cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                                      "--task", "t2", "--step", "r9", "--mode", "begin")[1])
        # ...and a NEW task's round 1, which must be raw-only
        self.raw = json.loads(cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t2",
                                     "--step", "r1", "--mode", "begin", "--raw")[1])
        self.state["codemap_pending"] = {"task": "t2", "step": "r1", "attempt": self.raw["attempt"]}
        self.write_state()

    def write_state(self):
        (self.run / "state.json").write_text(json.dumps(self.state))

    def lookup(self, *args, **kw):
        return cm_cli("lookup", "--run-dir", self.run, *args, **kw)

    def test_active_raw_step_hides_conclusions_and_reader_identity(self):
        rc, out, err = self.lookup("--task", "t2", "--step", "r1", stdin='{"include_conclusions":true}')
        self.assertEqual(rc, 0, err)
        result = json.loads(out)
        self.assertEqual(result["snapshot_id"], self.raw["snapshot_id"])
        self.assertTrue(result["entries"])
        self.assertNotIn("secret conclusion", out)
        for e in result["entries"]:
            self.assertEqual(e["reports"], [])

    def test_naming_another_snapshot_cannot_escape_the_active_view(self):
        rc, out, err = self.lookup("--snapshot", self.full["snapshot_id"], stdin='{"include_conclusions":true}')
        self.assertEqual(rc, 0, err)
        result = json.loads(out)
        self.assertEqual(result["error"], "unavailable_for_this_step")
        self.assertEqual(result["snapshot_id"], self.raw["snapshot_id"])
        self.assertNotIn("secret conclusion", out)

    def test_naming_another_task_step_cannot_escape_the_active_view(self):
        rc, out, err = self.lookup("--task", "t2", "--step", "r9", stdin='{"include_conclusions":true}')
        self.assertEqual(rc, 0, err)
        self.assertEqual(json.loads(out)["error"], "unavailable_for_this_step")
        self.assertNotIn("secret conclusion", out)

    def test_outside_an_active_attempt_a_historical_snapshot_is_served_exactly(self):
        self.state["codemap_pending"] = None
        self.write_state()
        rc, out, err = self.lookup("--snapshot", self.raw["snapshot_id"], stdin="{}")
        self.assertEqual(rc, 0, err)
        result = json.loads(out)
        self.assertEqual(result["snapshot_id"], self.raw["snapshot_id"])
        self.assertNotIn("secret conclusion", out, "a raw view stays raw forever")

    def test_an_unknown_snapshot_is_rejected_explicitly_not_substituted(self):
        self.state["codemap_pending"] = None
        self.write_state()
        rc, out, err = self.lookup("--snapshot", "f" * 64, stdin="{}")
        self.assertEqual(rc, 0, err)
        self.assertEqual(json.loads(out)["error"], "unavailable_snapshot")
        self.assertEqual(json.loads(out)["entries"], [])

    def test_the_locator_advertises_a_command_that_reaches_the_named_view(self):
        rc, out, err = cm_cli("locator", "--run-dir", self.run, "--task", "t2", "--step", "r1")
        self.assertEqual(rc, 0, err)
        self.assertIn(self.raw["snapshot_id"], out)
        self.assertNotIn("REPO_ROOT", out)
        cmd = [ln for ln in out.splitlines() if ln.startswith("example lookup:")][0]
        self.assertIn(str(Path(cm.__file__).resolve()), cmd)
        self.assertTrue(Path(str(Path(cm.__file__).resolve())).exists())

    def test_an_arbitrary_dir_is_refused_when_the_run_state_names_config_dir(self):
        other = Path(self.tmp) / "elsewhere"
        (other / "src").mkdir(parents=True)
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", str(other),
                              "--task", "t3", "--step", "r1", "--mode", "begin")
        self.assertEqual(rc, 2)
        self.assertIn("config.dir", err)


class RootAndNulDataTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = str(make_project(self.tmp))
        self.run = make_cm_run(self.tmp, self.root)

    def test_display_path_spellings_do_not_fragment_identity(self):
        self.assertEqual(cm.normalize_display_path("./src/a.py"), "src/a.py")
        self.assertEqual(cm.normalize_display_path("src//./a.py"), "src/a.py")

    def test_nul_bearing_source_is_stored_base64_and_never_line_addressed(self):
        data = b"a\x00b\n"
        (Path(self.root) / "src" / "n.dat").write_bytes(data)
        post = Path(self.tmp) / "post.json"
        post.write_text(json.dumps({"vote": "agree", "questions": [],
                                    "code_reads": [{"path": "src/n.dat", "lines": [1, 1],
                                                    "observed_sha256": cm.sha256_hex(data)}]}))
        attempt = json.loads(cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1",
                                    "--step", "r2", "--mode", "begin")[1])["attempt"]
        write_launch(self.run, attempt, "A")
        rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2",
                              "--mode", "stage", "--member", "A", "--generation", "1", "--post-json", post)
        self.assertEqual(rc, 0, err)
        staged = staged_payload(self.run, attempt, "A")
        self.assertEqual([u["reason"] for u in staged["unbound"]],
                         ["line_range_not_applicable_to_binary_source"])
        shell = list(staged["entries"].values())[0]["shell"]
        self.assertIsNone(shell["lines"], "binary source line metadata is null")
        obj = json.loads((self.run / "codemap" / "sources" /
                          (cm.sha256_hex(data) + ".json")).read_bytes())
        self.assertEqual(obj["encoding"], "base64")
        self.assertFalse(obj["text_safe"])
        self.assertEqual(base64.b64decode(obj["data"]), data)

    def test_all_full_sources_including_plain_text_are_stored_as_labelled_base64(self):
        store = cm.Store(self.run)
        store.ensure_dirs()
        sha = cm.sha256_hex(b"plain text\n")
        store.write_source(sha, b"plain text\n")
        obj = json.loads((store.sources_dir / (sha + ".json")).read_bytes())
        self.assertEqual(obj["encoding"], "base64")
        self.assertTrue(obj["text_safe"])
        self.assertEqual(store.read_source(sha), b"plain text\n")

    def test_a_same_size_edit_is_detected_because_detection_is_content_only(self):
        a = Path(self.root) / "src" / "a.py"
        a.write_text("aaaa\n")
        before = os.stat(a)
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "begin")
        post = Path(self.tmp) / "post.json"
        post.write_text(json.dumps({"vote": "agree", "questions": [],
                                    "code_reads": [{"path": "src/a.py",
                                                    "observed_sha256": cm.sha256_hex(a.read_bytes())}]}))
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2",
               "--mode", "stage", "--member", "A", "--generation", "1", "--post-json", post)
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "publish")
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r3", "--mode", "begin")
        a.write_text("bbbb\n")                                   # same size
        os.utime(a, (before.st_atime, before.st_mtime))           # restored mtime
        self.assertEqual(os.stat(a).st_size, before.st_size)
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", "r3", "--mode", "end")
        self.assertEqual(json.loads(out)["guard_status"], "changed",
                         "the guard hashes content and never consults size or mtime")

    def test_a_missing_guard_file_is_a_verification_failure_not_an_empty_pass(self):
        (Path(self.root) / "src" / "a.py").write_text("x\n")
        attempt = json.loads(cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1",
                                    "--step", "r2", "--mode", "begin")[1])["attempt"]
        write_launch(self.run, attempt, "A")
        (self.run / "codemap" / "attempts" / attempt / "guard.json").unlink()
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", "r2", "--mode", "end")
        self.assertEqual(rc, 1)
        self.assertIn("evidence/verification failure", err)

    def test_a_missing_index_is_recovered_only_from_a_recorded_verified_snapshot(self):
        (Path(self.root) / "src" / "a.py").write_text("x\n")
        cap = Path(self.tmp) / "cap.json"
        cap.write_text(json.dumps([{"path": "src/a.py"}]))
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--capture-json", cap)
        before = json.loads((self.run / "codemap" / "index.json").read_bytes())
        self.assertTrue(before["entries"])
        head = json.loads((self.run / "codemap" / "index-head.json").read_bytes())
        snap = self.run / "codemap" / "index-snapshots" / (head["index_snapshot_id"] + ".json")
        self.assertTrue(snap.exists())
        (self.run / "codemap" / "index.json").unlink()
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", "r3", "--mode", "begin")
        self.assertEqual(rc, 0, err)
        self.assertEqual(json.loads((self.run / "codemap" / "index.json").read_bytes())["entries"],
                         before["entries"], "recovered byte-for-byte from the recorded snapshot")

    def test_a_tampered_index_snapshot_is_refused_rather_than_trusted(self):
        (Path(self.root) / "src" / "a.py").write_text("x\n")
        cap = Path(self.tmp) / "cap.json"
        cap.write_text(json.dumps([{"path": "src/a.py"}]))
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--capture-json", cap)
        head = json.loads((self.run / "codemap" / "index-head.json").read_bytes())
        snap = self.run / "codemap" / "index-snapshots" / (head["index_snapshot_id"] + ".json")
        snap.write_bytes(cm.canonical_json({"schema_version": 1, "entries": {"forged": {}}}))
        (self.run / "codemap" / "index.json").unlink()
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", "r3", "--mode", "begin")
        self.assertEqual(rc, 1)
        self.assertIn("does not match its own digest", err)

    def test_a_missing_index_with_no_recorded_snapshot_is_an_error_not_an_empty_history(self):
        (Path(self.root) / "src" / "a.py").write_text("x\n")
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "begin")
        (self.run / "codemap" / "index.json").unlink()
        (self.run / "codemap" / "index-head.json").unlink()
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", "r3", "--mode", "begin")
        self.assertEqual(rc, 1)
        self.assertIn("prior code-map activity", err)

    def test_a_tampered_snapshot_is_rejected_on_read(self):
        (Path(self.root) / "src" / "a.py").write_text("x\n")
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "begin")
        store = cm.Store(self.run)
        snap = sorted(store.snapshots_dir.glob("*.json"))[0]
        snap.write_bytes(cm.canonical_json({"schema_version": 1, "sources": [{"path": "forged"}]}))
        with self.assertRaises(cm.CodemapError):
            store.read_snapshot(snap.stem)



class HistoricalBindingIdentityTests(unittest.TestCase):
    """A digest proves only that SOME file held those bytes. Binding a claim to a path requires a
    recorded version of THAT path holding them."""

    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = str(make_project(self.tmp))
        self.a = Path(self.root) / "src" / "a.py"
        self.b = Path(self.root) / "src" / "b.py"
        self.run = make_cm_run(self.tmp, self.root)

    def begin(self, step):
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", step, "--mode", "begin")
        self.assertEqual(rc, 0, err)
        self.attempt = json.loads(out)["attempt"]
        write_launch(self.run, self.attempt, "A")
        return self.attempt

    def stage(self, step, path, digest, member="A"):
        write_launch(self.run, self.attempt, member)
        post = Path(self.tmp) / "post-{}-{}.json".format(step, member)
        post.write_text(json.dumps({"vote": "agree", "questions": [],
                                    "code_reads": [{"path": path, "observed_sha256": digest}]}))
        rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1",
                              "--step", step, "--mode", "stage", "--member", member,
                              "--generation", "1", "--post-json", post)
        self.assertEqual(rc, 0, err)
        return staged_payload(self.run, self.attempt, member)

    def test_a_digest_captured_from_another_file_never_authenticates_this_path(self):
        self.b.write_text("B CONTENT\n")
        b_digest = cm.sha256_hex(self.b.read_bytes())
        self.begin("r2")
        self.stage("r2", "src/b.py", b_digest)          # records the version for src/b.py
        # now a claim about src/a.py quoting src/b.py's digest: the object exists, the identity
        # does not, so the claim must stay unbound
        self.a.write_text("A CONTENT\n")
        self.begin("r3")
        staged = self.stage("r3", "src/a.py", b_digest)
        self.assertEqual([u["reason"] for u in staged["unbound"]], ["digest_mismatch"])
        self.assertEqual([r for e in staged["entries"].values() for r in e["reports"]], [],
                         "equal bytes somewhere else are not evidence about this path")
        entry = list(staged["entries"].values())[0]
        self.assertEqual(entry["shell"]["source_sha256"], cm.sha256_hex(self.a.read_bytes()),
                         "the entry describes today's src/a.py, never src/b.py's version")

    def test_a_historical_version_of_this_path_does_bind_and_keeps_its_own_resolved_path(self):
        real = Path(self.root) / "src" / "real1.py"
        real.write_text("V1\n")
        link = Path(self.root) / "src" / "a.py"
        link.symlink_to("real1.py")
        v1 = cm.sha256_hex(b"V1\n")
        self.begin("r2")
        self.stage("r2", "src/a.py", v1)
        # retarget to a DIFFERENT file with the same content: today's resolved_path changed
        real2 = Path(self.root) / "src" / "real2.py"
        real2.write_text("V2\n")
        link.unlink()
        link.symlink_to("real2.py")
        self.begin("r3")
        staged = self.stage("r3", "src/a.py", v1)
        entry = list(staged["entries"].values())[0]
        self.assertTrue(entry["historical"])
        self.assertEqual(entry["shell"]["source_sha256"], v1)
        self.assertTrue(entry["shell"]["resolved_path"].endswith("real1.py"),
                        "a historical version keeps the path as it resolved THEN, not today's target")
        self.assertEqual([r["observed_sha256"] for e in staged["entries"].values()
                          for r in e["reports"]], [v1])

    def test_historical_evidence_survives_the_live_file_being_deleted(self):
        self.a.write_text("ONLY VERSION\n")
        v = cm.sha256_hex(self.a.read_bytes())
        self.begin("r2")
        self.stage("r2", "src/a.py", v)
        self.a.unlink()                                  # the live file is gone
        self.begin("r3")
        staged = self.stage("r3", "src/a.py", v)
        self.assertEqual(staged["unbound"], [], "recorded history does not depend on the live file")
        entry = list(staged["entries"].values())[0]
        self.assertTrue(entry["historical"])
        self.assertEqual(entry["shell"]["source_sha256"], v)

    def test_a_historical_binding_is_never_published_as_current(self):
        self.a.write_text("V1\n")
        v1 = cm.sha256_hex(self.a.read_bytes())
        self.begin("r2")
        self.stage("r2", "src/a.py", v1)
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "publish")
        self.a.write_text("V2 IS LONGER\n")
        self.begin("r3")
        self.stage("r3", "src/a.py", v1)
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r3", "--mode", "end")
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r3", "--mode", "publish")
        index = json.loads((self.run / "codemap" / "index.json").read_bytes())
        hist = [e for e in index["entries"].values() if e["source_sha256"] == v1]
        self.assertTrue(hist)
        for e in hist:
            self.assertFalse(e["freshness"]["current_at_snapshot"],
                             "a version the path no longer holds is never labelled current")
            self.assertNotEqual(e["freshness"]["status"], "current")


class ValidationCoverageTests(unittest.TestCase):
    """A freshness snapshot attests to the exact source version it re-captured. An entry gets
    "current" only when root, display path, resolved path AND digest all match that verified
    version — a bare path match is not coverage."""

    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = os.path.realpath(str(make_project(self.tmp)))
        self.run = make_cm_run(self.tmp, self.root)

    def begin(self, step):
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", step, "--mode", "begin")
        self.assertEqual(rc, 0, err)
        self.attempt = json.loads(out)["attempt"]
        return self.attempt

    def stage(self, step, path, digest, member="A"):
        write_launch(self.run, self.attempt, member)
        post = Path(self.tmp) / "post-{}-{}.json".format(step, member)
        post.write_text(json.dumps({"vote": "agree", "questions": [],
                                    "code_reads": [{"path": path, "observed_sha256": digest}]}))
        rc, _, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1",
                            "--step", step, "--mode", "stage", "--member", member,
                            "--generation", "1", "--post-json", post)
        self.assertEqual(rc, 0, err)

    def end_and_publish(self, step):
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", step, "--mode", "end")
        self.assertEqual(rc, 0, err)
        guard_status = json.loads(out)["guard_status"]
        rc, out, err = cm_cli("ingest", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", step, "--mode", "publish")
        self.assertEqual(rc, 0, err)
        return guard_status, json.loads(out)

    def index(self):
        return json.loads((self.run / "codemap" / "index.json").read_bytes())

    def test_a_version_the_validation_did_not_verify_is_never_labelled_current(self):
        """Old bytes are exposed and guarded; new bytes are staged at the SAME path; the old bytes
        are then restored so the guard passes. The guard verified V1 — it says nothing whatever
        about V2, which must not inherit its snapshot."""
        a = Path(self.root) / "src" / "a.py"
        a.write_text("V1\n")
        v1 = cm.sha256_hex(a.read_bytes())
        self.begin("r2")
        self.stage("r2", "src/a.py", v1)
        self.assertEqual(self.end_and_publish("r2")[0], "current")

        self.begin("r3")                      # the guard now holds V1 of src/a.py
        a.write_text("V2\n")                  # the file changes mid-step
        v2 = cm.sha256_hex(a.read_bytes())
        self.stage("r3", "src/a.py", v2)      # a member reports the new bytes
        a.write_text("V1\n")                  # ...and the original bytes come back
        status, _ = self.end_and_publish("r3")
        self.assertEqual(status, "current", "the guarded version really is back in place")

        index = self.index()
        snap = json.loads((self.run / "codemap" / "attempts" / self.attempt / "meta.json").read_bytes())
        v2_entries = [e for e in index["entries"].values() if e["source_sha256"] == v2]
        self.assertTrue(v2_entries, "the V2 claim is still published as evidence")
        for e in v2_entries:
            self.assertNotEqual(e["freshness"]["status"], "current")
            self.assertFalse(e["freshness"]["current_at_snapshot"])
            self.assertIsNone(e["freshness"]["snapshot_id"],
                              "an entry never borrows a snapshot that did not cover its version")
            self.assertNotEqual(e["freshness"]["snapshot_id"], snap.get("validation_snapshot_id"))
        # and the location state is the END VALIDATION's, not the earlier staging observation
        loc = index["locations"]["src/a.py"]
        self.assertEqual(loc["source_sha256"], v1)
        self.assertEqual(loc["status"], "current")
        self.assertEqual(loc["snapshot_id"], snap.get("validation_snapshot_id"))

    def test_equal_bytes_behind_a_different_resolved_path_are_not_covered_either(self):
        """The pure resolved-path mismatch: identical content, different real file. The digest
        alone would match the verified version; the identity does not."""
        t1 = Path(self.root) / "src" / "t1.py"
        t2 = Path(self.root) / "src" / "t2.py"
        t1.write_text("SAME\n")
        t2.write_text("SAME\n")
        link = Path(self.root) / "src" / "link.py"
        link.symlink_to("t1.py")
        same = cm.sha256_hex(b"SAME\n")
        self.begin("r2")
        self.stage("r2", "src/link.py", same)
        self.assertEqual(self.end_and_publish("r2")[0], "current")

        self.begin("r3")                      # guard: src/link.py -> .../t1.py
        link.unlink(); link.symlink_to("t2.py")
        self.stage("r3", "src/link.py", same)  # equal bytes, but resolved to t2.py
        link.unlink(); link.symlink_to("t1.py")
        status, _ = self.end_and_publish("r3")
        self.assertEqual(status, "current")

        index = self.index()
        by_resolved = [e for e in index["entries"].values() if e["resolved_path"].endswith("t2.py")]
        self.assertTrue(by_resolved, "the t2 claim is published as evidence")
        for e in by_resolved:
            self.assertNotEqual(e["freshness"]["status"], "current",
                                "same bytes behind another real file is not the verified version")
            self.assertIsNone(e["freshness"]["snapshot_id"])
        self.assertTrue(index["locations"]["src/link.py"]["resolved_path"].endswith("t1.py"),
                        "the end validation's resolved path is final, not the staged observation")


class AcceptedEventImmutabilityTests(unittest.TestCase):
    """An accepted event is staged once; re-ingesting it never re-decides anything."""

    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = str(make_project(self.tmp))
        self.a = Path(self.root) / "src" / "a.py"
        self.a.write_text("one\ntwo\n")
        self.run = make_cm_run(self.tmp, self.root)
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", "r2", "--mode", "begin")
        self.attempt = json.loads(out)["attempt"]

    def ingest(self, post, member="A", generation=1, launch=None):
        args = ["ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1",
                "--step", "r2", "--mode", "stage", "--member", member,
                "--generation", str(generation), "--post-json", post]
        if launch is not None:
            args += ["--launch-id", launch]
        return cm_cli(*args)

    def test_a_replacement_launch_in_the_same_attempt_keeps_its_own_generation(self):
        """The defect: a member fails at generation 1 with no accepted reply, is replaced, and is
        launched again inside the SAME attempt. The replacement's reply belongs to generation 2 —
        it must never be bound and authenticated as the generation-1 session that never replied."""
        first = write_launch(self.run, self.attempt, "A", generation=1)
        second = write_launch(self.run, self.attempt, "A", generation=2, launch_seq=2,
                              launch_id="A-s2")
        digest = cm.sha256_hex(self.a.read_bytes())
        post = Path(self.tmp) / "replacement.json"
        post.write_text(json.dumps({"vote": "agree", "questions": [],
                                    "code_reads": [{"path": "src/a.py", "lines": [1, 1],
                                                    "observed_sha256": digest,
                                                    "conclusion": "the replacement read it"}]}))
        rc, out, err = self.ingest(post, generation=2, launch=second)
        self.assertEqual(rc, 0, err)
        staged = staged_payloads(self.run, self.attempt, "A")
        self.assertEqual(len(staged), 1)
        staged = staged[0]
        self.assertTrue(staged["attributed"])
        self.assertEqual(staged["attribution"]["generation"], 2,
                         "the reply belongs to the launch that produced it")
        self.assertEqual(staged["attribution"]["launch_id"], second)
        self.assertEqual(staged["attribution"]["launch_seq"], 2)
        self.assertEqual([], [d for d in staged["diagnostics"]
                              if d["code"] == "generation_mismatch_with_launch_record"])
        reports = [r for e in staged["entries"].values() for r in e["reports"]]
        self.assertEqual([r["reader"]["generation"] for r in reports], [2],
                         "the bound report is attributed to generation 2")
        meta = accepted_meta(self.run, self.attempt, staged["event_id"])
        self.assertIsNotNone(meta, "the acceptance metadata is durable, addressed by its event id")
        self.assertEqual(meta["generation"], 2)
        self.assertEqual(meta["launch_id"], second)
        # the original launch record is immutable: the replacement never rewrote it
        rec = json.loads((Path(self.run) / "codemap" / "attempts" / self.attempt / "launches"
                          / (first + ".json")).read_bytes())
        self.assertEqual(rec["generation"], 1)
        self.assertEqual(rec["launch_seq"], 1)

    def test_an_explicit_launch_selector_never_falls_back_to_another_record(self):
        """A selector naming a launch the orchestrator never recorded authenticates nothing: the
        bytes are kept, but no other record may stand in for the missing one."""
        write_launch(self.run, self.attempt, "A", generation=1)
        post = Path(self.tmp) / "unrecorded.json"
        post.write_text(json.dumps({"vote": "agree", "questions": [],
                                    "code_reads": [{"path": "src/a.py", "lines": [1, 1],
                                                    "observed_sha256": cm.sha256_hex(self.a.read_bytes())}]}))
        rc, out, err = self.ingest(post, generation=2, launch="A-s2")
        self.assertEqual(rc, 0, err)
        staged = staged_payload(self.run, self.attempt, "A")
        self.assertFalse(staged["attributed"])
        self.assertIsNone(staged["attribution"]["generation"],
                          "no other launch record may be relabelled into this one")
        self.assertIn("no_launch_record_for_launch", [d["code"] for d in staged["diagnostics"]])
        self.assertEqual(staged["unbound"][0]["reason"], "unattributed_accepted_event")
        archive = Path(self.run) / "codemap" / "attempts" / self.attempt / "accepted"
        self.assertTrue((archive / (staged["accepted_sha256"] + ".json")).exists(),
                        "the accepted bytes are preserved even when nothing authenticates them")

    def test_selector_less_staging_is_unattributed_when_the_member_has_two_launches(self):
        """The defect: with two launch records for the member and no selector, staging read "the"
        member-level record and authenticated a generation-2 reply as generation 1. Nothing
        identifies which launch produced these bytes, so nothing may authenticate them: the event
        is preserved in full, unattributed, and its reports stay unbound."""
        write_launch(self.run, self.attempt, "A", generation=1)
        write_launch(self.run, self.attempt, "A", generation=2, launch_seq=2, launch_id="A-s2")
        digest = cm.sha256_hex(self.a.read_bytes())
        post = Path(self.tmp) / "ambiguous.json"
        post.write_text(json.dumps({"vote": "agree", "questions": [],
                                    "code_reads": [{"path": "src/a.py", "lines": [1, 1],
                                                    "observed_sha256": digest}]}))
        rc, out, err = self.ingest(post, generation=2)        # no --launch-id
        self.assertEqual(rc, 0, err)
        staged = staged_payload(self.run, self.attempt, "A")
        self.assertFalse(staged["attributed"])
        self.assertIsNone(staged["attribution"]["generation"],
                          "the caller's own generation is not authentication")
        self.assertIn("ambiguous_launch_records_for_member", [d["code"] for d in staged["diagnostics"]])
        self.assertEqual([u["reason"] for u in staged["unbound"]], ["unattributed_accepted_event"])
        self.assertEqual([r for e in staged["entries"].values() for r in e["reports"]], [],
                         "nothing it claims becomes a bound finding")
        archive = Path(self.run) / "codemap" / "attempts" / self.attempt / "accepted"
        self.assertTrue((archive / (staged["accepted_sha256"] + ".json")).exists(),
                        "the accepted bytes are preserved in full")

    def test_a_single_launch_still_authenticates_a_selector_less_reply(self):
        """The compatibility path the ambiguity rule must not break: one launch is unambiguous."""
        write_launch(self.run, self.attempt, "A", generation=3)
        post = Path(self.tmp) / "single.json"
        post.write_text(json.dumps({"vote": "agree", "questions": []}))
        self.assertEqual(self.ingest(post, generation=3)[0], 0)
        staged = staged_payload(self.run, self.attempt, "A")
        self.assertTrue(staged["attributed"])
        self.assertEqual(staged["attribution"]["generation"], 3)

    def test_the_association_names_the_event_the_live_post_was_accepted_as(self):
        """Two launches, byte-identical tails: member plus tail digest matches BOTH events, so only
        the association written at acceptance can say which one this live post is."""
        first = write_launch(self.run, self.attempt, "A", generation=1)
        second = write_launch(self.run, self.attempt, "A", generation=2, launch_seq=2,
                              launch_id="A-s2")
        post = Path(self.tmp) / "t1-r2-A.json"
        post.write_text(json.dumps({"vote": "agree", "questions": []}))
        self.assertEqual(self.ingest(post, generation=1, launch=first)[0], 0)
        self.assertEqual(self.ingest(post, generation=2, launch=second)[0], 0)
        staged = staged_payloads(self.run, self.attempt, "A")
        self.assertEqual(len({s["accepted_sha256"] for s in staged}), 1,
                         "the two events really are byte-identical tails of the same member")
        assoc = post_assoc(self.run, self.attempt, post.name)
        by_gen = {s["attribution"]["generation"]: s for s in staged}
        self.assertEqual(assoc["event_id"], by_gen[2]["event_id"],
                         "the association names the event this file was last accepted as")
        self.assertEqual(assoc["generation"], 2)
        self.assertEqual(assoc["launch_id"], second)
        self.assertEqual(accepted_meta(self.run, self.attempt, assoc["event_id"])["generation"], 2)

    def test_identical_tails_from_two_launches_are_two_accepted_events(self):
        first = write_launch(self.run, self.attempt, "A", generation=1)
        second = write_launch(self.run, self.attempt, "A", generation=2, launch_seq=2,
                              launch_id="A-s2")
        post = Path(self.tmp) / "same-tail.json"
        post.write_text(json.dumps({"vote": "agree", "questions": []}))
        self.assertEqual(self.ingest(post, generation=1, launch=first)[0], 0)
        self.assertEqual(self.ingest(post, generation=2, launch=second)[0], 0)
        staged = staged_payloads(self.run, self.attempt, "A")
        self.assertEqual(len(staged), 2, "byte-identical tails from two launches are two events")
        self.assertNotEqual(staged[0]["event_id"], staged[1]["event_id"])
        self.assertEqual(sorted(s["attribution"]["generation"] for s in staged), [1, 2],
                         "neither the old reply nor the new one is relabelled")

    def test_restaging_one_launch_keeps_its_metadata_and_does_no_work(self):
        launch = write_launch(self.run, self.attempt, "A", generation=2, launch_seq=2,
                              launch_id="A-s2")
        post = Path(self.tmp) / "restage.json"
        post.write_text(json.dumps({"vote": "agree", "questions": [],
                                    "code_reads": [{"path": "src/a.py",
                                                    "observed_sha256": cm.sha256_hex(self.a.read_bytes())}]}))
        self.ingest(post, generation=2, launch=launch)
        before = staged_payload(self.run, self.attempt, "A")
        self.ingest(post, generation=2, launch=launch)
        self.assertEqual(staged_payload(self.run, self.attempt, "A"), before,
                         "the staged decisions of an already-staged launch are frozen")
        reingest = [e for e in cm.Store(self.run).read_events() if e["kind"] == "stage_reingest"]
        self.assertEqual(len(reingest), 1)
        self.assertEqual(reingest[0]["stats"]["bytes_read"], 0, "no file was re-captured")
        self.assertEqual(reingest[0]["generation"], 2)

    def test_an_accepted_reply_keeps_its_generation_when_the_member_advances_afterwards(self):
        """The generation-1 reply was accepted; only afterwards did the member hand over. Nothing
        about the later generation may touch the event that was already accepted."""
        first = write_launch(self.run, self.attempt, "A", generation=1)
        post = Path(self.tmp) / "early.json"
        post.write_text(json.dumps({"vote": "agree", "questions": []}))
        self.ingest(post, generation=1, launch=first)
        write_launch(self.run, self.attempt, "A", generation=2, launch_seq=2, launch_id="A-s2")
        staged = staged_payloads(self.run, self.attempt, "A")
        self.assertEqual(len(staged), 1)
        self.assertEqual(staged[0]["attribution"]["generation"], 1)
        self.assertEqual(staged[0]["attribution"]["launch_id"], first)
        meta = accepted_meta(self.run, self.attempt, staged[0]["event_id"])
        self.assertEqual(meta["generation"], 1)

    def test_restaging_after_the_source_changed_never_turns_unmatched_into_bound(self):
        write_launch(self.run, self.attempt, "A")
        post = Path(self.tmp) / "post.json"
        stale_digest = cm.sha256_hex(b"SOMETHING ELSE\n")
        post.write_text(json.dumps({"vote": "agree", "questions": [],
                                    "code_reads": [{"path": "src/a.py", "observed_sha256": stale_digest}]}))
        self.ingest(post)
        first = staged_payload(self.run, self.attempt, "A")
        self.assertEqual([u["reason"] for u in first["unbound"]], ["digest_mismatch"])
        # the file now really does hold the claimed bytes — replaying the SAME accepted event must
        # not retroactively authenticate a claim that was unmatched when it was accepted
        self.a.write_bytes(b"SOMETHING ELSE\n")
        self.ingest(post)
        again = staged_payload(self.run, self.attempt, "A")
        self.assertEqual(again, first, "the staged decision is frozen at acceptance time")

    def test_reingestion_is_recorded_as_logical_work_with_no_capture(self):
        write_launch(self.run, self.attempt, "A")
        post = Path(self.tmp) / "post.json"
        post.write_text(json.dumps({"vote": "agree", "questions": [],
                                    "code_reads": [{"path": "src/a.py",
                                                    "observed_sha256": cm.sha256_hex(self.a.read_bytes())}]}))
        self.ingest(post)
        self.ingest(post)
        store = cm.Store(self.run)
        kinds = [e["kind"] for e in store.read_events()]
        self.assertEqual(kinds.count("stage"), 1)
        self.assertEqual(kinds.count("stage_reingest"), 1)
        reingest = [e for e in store.read_events() if e["kind"] == "stage_reingest"][0]
        self.assertEqual(reingest["stats"]["bytes_read"], 0, "no file was read a second time")

    def test_two_authors_with_identical_malformed_tails_keep_both_diagnostics(self):
        for m in ("A", "B"):
            write_launch(self.run, self.attempt, m)
        post = Path(self.tmp) / "same.json"
        post.write_text(json.dumps({"vote": "agree", "questions": [],
                                    "code_reads": [{"path": "src/a.py", "bogus_key": 1}]}))
        self.ingest(post, member="A")
        self.ingest(post, member="B")     # byte-identical tail, different author
        cm_cli("validate", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "end")
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r2", "--mode", "publish")
        index = json.loads((self.run / "codemap" / "index.json").read_bytes())
        diags = [d for d in index["diagnostics"] if d["code"] == "malformed_code_reads_item"]
        self.assertEqual(sorted(d["attribution"]["member"] for d in diags), ["A", "B"],
                         "one author's identical tail never suppresses the other's diagnostic")

    def test_a_genuinely_new_event_with_the_same_tail_is_a_distinct_event(self):
        write_launch(self.run, self.attempt, "A")
        post = Path(self.tmp) / "post.json"
        post.write_text(json.dumps({"vote": "agree", "questions": []}))
        self.ingest(post)
        first = sorted((Path(self.run) / "codemap" / "attempts" / self.attempt / "staged").glob("*.json"))
        # a replay in a NEW attempt: same member, same bytes, different accepted event
        rc, out, err = cm_cli("validate", "--run-dir", self.run, "--dir", self.root,
                              "--task", "t1", "--step", "r3", "--mode", "begin")
        attempt2 = json.loads(out)["attempt"]
        write_launch(self.run, attempt2, "A")
        cm_cli("ingest", "--run-dir", self.run, "--dir", self.root, "--task", "t1", "--step", "r3",
               "--mode", "stage", "--member", "A", "--generation", "1", "--post-json", post)
        second = sorted((Path(self.run) / "codemap" / "attempts" / attempt2 / "staged").glob("*.json"))
        self.assertEqual(len(first), 1)
        self.assertEqual(len(second), 1)
        self.assertNotEqual(json.loads(first[0].read_bytes())["event_id"],
                            json.loads(second[0].read_bytes())["event_id"])


class CaptureSeamTests(unittest.TestCase):
    """Deterministic tests at the real open/read/stat seams."""

    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp)
        self.root = os.path.realpath(str(make_project(self.tmp)))
        self.a = Path(self.root) / "src" / "a.py"
        self.a.write_text("body\n")

    def test_an_absolute_path_is_rejected_on_the_original_spelling_not_normalised_away(self):
        with self.assertRaises(cm.CaptureError) as ctx:
            cm.validated_display_path("/b")
        self.assertEqual(ctx.exception.reason, "absolute_path")
        # and the normaliser alone would have silently turned it into a relative path
        self.assertEqual(cm.normalize_display_path("/b"), "b")

    def test_an_embedded_nul_path_is_a_per_item_reason_not_an_aborting_valueerror(self):
        with self.assertRaises(cm.CaptureError) as ctx:
            cm.validated_display_path("src/a\x00.py")
        self.assertEqual(ctx.exception.reason, "invalid_path")

    def test_an_unreadable_parent_directory_is_unreadable_not_a_confirmed_change(self):
        d = Path(self.root) / "locked"
        d.mkdir()
        (d / "f.py").write_text("x\n")
        os.chmod(d, 0o000)
        self.addCleanup(os.chmod, d, 0o755)
        if os.geteuid() == 0:
            self.skipTest("running as root; directory permissions do not apply")
        cap = cm.bounded_capture(self.root, "locked/f.py")
        self.assertEqual(cap.status, "unstable")
        self.assertEqual(cap.reason, "unreadable")
        self.assertNotIn(cap.reason, cm.CONFIRMED_CHANGE_REASONS,
                         "a chmod on a parent must never invalidate a round's votes")

    def test_a_symlink_that_stays_inside_the_root_is_permitted_and_captured(self):
        """The no-follow walk runs over the ALREADY-RESOLVED real path, so an ordinary in-root
        symlink is legitimate (the ratified design permits it) — what no-follow catches is a
        symlink that appears between resolution and open."""
        (Path(self.root) / "src" / "t.py").write_text("t\n")
        (Path(self.root) / "src" / "s.py").symlink_to("t.py")
        cap = cm.bounded_capture(self.root, "src/s.py")
        self.assertEqual(cap.status, "ok")
        self.assertEqual(cap.data, b"t\n")
        self.assertTrue(cap.resolved_path.endswith("t.py"), "the identity is the real target")

    def test_a_component_swapped_for_a_symlink_after_resolution_is_a_retarget(self):
        (Path(self.root) / "src" / "real.py").write_text("real\n")
        plain = Path(self.root) / "src" / "p.py"
        plain.write_text("plain\n")
        real_resolve = cm.safe_resolve

        def resolve_then_swap(root, rel):
            resolved = real_resolve(root, rel)
            if rel == "src/p.py" and not plain.is_symlink():
                plain.unlink()                       # between resolution and open
                plain.symlink_to("real.py")
            return resolved

        with unittest.mock.patch.object(cm, "safe_resolve", resolve_then_swap):
            with self.assertRaises(cm.CaptureError) as ctx:
                cm._open_norace(self.root, "src/p.py")
        self.assertEqual(ctx.exception.reason, "retargeted")

    def test_a_completed_read_rejected_after_the_fact_still_reports_its_work(self):
        """The file grows at EOF, between the last read() and the after-read fstat: every byte was
        genuinely read and genuinely hashed, and the rejection does not erase that work."""
        real_read = os.read
        grown = {"n": 0}

        def read_then_grow(fd, n):
            chunk = real_read(fd, n)
            if not chunk and grown["n"] < 2:     # EOF reached: the whole file was read
                grown["n"] += 1
                with open(self.a, "ab") as fh:
                    fh.write(b"x")
            return chunk

        with unittest.mock.patch.object(cm.os, "read", read_then_grow):
            cap = cm.bounded_capture(self.root, "src/a.py")
        self.assertEqual(cap.status, "unstable")
        self.assertEqual(cap.reason, "mutated_during_read")
        self.assertEqual(cap.attempts, 2, "exactly two bounded attempts, no more")
        # attempt 1 read "body\n" (5), attempt 2 read the grown "body\nx" (6); each was hashed
        self.assertEqual(cap.bytes_read, 11)
        self.assertEqual(cap.bytes_hashed, 11)
        # and a guard over that source reports "we could not check", never "current"
        guard = [{"root": self.root, "path": "src/a.py", "resolved_path": str(self.a),
                  "source_sha256": cm.sha256_hex(self.a.read_bytes())}]
        grown["n"] = 0
        with unittest.mock.patch.object(cm.os, "read", read_then_grow):
            status, results, stats = cm.verify_guard(self.root, guard)
        self.assertEqual(status, "pending_verification", "unstable is never reported as current")
        self.assertEqual(results[0]["status"], "unstable")
        self.assertGreater(stats["bytes_read"], 0, "the guard reports the work it really did")
        self.assertGreater(stats["bytes_hashed"], 0)

    def test_a_partial_read_that_then_fails_counts_read_bytes_and_no_hashing(self):
        """Work that happened is counted; work that did not is not. A read aborted mid-file was
        never hashed, so bytes_hashed stays 0 while bytes_read records what came off the fd."""
        real_read = os.read
        calls = {"n": 0}

        def flaky(fd, n):
            calls["n"] += 1
            if calls["n"] % 2 == 1:
                return real_read(fd, 3)          # a partial chunk...
            raise OSError(5, "simulated I/O error")   # ...then the read fails

        with unittest.mock.patch.object(cm.os, "read", flaky):
            cap = cm.bounded_capture(self.root, "src/a.py")
        self.assertEqual(cap.status, "unstable")
        self.assertEqual(cap.reason, "unreadable")
        self.assertEqual(cap.attempts, 2)
        self.assertEqual(cap.bytes_read, 6, "3 bytes actually read on each of the two attempts")
        self.assertEqual(cap.bytes_hashed, 0, "a read that never completed was never hashed")
        self.assertNotIn(cap.reason, cm.CONFIRMED_CHANGE_REASONS)

    def test_a_symlink_that_escapes_the_root_after_the_read_still_reports_its_work(self):
        """The defect: an in-root symlink is retargeted OUTSIDE the root at EOF, after the read
        loop finished. The source is rightly rejected, but the escape is raised inside
        safe_resolve, which knows nothing about this attempt — so the five bytes really read and
        really hashed must still be reported, not silently accounted for as zero work."""
        outside = Path(self.tmp) / "outside.py"
        outside.write_text("gone\n")
        target = Path(self.root) / "src" / "target.py"
        target.write_text("body\n")                      # five bytes
        link = Path(self.root) / "src" / "link.py"
        link.symlink_to("target.py")                     # in-root and valid when it is opened
        real_read, real_hash = os.read, cm.sha256_hex
        actual = {"read": 0, "hashed": 0, "escaped": False}

        def read_then_escape(fd, n):
            chunk = real_read(fd, n)
            actual["read"] += len(chunk)
            if not chunk and not actual["escaped"]:      # EOF: the whole file has been read
                actual["escaped"] = True
                link.unlink()
                link.symlink_to(outside)
            return chunk

        def counting_hash(data):
            actual["hashed"] += len(data)
            return real_hash(data)

        with unittest.mock.patch.object(cm.os, "read", read_then_escape), \
                unittest.mock.patch.object(cm, "sha256_hex", counting_hash):
            cap = cm.bounded_capture(self.root, "src/link.py")
        self.assertEqual(cap.status, "error")
        self.assertEqual(cap.reason, "escape", "an escaped source is still rejected immediately")
        self.assertEqual(actual["read"], 5, "instrumented: five bytes really came off the fd")
        self.assertEqual(actual["hashed"], 5, "instrumented: those five bytes were really hashed")
        self.assertEqual(cap.bytes_read, 5, "the work done is reported, not discarded")
        self.assertEqual(cap.bytes_hashed, 5)
        # and that work reaches the accounting path the run's reporting actually sums
        stats = cm.new_stats()
        cm.account(stats, cap)
        self.assertEqual((stats["bytes_read"], stats["bytes_hashed"]), (5, 5))
        self.assertEqual(stats["capture_failures"], 1)
        # the same escape seen through the freshness guard: a confirmed change, work still counted
        link.unlink()
        link.symlink_to(outside)
        guard = [{"root": self.root, "path": "src/link.py",
                  "resolved_path": str(Path(self.root) / "src" / "target.py"),
                  "source_sha256": cm.sha256_hex(b"body\n")}]
        status, results, gstats = cm.verify_guard(self.root, guard)
        self.assertEqual(status, "changed", "an escaped source is a demonstrated change")
        self.assertEqual(results[0]["reason"], "escape")
        # and the same file captured without the escape is not double-counted
        link.unlink()
        link.symlink_to("target.py")
        ok = cm.bounded_capture(self.root, "src/link.py")
        self.assertEqual(ok.status, "ok")
        self.assertEqual((ok.bytes_read, ok.bytes_hashed), (10, 10),
                         "two complete reads of five bytes, each hashed once")

    def test_a_post_read_filesystem_failure_is_unreadable_and_keeps_its_counters(self):
        """A post-read failure that the inner read handler never saw: the re-resolution itself
        fails with an I/O error. That is "we could not look", never a confirmed change, and the
        bytes already read and hashed are still reported."""
        real_realpath = os.path.realpath
        calls = {"n": 0}

        def flaky_realpath(p):
            # the pre-open resolution succeeds; only the post-read re-resolution fails
            if str(p).endswith("src/a.py"):
                calls["n"] += 1
                if calls["n"] % 2 == 0:
                    raise OSError(5, "simulated I/O error")
            return real_realpath(p)

        with unittest.mock.patch.object(cm.os.path, "realpath", flaky_realpath):
            cap = cm.bounded_capture(self.root, "src/a.py")
        self.assertEqual(cap.status, "unstable")
        self.assertEqual(cap.reason, "unreadable")
        self.assertNotIn(cap.reason, cm.CONFIRMED_CHANGE_REASONS,
                         "a failed re-resolution is not a demonstrated change")
        self.assertEqual(cap.attempts, 2)
        self.assertEqual(cap.bytes_read, 10, "five bytes on each of the two attempts")
        self.assertEqual(cap.bytes_hashed, 10, "each completed read was hashed before the failure")

    def test_a_failure_closing_the_descriptor_after_eof_is_unreadable_and_hashes_nothing(self):
        """The defect: the read finished, and then descriptor cleanup itself failed. os.close runs
        in the `finally` that ends the inner read handler, so no inner handler can ever see it —
        the raw OSError left the whole capture operation, past every accounting boundary, and
        bounded_capture propagated it instead of returning a result. It must become the ordinary
        retry-worthy `unreadable`, carrying the bytes genuinely read; nothing was hashed, because
        the hashing happens after the close and never ran."""
        real_read, real_close = os.read, os.close
        at_eof = set()
        seen = {"read": 0, "closes": 0}

        def read_to_eof(fd, n):
            chunk = real_read(fd, n)
            seen["read"] += len(chunk)
            if not chunk:
                at_eof.add(fd)          # this descriptor is the regular file, read to the end
            return chunk

        def close_then_fail(fd):
            real_close(fd)              # really closed: the failure injects no descriptor leak
            if fd in at_eof:
                at_eof.discard(fd)
                seen["closes"] += 1
                raise OSError(5, "simulated I/O error closing the file")

        with unittest.mock.patch.object(cm.os, "read", read_to_eof), \
                unittest.mock.patch.object(cm.os, "close", close_then_fail):
            cap = cm.bounded_capture(self.root, "src/a.py")
        self.assertEqual(cap.status, "unstable", "a result, not a raw OSError out of the operation")
        self.assertEqual(cap.reason, "unreadable")
        self.assertNotIn(cap.reason, cm.CONFIRMED_CHANGE_REASONS,
                         "a failed close is not a demonstrated change")
        self.assertEqual(cap.attempts, 2)
        self.assertEqual(seen["closes"], 2, "the failure really fired on both attempts")
        self.assertEqual(cap.bytes_read, 10, "five bytes on each of the two attempts")
        self.assertEqual(cap.bytes_hashed, 0,
                         "the close failed before the hash: hashing that never happened is never counted")
        self.assertEqual(seen["read"], 10, "instrumented: exactly those bytes came off the fd")
        # and those totals reach the accounting path the run's reporting actually sums
        stats = cm.new_stats()
        cm.account(stats, cap)
        self.assertEqual((stats["bytes_read"], stats["bytes_hashed"]), (10, 0))
        self.assertEqual(stats["capture_unstable"], 1, "retry-worthy, not a confirmed failure")
        self.assertEqual(stats["read_attempts"], 2)

    def test_a_fifo_is_rejected_without_hanging(self):
        fifo = Path(self.root) / "src" / "pipe"
        os.mkfifo(fifo)
        cap = cm.bounded_capture(self.root, "src/pipe")
        self.assertEqual(cap.status, "error")
        self.assertEqual(cap.reason, "not_regular")


