        self.assertEqual(records[0]["type"], "header")
        self.assertEqual(records[0]["argv"], argv)
        self.assertEqual(records[0]["log"], str(self.only_log()))
        self.assertEqual(records[-1]["type"], "end")
        self.assertEqual(records[-1]["failing_tests"], 0)

