    ROWS_300 = ("for i in range(300):\n"
                "    print(('error: boom %d ' % i if i % 3 == 0 else 'line %d ' % i) + 'x' * 100)\n"
                "raise SystemExit(1)\n")

    def test_the_whole_stdout_fits_in_max_bytes_at_the_computed_minimum_and_the_omission_line_is_exact(self):
        command = self.py(self.ROWS_300)
        cap = self.minimum(command)
        rc, out, err = self.wrap(command, ["--max-bytes", str(cap)])
        self.assertEqual(rc, 1, (out, err))
        self.assertLessEqual(len(out), cap)
        self.assertNotIn(b"TRUNCATED", out)
        self.assertTrue(out.endswith(b"\n"))
        lines = out.decode().splitlines()
        self.assertEqual(lines[3][:len("failures index:")], "failures index:")
        self.assertEqual(lines[4], "failing tests not identified")
        shown = {int(m.group(1)) for m in (re.match(r"^(\d+): ", line) for line in lines) if m}
        errors_shown = {n for n in shown if (n - 1) % 3 == 0}
        parts = []
        if 100 - len(errors_shown):
            parts.append("%d more error lines not shown" % (100 - len(errors_shown)))
        if 300 - len(shown):
            parts.append("%d of 300 log lines not shown" % (300 - len(shown)))
        self.assertEqual(lines[-1], "omitted: " + "; ".join(parts))
        self.assertLess(len(shown), 60, "at the minimum the optional rows cannot all fit")

    def test_the_byte_ceiling_is_exact_the_selection_fills_it_and_one_byte_less_drops_a_row(self):
        command = self.py(self.ROWS_300)
        cap = self.minimum(command) + 1000
        rc, first, err = self.wrap(command, ["--max-bytes", str(cap)])
        self.assertEqual(rc, 1, (first, err))
        size = len(first)
        self.assertLessEqual(size, cap)
        self.assertGreater(size, cap - 500, "the assembly leaves a large part of the budget unused")
        rc, same, err = self.wrap(command, ["--max-bytes", str(size)])
        self.assertEqual(len(same), size, "the output that fits exactly must still be produced at its own size")
        rc, less, err = self.wrap(command, ["--max-bytes", str(size - 1)])
        self.assertLessEqual(len(less), size - 1)
        rows = lambda text: len(re.findall(rb"(?m)^\d+: ", text))
        self.assertLess(rows(less), rows(same))

