    def limited(self, code, limit=100, wrapper_args=(), **kw):
        return self.wrap(self.py(code), wrapper_args,
                         preexec_fn=lambda: resource.setrlimit(resource.RLIMIT_FSIZE, (limit, limit)), **kw)

    def test_the_mandatory_lines_fit_at_the_computed_minimum_in_every_scenario(self):
        fallback = self.root / ("fallback-" + "f" * 60)
        code = "import os; os.write(1, b''.join(b'line-%04d ' % i + b'x' * 50 + b'\\n' for i in range(20))); raise SystemExit(4)"

        def check(out, cap, expect):
            self.assertLessEqual(len(out), cap)
            lines = out.decode().splitlines()
            self.assertTrue(lines[-1].startswith("omitted:"), lines[-1])
            self.assertNotIn("SUMMARY ERROR", out.decode())
            for wanted in expect:
                self.assertTrue(any(l.startswith(wanted) for l in lines), (wanted, lines))

        with self.subTest(scenario="incomplete capture with continuation segments in the fallback directory"):
            args = ["--fallback-dir", str(fallback)]
            cap = self.minimum(self.py(code), args)
            rc, out, err = self.limited(code, 100, args + ["--max-bytes", str(cap)])
            self.assertEqual(rc, 4, (out, err))
            check(out, cap, ["capture: INCOMPLETE", "log continued:", "failures index: INCOMPLETE"])
            shutil.rmtree(self.logs)
            shutil.rmtree(fallback, ignore_errors=True)
        with self.subTest(scenario="timeout"):
            sleeper = self.py("import time; print('x'); time.sleep(30)")
            cap = self.minimum(sleeper, ["--timeout", "1"])
            rc, out, err = self.wrap(sleeper, ["--timeout", "1", "--max-bytes", str(cap)])
            self.assertEqual(rc, 124, (out, err))
            check(out, cap, ["TIMEOUT (TIMED OUT after 1s"])
            shutil.rmtree(self.logs)
        with self.subTest(scenario="signal"):
            killed = self.py("import os, signal; os.kill(os.getpid(), signal.SIGKILL)")
            cap = self.minimum(killed)
            rc, out, err = self.wrap(killed, ["--max-bytes", str(cap)])
            self.assertEqual(rc, 137, (out, err))
            check(out, cap, ["SIGNAL 9 (SIGKILL)"])

