    def test_markup_characters_inside_quoted_attributes_are_not_misread_as_token_ends(self):
        tricky = 'a > b <!-- c --> d ?> e ]]> f <![CDATA[ g'
        xml = ('<testsuites><testsuite name="s"><testcase classname="pkg.C" name="t" note="%s"><failure message="m">'
               'x</failure></testcase></testsuite></testsuites>' % tricky.replace("<", "&lt;"))
        self.assert_read_ok(self.scan(xml.replace("&lt;", "&#60;"), limit=200))
        single = "<testsuites><testsuite name='s'><testcase classname='pkg.C' name='t' note='say \"hi\" > there'>" \
                 "<failure message=\"it's\">x</failure></testcase></testsuite></testsuites>"
        shutil.rmtree(self.logs)
        self.assert_read_ok(self.scan(single, limit=200))

