    class EntryStream:
        """A `_scandir` seam for one directory that produces `count` regular-file entries lazily, one per request, and
        counts how many were requested; every other directory is listed for real."""

        def __init__(self, count, directory="reports", unreadable=False, stem="r%05d.xml", real=False, subdirectories=False):
            self.count, self.directory, self.pulled = count, directory, 0
            self.unreadable, self.stem, self.real = unreadable, stem, real     # `unreadable` may be a function of no arguments
            self.subdirectories = subdirectories       # the entries are directories whose own listing fails with EIO
            self.on_first = None                       # called once, when the first directory is listed

        def make(self, name):
            """A regular file, or (`unreadable`) an entry whose type cannot be inspected (EIO)."""
            plain = lambda *args, **kwargs: False

            def broken(*args, **kwargs):
                raise OSError(errno.EIO, "Input/output error", self.directory + "/" + name)
            return types.SimpleNamespace(name=name, path=self.directory + "/" + name,
                                         is_dir=(lambda *args, **kwargs: True) if self.subdirectories else
                                         broken if (self.unreadable() if callable(self.unreadable) else self.unreadable) else plain,
                                         is_symlink=plain,
                                         is_file=lambda *args, **kwargs: not self.subdirectories)

        def __call__(self, path):
            if self.on_first is not None:
                hook, self.on_first = self.on_first, None
                hook()
            if self.subdirectories and str(path).startswith(self.directory + "/"):
                raise OSError(errno.EIO, "Input/output error", str(path))
            if str(path).rstrip("/") != self.directory:
                return os.scandir(path)
            stream = self
            path = str(path)

            class Listing:
                def __enter__(self):
                    return self

                def __exit__(self, *exc):
                    return None

                def __iter__(self):
                    for i in range(stream.count):
                        stream.pulled += 1
                        yield stream.make(stream.stem % i)
                    if stream.real:
                        with os.scandir(path) as entries:
                            yield from entries
            return Listing()

    def test_a_capped_discovery_stops_reading_the_directory_once_the_source_is_capped(self):
        self.put("reports/r00000.xml", self.one_failure("test_first"))
        stream = self.EntryStream(10000)
        module, rc, out = self.inproc(self.globs("reports/*.xml"), self.py(self.GLOB_CMD),
                                      {"_scandir": stream, "MAX_REPORT_PATHS": 1, "MAX_UNEXAMINED_COUNT": 2})
        lines = self.summary_lines(out)
        self.assertIn("reports not examined: 4+ (glob reports/*.xml)", lines)
        self.assertIn("stale 1", self.reports_line(out))
        self.assertLessEqual(stream.pulled, 8, "the whole directory was read before the first candidate was admitted")

    def test_expanding_a_glob_over_a_hundred_thousand_entries_holds_no_memory_per_entry(self):
        import tracemalloc
        module = rc_load()
        expand = getattr(module, "expand_glob", None)
        self.assertIsNotNone(expand, "run_check.py has no expand_glob")
        (self.cwd / "reports").mkdir()
        old = os.getcwd()
        os.chdir(str(self.cwd))
        try:
            for pattern in ("reports/*.xml", "reports/**", "reports/**/*.xml"):
                with self.subTest(pattern=pattern):
                    stream = self.EntryStream(100000)
                    with unittest.mock.patch.object(module, "_scandir", stream, create=True):
                        tracemalloc.start()
                        try:
                            hits = sum(1 for _ in expand(pattern, lambda path, code: None))
                            peak = tracemalloc.get_traced_memory()[1]
                        finally:
                            tracemalloc.stop()
                    self.assertGreaterEqual(hits, 100000)
                    self.assertLess(peak, 1024 * 1024, "%d bytes were held at the peak" % peak)
        finally:
            os.chdir(old)

    def test_every_inspection_failure_of_a_source_without_matches_is_counted_streamed_to_the_index_and_accounted_in_the_omissions(self):
        stream = self.EntryStream(300, unreadable=True, stem="e%05d")
        module, rc, out = self.inproc(self.globs("reports/**/*.xml"), self.py(self.GLOB_CMD), {"_scandir": stream})
        lines = self.summary_lines(out)
        self.assertIn("errors 600", self.reports_line(out))
        coverage = [r for r in self.index_records() if r["type"] == "coverage" and r.get("kind") == "discovery_error"]
        self.assertEqual({(p, len({r["path"] for r in coverage if r["pass"] == p})) for p in ("pre_launch", "post_run")},
                         {("pre_launch", 300), ("post_run", 300)})
        self.assertEqual(len(coverage), 600)
        shown = [l for l in lines if l.startswith("WARNING:")]
        omitted = re.search(r"(\d+) warning lines not shown", lines[-1])
        self.assertIsNotNone(omitted, lines[-1])
        self.assertEqual(len(shown) + int(omitted.group(1)), 601)
        self.assertLessEqual(len(out), 4000)

