    def growth_while_diagnosing(self, count):
        """The memory that one in-process run holds at its peak beyond what was held when its discovery started, while the
        discovery meets `count` unreadable entries in each pass (no report matches); returns (bytes, stdout bytes)."""
        import gc
        import tracemalloc
        shutil.rmtree(self.logs, ignore_errors=True)
        stream = self.EntryStream(count, unreadable=True, stem="e%05d")
        base = []

        def restart():
            tracemalloc.reset_peak()
            base.append(tracemalloc.get_traced_memory()[0])
        stream.on_first = restart
        gc.collect()
        tracemalloc.start()
        try:
            module, rc, out = self.inproc(self.globs("reports/*/x.xml"), self.py(self.GLOB_CMD),
                                          {"_scandir": stream, "MAX_REPORT_PATHS": 100})
            peak = tracemalloc.get_traced_memory()[1]
        finally:
            tracemalloc.stop()
        return peak - base[0], out

    def test_the_memory_held_for_discovery_diagnostics_does_not_grow_with_their_number(self):
        small, _ = self.growth_while_diagnosing(100)
        big, out = self.growth_while_diagnosing(30000)
        self.assertIn("errors 60000", self.reports_line(out))
        self.assertLess(big, 1024 * 1024, "%d bytes were held at the peak for 60000 diagnostics (%d for 200)" % (big, small))

    def test_more_distinct_discovery_failures_than_can_be_remembered_are_flagged_and_their_repeats_counted_again(self):
        (self.cwd / "reports").mkdir()
        stream = self.EntryStream(5, stem="d%05d", subdirectories=True)
        module, rc, out = self.inproc(self.globs("reports/**/*.xml"), self.py(self.GLOB_CMD),
                                      {"_scandir": stream, "MAX_REPORT_PATHS": 3})
        lines = self.summary_lines(out)
        for label in ("pre-launch", "post-run"):
            self.assertIn("WARNING: more than 3 distinct discovery failures in the %s pass; a failure that repeats after that "
                          "is counted again in the errors" % label, lines)
        coverage = [(r["pass"], r["cap"]) for r in self.index_records()
                    if r["type"] == "coverage" and r.get("kind") == "discovery_errors_dedup_capped"]
        self.assertEqual(sorted(coverage), [("post_run", 3), ("pre_launch", 3)])
        errors = int(re.search(r"errors (\d+)$", self.reports_line(out)).group(1))
        self.assertGreater(errors, 10)              # 5 distinct directories in each pass, each listed twice: 7 per pass here

    def test_the_report_warnings_that_do_not_fit_are_counted_exactly_in_the_omission_line(self):
        code = ("import os\n"
                "d = os.environ['RUN_CHECK_REPORT_DIR']\n"
                "for i in range(60):\n"
                "    open(os.path.join(d, 'bad%02d.xml' % i), 'w').write('<<<not xml')\n")
        command = self.py(code)
        cap = self.minimum(command)
        rc, out, err = self.wrap(command, ["--max-bytes", str(cap)])
        self.assertEqual(rc, 0, (out, err))
        lines = self.summary_lines(out)
        shown = [l for l in lines if l.startswith("WARNING: REPORT_ERROR:")]
        omitted = re.search(r"(\d+) warning lines not shown", lines[-1])
        self.assertIsNotNone(omitted, lines[-1])
        self.assertEqual(len(shown) + int(omitted.group(1)), 60)
        self.assertIn("errors 60", self.reports_line(out))
        self.assertLessEqual(len(out), cap)

    def test_a_new_report_stays_unproven_although_the_summary_cannot_show_every_discovery_diagnostic(self):
        new = (self.cwd / "reports" / "new.xml").resolve()
        (self.cwd / "reports").mkdir()
        stream = self.EntryStream(40, unreadable=lambda: not new.exists(), stem="e%05d", real=True)
        args = self.globs("reports/**/*.xml")
        command = self.py(self.GLOB_CMD, "write", "reports/new.xml")
        cap = self.minimum(command, args)
        module, rc, out = self.inproc(args + ["--max-bytes", str(cap)], command, {"_scandir": stream},
                                      env={"RC_XML": self.one_failure("test_new")})
        lines = self.summary_lines(out)
        self.assertLessEqual(len(out), cap)
        self.assertRegex(lines[-1], r"^omitted: .*\d+ warning lines not shown")          # some diagnostics were left out
        self.assertIn("0 changed during this run", self.reports_line(out))
        record = [r for r in self.index_records() if r["type"] == "report" and r["path"] == str(new)]
        self.assertEqual([(r["status"], r["error"]) for r in record],
                         [("unknown", "pre-launch discovery incomplete; current-run provenance unknown")])
        self.assertNotIn("failing tests: 1 identified", "\n".join(lines))

    def test_two_hundred_unreadable_directories_are_all_counted_and_only_the_warnings_that_fit_are_shown(self):
        names = ["reports/d%03d" % i for i in range(200)]
        for name in names:
            (self.cwd / name).mkdir(parents=True)
            (self.cwd / name).chmod(0)
        try:
            rc, out, err = self.wrap(self.py("pass"), self.globs("reports/**/*.xml"))
        finally:
            for name in names:
                (self.cwd / name).chmod(0o755)
        lines = self.summary_lines(out)
        self.assertEqual(rc, 0, (out, err))
        self.assertIn("errors 400", self.reports_line(out))
        shown = [l for l in lines if l.startswith("WARNING:")]
        omitted = re.search(r"(\d+) warning lines not shown", lines[-1])
        self.assertIsNotNone(omitted, lines[-1])
        self.assertEqual(len(shown) + int(omitted.group(1)), 401)           # 400 failures and the glob that matches nothing
        coverage = [r for r in self.index_records() if r["type"] == "coverage" and r.get("kind") == "discovery_error"]
        self.assertEqual((len(coverage), {r["errno"] for r in coverage}), (400, {"EACCES"}))
        self.assertLessEqual(len(out), 4000)

    def glob_fixture(self):
        for name in ("top.xml", ".hidden.xml", "a/x.xml", "a/y.xml", "a/.h.xml", "a/file.txt", "a/b/y.xml", "a/b/c/z.xml",
                     ".dot/w.xml", ".dot/.v.xml", "d[1]/e.xml", "sp ace/s.xml", "a/b/c/d/deep.xml"):
            self.put("fx/" + name, "<x/>")
        (self.cwd / "fx" / "emptydir").mkdir()
        os.symlink("b", str(self.cwd / "fx" / "a" / "link"))
        os.symlink("nowhere", str(self.cwd / "fx" / "dangling.xml"))

    GLOB_PATTERNS = ("*.xml", "*", "**", "**/", "**/*.xml", "a/**", "a/**/*.xml", "a/*/y.xml", "*/x.xml", ".dot/*.xml",
                     ".*/*.xml", "a/b/", "a/", "nonexistent/*", "a/x.xml", "./a/*.xml", "a/[xy].xml", "a/?.xml", "a/[!x].xml",
                     "a/link/*.xml", "**/link/*.xml", "**/y.xml", "a/**/c/*.xml", "d[[]1]/*.xml", "sp*/*.xml", "a//x.xml",
                     "**/.v.xml", "?/*/*.xml", "dangling.xml", "*ng*", "nothing.xml", "a/b/**/deep.xml", "**/**/z.xml",
                     "a/**/**/*.xml", "emptydir/**", "**/emptydir")

    def test_the_glob_expansion_returns_exactly_what_glob_glob_returns_for_every_pattern_shape(self):
        import glob as real_glob
        module = rc_load()
        expand = getattr(module, "expand_glob", None)
        self.assertIsNotNone(expand, "run_check.py has no expand_glob")
        self.glob_fixture()
        base = self.cwd / "fx"
        old = os.getcwd()
        os.chdir(str(base))
        try:
            for pattern in self.GLOB_PATTERNS + (str(base) + "/a/**/*.xml", str(base) + "/*.xml", str(base) + "/nothing/*"):
                with self.subTest(pattern=pattern):
                    errors = []
                    mine = [p for p in expand(pattern, lambda path, code: errors.append((path, code)))]
                    theirs = [p for p in real_glob.iglob(pattern, recursive=True)]
                    self.assertEqual(sorted(set(p for p in mine if p)), sorted(set(p for p in theirs if p)))
                    self.assertEqual(errors, [])
        finally:
            os.chdir(old)

    def test_the_glob_expansion_terminates_on_a_symlink_cycle_and_reaches_the_same_real_files(self):
        import glob as real_glob
        module = rc_load()
        expand = getattr(module, "expand_glob", None)
        self.assertIsNotNone(expand, "run_check.py has no expand_glob")
        self.put("fx/a/x.xml", "<x/>")
        os.symlink("..", str(self.cwd / "fx" / "a" / "up"))
        os.symlink("../b", str(self.cwd / "fx" / "a" / "sideways"))
        os.makedirs(str(self.cwd / "fx" / "b"))
        os.symlink("../a", str(self.cwd / "fx" / "b" / "back"))
        old = os.getcwd()
        os.chdir(str(self.cwd / "fx"))
        try:
            errors = []
            mine = list(expand("**/*.xml", lambda path, code: errors.append((path, code))))
            self.assertEqual(errors, [])
            self.assertEqual({os.path.realpath(p) for p in mine}, {str((self.cwd / "fx" / "a" / "x.xml").resolve())})
            self.assertLess(len(mine), 50)
        finally:
            os.chdir(old)

    def test_a_directory_whose_symlink_status_cannot_be_read_is_treated_as_a_symlink_so_a_cycle_still_ends(self):
        module = rc_load()
        expand = getattr(module, "expand_glob", None)
        self.assertIsNotNone(expand, "run_check.py has no expand_glob")
        self.put("fx/a/x.xml", "<x/>")
        os.symlink("..", str(self.cwd / "fx" / "a" / "up"))
        seam = self.faulty_scandir(self.cwd / "never-created", bad_entry="up", method="is_symlink")
        old = os.getcwd()
        os.chdir(str(self.cwd / "fx"))
        try:
            errors = []
            with unittest.mock.patch.object(module, "_scandir", seam, create=True):
                mine = list(expand("**/*.xml", lambda path, code: errors.append((path, code))))
        finally:
            os.chdir(old)
        self.assertEqual(mine, ["a/x.xml"])
        self.assertEqual(set(errors), {("a/up", "EIO")})

    def test_a_pre_launch_discovery_that_fails_makes_every_later_new_path_unproven(self):
        z = (self.cwd / "reports" / "new.xml").resolve()
