        self.assertIn("WARNING: PROVENANCE_ERROR: %s: pre-launch discovery incomplete; current-run provenance unknown" % z, lines)
        self.assertEqual(self.reports_line(out), "reports: 0 changed during this run (concurrent writers not excluded), "
                         "0 produced by this invocation, stale 0, removed 0, errors 2")
