    def test_a_post_run_discovery_that_fails_is_a_report_error_and_never_a_removal_claim(self):
        self.put("reports/old.xml", self.one_failure("test_old"))
        module, rc, out = self.inproc(self.globs("reports/*.xml"), self.py("open('started', 'w').close(); raise SystemExit(1)"),
                                      {"_scandir": self.faulty_scandir(self.cwd / "started", directory="reports", after=True)})
        lines = self.summary_lines(out)
        self.assertIn("WARNING: REPORT_ERROR: %s: EIO" % (self.cwd / "reports"), lines)
        self.assertEqual(self.reports_line(out), "reports: 0 changed during this run (concurrent writers not excluded), "
                         "0 produced by this invocation, stale 0, removed 0, errors 1")

    def private_pair(self, method):
        """Runs the MIXED command (a-bad.xml with test_bad, then z-good.xml with test_good, and a log failure) with the
        `method` inspection of the entry a-bad.xml failing with EIO; returns (rc, out, path of a-bad.xml)."""
        command = self.py(self.MIXED, self.suite(self.case("pkg.C", "test_bad")), self.suite(self.case("pkg.C", "test_good")))
        seam = self.faulty_scandir(self.cwd / "never-created", bad_entry="a-bad.xml", method=method)
        module, rc, out = self.inproc([], command, {"_scandir": seam})
        return rc, out, self.report_dir() / "a-bad.xml"

    def assert_only_the_bad_entry_is_lost(self, rc, out, bad):
        lines = self.summary_lines(out)
        self.assertEqual(rc, 1, out)
        self.assertNotIn("SUMMARY ERROR", "\n".join(lines))
        self.assertIn("WARNING: REPORT_ERROR: %s: EIO" % bad, lines)
        self.assertIn("failing tests: 2 identified (junit 1, text-heuristic 1)", lines)
        self.assertIn("#1 pkg.C.test_good [junit]", lines)
        self.assertIn("#2 m.C.test_log [text-heuristic]", lines)
        self.assertIn("1 produced by this invocation", self.reports_line(out))
        self.assertIn("errors 1", self.reports_line(out))
        records = self.index_records()
        self.assertEqual([(r["path"], r["status"]) for r in records if r["type"] == "report"],
                         [(str(self.report_dir() / "z-good.xml"), "ok")])
        self.assertEqual([(r["path"], r["errno"], r["pass"]) for r in records
                          if r["type"] == "coverage" and r.get("kind") == "discovery_error"], [(str(bad), "EIO", "post_run")])
        self.assertEqual(records[-1]["type"], "end")
        self.assertEqual(records[-1]["failing_tests"], 2)

    def test_a_private_entry_whose_type_cannot_be_inspected_is_reported_and_the_entries_after_it_are_still_read(self):
        rc, out, bad = self.private_pair("is_dir")
        self.assert_only_the_bad_entry_is_lost(rc, out, bad)

    def test_a_private_entry_whose_file_type_cannot_be_inspected_is_reported_and_the_entries_after_it_are_still_read(self):
        rc, out, bad = self.private_pair("is_file")
        self.assert_only_the_bad_entry_is_lost(rc, out, bad)

    def test_a_private_report_subdirectory_that_cannot_be_listed_is_a_report_error_and_the_rest_is_read(self):
        code = ("import os, sys\n"
                "d = os.environ['RUN_CHECK_REPORT_DIR']\n"
                "os.makedirs(os.path.join(d, 'locked'))\n"
                "open(os.path.join(d, 'locked', 'hidden.xml'), 'w').write(sys.argv[1])\n"
                "os.chmod(os.path.join(d, 'locked'), 0)\n"
                "open(os.path.join(d, 'ok.xml'), 'w').write(sys.argv[1])\n"
                "sys.exit(1)\n")
        rc, out, err = self.wrap(self.py(code, self.one_failure()))
        locked = self.report_dir() / "locked"
        try:
            lines = self.summary_lines(out)
            self.assertIn("WARNING: REPORT_ERROR: %s: EACCES" % locked, lines)
            self.assertIn("failing tests: 1 identified (junit 1, text-heuristic 0)", lines)
            self.assertIn("1 produced by this invocation", self.reports_line(out))
            self.assertIn("errors 1", self.reports_line(out))
        finally:
            os.chmod(str(locked), 0o700)

    def test_discovery_failures_are_coverage_records_naming_the_source_the_path_and_the_pass(self):
        marker = self.cwd / "reports" / "new.xml"
        directory = str(self.cwd / "reports")
        module, rc, out = self.inproc(self.globs("reports/*.xml"), self.py(self.GLOB_CMD, "write", "reports/new.xml"),
                                      {"_scandir": self.faulty_scandir(marker, directory="reports")},
                                      env={"RC_XML": self.one_failure()})
        coverage = [r for r in self.index_records() if r["type"] == "coverage" and r.get("kind") == "discovery_error"]
        self.assertEqual([(r["source"], r["path"], r["pass"], r["errno"]) for r in coverage],
                         [("reports/*.xml", directory, "pre_launch", "EIO")])
        module, rc, out = self.inproc(self.globs("reports/*.xml"), self.py(self.GLOB_CMD, "write", "reports/new2.xml"),
                                      {"_scandir": self.faulty_scandir(self.cwd / "reports" / "new2.xml", directory="reports",
                                                                       after=True)}, env={"RC_XML": self.one_failure()})
        logs = sorted(self.files(".failures.jsonl"))
