    HEADER = b'{"type":"header","version":1}\n'

    @staticmethod
    def diag(number):
        """One pre-launch discovery_error record exactly as the failures index writes it."""
        return (json.dumps({"type": "coverage", "kind": "discovery_error", "source": "reports/*.xml",
                            "path": "/w/reports/d%d" % number, "pass": "pre_launch", "errno": "EIO"},
                           ensure_ascii=True, separators=(",", ":")) + "\n").encode("ascii")

    def replay(self, source, start, end, name="final", **seams):
        """Index.copy_records of bytes [start, end) of `source` into a new index: (records written, the Index, the source path)."""
        module = rc_load()
        self.assertTrue(hasattr(module, "Index"), "run_check.py has no Index class")
        for attribute, value in seams.items():
            setattr(module, attribute, value)
        path = self.root / (name + "-source.jsonl")
        path.write_bytes(source)
        target = module.Index(str(self.root / (name + ".jsonl")))
        target.copy_records(str(path), start, end)
        target.close()
        return [json.loads(l) for l in (self.root / (name + ".jsonl")).read_text().splitlines()], target, str(path)

    def not_copied(self, records):
        return [r for r in records if isinstance(r, dict) and r.get("kind") == "records_not_copied"]

    def test_a_source_that_ends_at_a_record_boundary_before_the_saved_end_leaves_an_explicit_gap(self):
        start = len(self.HEADER)
        source = self.HEADER + self.diag(0) + self.diag(1)                    # the third record of the range is missing
        end = start + len(self.diag(0)) + len(self.diag(1)) + len(self.diag(2))
        records, target, path = self.replay(source, start, end)
        self.assertEqual([r["path"] for r in records if r.get("kind") == "discovery_error"], ["/w/reports/d0", "/w/reports/d1"])
        gap = self.not_copied(records)
        self.assertEqual(len(gap), 1, records)
        self.assertEqual((gap[0]["from"], gap[0]["range"], gap[0]["copied_records"]), (path, [start, end], 2))
        self.assertTrue(gap[0]["reason"].startswith("EOFError"), gap[0])
        self.assertIsNone(target.error)

    def test_an_empty_source_leaves_an_explicit_gap_for_the_whole_saved_range(self):
        start = len(self.HEADER)
        end = start + len(self.diag(0)) + len(self.diag(1))
        records, target, path = self.replay(b"", start, end)
        self.assertEqual([r for r in records if r.get("kind") == "discovery_error"], [])
        gap = self.not_copied(records)
        self.assertEqual(len(gap), 1, records)
        self.assertEqual((gap[0]["from"], gap[0]["range"], gap[0]["copied_records"]), (path, [start, end], 0))
        self.assertTrue(gap[0]["reason"].startswith("EOFError"), gap[0])

    def test_a_last_record_without_its_line_feed_is_not_copied_and_leaves_an_explicit_gap(self):
        start = len(self.HEADER)
        source = self.HEADER + self.diag(0) + self.diag(1)[:-1]                # the terminator of the last record is gone
        end = start + len(self.diag(0)) + len(self.diag(1))
        records, target, path = self.replay(source, start, end)
        self.assertEqual([r["path"] for r in records if r.get("kind") == "discovery_error"], ["/w/reports/d0"])
        gap = self.not_copied(records)
        self.assertEqual(len(gap), 1, records)
        self.assertEqual((gap[0]["from"], gap[0]["range"], gap[0]["copied_records"]), (path, [start, end], 1))
        self.assertIn("line feed", gap[0]["reason"])

    def test_a_record_that_extends_beyond_the_saved_range_is_neither_read_nor_copied(self):
        start = len(self.HEADER)
        longer = self.diag(1)[:-1].replace(b"/w/reports/d1", b"/w/reports/" + b"x" * 400) + b"\n"    # replaced by a longer record
        source = self.HEADER + self.diag(0) + longer + self.diag(2)
        end = start + len(self.diag(0)) + len(self.diag(1))
        self.assertGreater(len(longer), len(self.diag(1)))
        records, target, path = self.replay(source, start, end)
        self.assertEqual([r["path"] for r in records if r.get("kind") == "discovery_error"], ["/w/reports/d0"])
        gap = self.not_copied(records)
        self.assertEqual(len(gap), 1, records)
        self.assertEqual((gap[0]["from"], gap[0]["range"], gap[0]["copied_records"]), (path, [start, end], 1))
        self.assertIn("beyond the saved range", gap[0]["reason"])

    def test_a_record_longer_than_the_read_bound_is_not_copied_and_leaves_an_explicit_gap(self):
        start = len(self.HEADER)
        long = self.diag(1)[:-1].replace(b"/w/reports/d1", b"/w/reports/" + b"x" * 400) + b"\n"
        source = self.HEADER + self.diag(0) + long + self.diag(2)
        end = start + len(self.diag(0)) + len(long) + len(self.diag(2))                   # the whole range is in the file
        records, target, path = self.replay(source, start, end, REPORT_CHUNK=200)
        self.assertEqual([r["path"] for r in records if r.get("kind") == "discovery_error"], ["/w/reports/d0"])
        gap = self.not_copied(records)
        self.assertEqual(len(gap), 1, records)
        self.assertEqual((gap[0]["from"], gap[0]["range"], gap[0]["copied_records"]), (path, [start, end], 1))
        self.assertIn("longer than 200 bytes", gap[0]["reason"])

    def test_a_healthy_range_is_replayed_record_for_record_and_nothing_outside_it_is_copied(self):
        start = len(self.HEADER)
        inside = [self.diag(0), self.diag(1), self.diag(2)]
        source = self.HEADER + b"".join(inside) + self.diag(3)                            # a record after the range is not ours
        records, target, path = self.replay(source, start, start + sum(len(r) for r in inside))
        self.assertEqual(records, [json.loads(r) for r in inside])
        self.assertEqual((target.error, target.written, target.dropped), (None, 3, 0))
        self.assertEqual((self.root / "final.jsonl").read_bytes(), b"".join(inside))

    def test_a_malformed_record_leaves_an_explicit_gap_and_keeps_the_records_before_it(self):
        start = len(self.HEADER)
        source = self.HEADER + self.diag(0) + b'{"type":"coverage","kind":\n' + self.diag(2)
        end = start + len(self.diag(0)) + len(b'{"type":"coverage","kind":\n') + len(self.diag(2))
        records, target, path = self.replay(source, start, end)
        self.assertEqual([r["path"] for r in records if r.get("kind") == "discovery_error"], ["/w/reports/d0"])
        gap = self.not_copied(records)
        self.assertEqual(len(gap), 1, records)
        self.assertEqual((gap[0]["from"], gap[0]["range"], gap[0]["copied_records"]), (path, [start, end], 1))
        self.assertTrue(gap[0]["reason"].startswith("JSONDecodeError"), gap[0])

    def test_a_record_that_is_not_a_json_object_is_not_copied_and_leaves_an_explicit_gap(self):
        start = len(self.HEADER)
        source = self.HEADER + self.diag(0) + b"[1,2,3]\n" + self.diag(2)
        end = start + len(self.diag(0)) + len(b"[1,2,3]\n") + len(self.diag(2))
        records, target, path = self.replay(source, start, end)
        self.assertEqual(records[0], json.loads(self.diag(0)))
        self.assertEqual(len(records), 2, records)                                        # the first record and the gap only
        gap = self.not_copied(records)
        self.assertEqual(len(gap), 1, records)
        self.assertEqual(gap[0]["copied_records"], 1)
        self.assertIn("not a JSON object", gap[0]["reason"])

    def test_a_record_that_the_decoder_cannot_parse_at_this_depth_leaves_an_explicit_gap(self):
        # Python versions before 3.14 raise RecursionError for a deeply nested record; 3.14 parses it, so the decoder is faked
        start = len(self.HEADER)
        deep = b'{"a":' + b"[" * 30 + b"]" * 30 + b"}\n"
        source = self.HEADER + self.diag(0) + deep
        end = start + len(self.diag(0)) + len(deep)

        def loads(data):
            if data.startswith(b'{"a":'):
                raise RecursionError("maximum recursion depth exceeded while decoding a JSON object")
            return json.loads(data)
        decoder = types.SimpleNamespace(loads=loads, dumps=json.dumps, JSONDecodeError=json.JSONDecodeError)
        records, target, path = self.replay(source, start, end, json=decoder)
        self.assertEqual([r["path"] for r in records if r.get("kind") == "discovery_error"], ["/w/reports/d0"])
        gap = self.not_copied(records)
        self.assertEqual(len(gap), 1, records)
        self.assertEqual((gap[0]["copied_records"], gap[0]["range"]), (1, [start, end]))
        self.assertTrue(gap[0]["reason"].startswith("RecursionError"), gap[0])

