    def test_two_different_identities_whose_nul_joined_parts_are_equal_are_both_failing_tests(self):
        data = b"FAIL: x (m.C\x00t.u)\nFAIL: x (m.C.t\x00u)\nFAILED (failures=2)\n"
        rc, out, err = self.emit_bytes(data)
