    def test_sgr_coloured_pytest_blocks_are_matched_keep_their_raw_bytes_and_have_a_message_without_the_colours(self):
        raw = (b"\x1b[31m\x1b[1m=================================== FAILURES ===================================\x1b[0m\n"
               b"\x1b[31m\x1b[1m" + b"_" * 20 + b" test_fail " + b"_" * 20 + b"\x1b[0m\n"
               b"\x1b[1m\x1b[31mE       assert 1 == 2\x1b[0m\n"
               b"\x1b[33m=========================== short test summary info ============================\x1b[0m\n"
               b"\x1b[31mFAILED\x1b[0m test_x.py::test_fail - assert 1 == 2\n")
        rc, out, err = self.emit_bytes(raw)
        records = self.records()
        failure = self.failures()[0]
        self.assertEqual((failure.get("block"), failure["log_lines"], self.message_of(records, failure)),
                         (1, [2, 3], "    assert 1 == 2"))
        self.assertEqual(self.body_of(records, 1), self.lines_text(raw, 2, 3))
        self.assertIn("\x1b[1m\x1b[31mE ", self.body_of(records, 1))

    def test_a_text_message_longer_than_one_chunk_is_recoverable_from_its_message_chunk_records_and_cut_exactly_in_the_summary(self):
        long = "".join("word%d " % i for i in range(9000))                       # 79890 characters in ONE E line
        raw = (self.PY_FAILURES + self.py_header("test_long") + b"E   " + long.encode() + b"\n" + self.PY_SUMMARY
               + b"FAILED test_l.py::test_long - short\n")
        rc, out, err = self.emit_bytes(raw)
        records = self.records()
        failure = self.failures()[0]
        self.assertEqual(len(failure["message"]), 16384)
        self.assertEqual((failure["message_chars"], failure["message_more"]), (len(long), 4))
        self.assertEqual(self.message_of(records, failure), long)
        cut = len(long) - 300
        lines = self.text_lines(out)
        self.assertIn("detail #1: " + long[:300] + "[...+%d characters]" % cut, lines)
        self.assertRegex(lines[-1], r"(^|; )\d+ lines or messages cut(;|$)")

    def test_an_unittest_exception_report_longer_than_one_chunk_is_recoverable_from_its_message_chunk_records(self):
        long = "x" * 40000
        raw = (b"FAIL: t (m.T.t)\n----------------------------------------------------------------------\n"
               b"Traceback (most recent call last):\n  File \"t.py\", line 1, in t\nAssertionError: " + long.encode() + b"\nsecond\n")
        rc, out, err = self.emit_bytes(raw)
        records = self.records()
        failure = self.failures()[0]
        expected = "AssertionError: " + long + "\nsecond"
        self.assertEqual((failure["message_chars"], failure["message_more"]), (len(expected), 2))
        self.assertEqual(self.message_of(records, failure), expected)
        self.assertEqual(self.body_of(records, 1), raw.decode())

    # ---- R16/R05/R04/R13: streaming, chunk boundaries, long lines, Unicode, storage segments ---------------------------

    def limited(self, code, limit=100, wrapper_args=(), **kw):
        """Run the wrapper with a hard RLIMIT_FSIZE of `limit` bytes for itself (and the command it starts)."""
        return self.wrap(self.py(code), wrapper_args,
                         preexec_fn=lambda: resource.setrlimit(resource.RLIMIT_FSIZE, (limit, limit)), **kw)

    def analyze(self, raw, sizes=None, budget=20000):
        """The failures-index records a Sink writes for the written stream `raw` (one segment file) when the analyzer is
        fed in chunks of the given sizes (cycled), by default in one piece. Returns (module, sink, analyzer, records)."""
        module, sink, analyzer, index_path = self.run_analysis(raw, sizes, budget)
        records = [json.loads(line) for line in index_path.read_text(encoding="utf-8").splitlines()]
        return module, sink, analyzer, records

    def run_analysis(self, raw, sizes=None, budget=20000, cap=None, before=None):
        """The analysis itself, nothing read back: (module, sink, analyzer, path of the failures index). With `cap` the
        module's DEDUP_CAP is lowered; `before(sink)` runs before the first byte is fed."""
        module = rc_load()
        if cap is not None:
            module.DEDUP_CAP = cap
        log = self.root / "unit.log"
        log.write_bytes(raw)
        capture = types.SimpleNamespace(segments=[types.SimpleNamespace(path=str(log), bytes=len(raw))], unwritten=0)
        index_path = self.root / "unit.failures.jsonl"
        if index_path.exists():
            index_path.unlink()
        index = module.Index(str(index_path))
        sink = module.Sink(index, budget)
        sink.stream = capture
        if before:
            before(sink)
        analyzer = module.LogAnalyzer(sink.text_hit)
        position, turn = 0, 0
        while position < len(raw):
            size = len(raw) if not sizes else sizes[turn % len(sizes)]
            analyzer.feed(raw[position:position + size])
            position += size
            turn += 1
        analyzer.finish()
        index.close()
        return module, sink, analyzer, index_path

    def mixed_transcript(self):
        """A transcript with CRLF and LF lines, SGR colours, multi-byte characters, an invalid byte, a subTest suffix, and
        unittest and pytest failure blocks (one pytest block without a FAILED line, one FAILED line without a block)."""
        return (b"..F\r\n"
                b"======================================================================\r\n"
                b"\x1b[31mFAIL\x1b[0m\x1b[1;31m: test_\xc3\xa9 (m.T.test_\xc3\xa9) (s='\xe6\x97\xa5\xe6\x9c\xac \xf0\x9f\x98\x80')\x1b[0m\r\n"
                b"----------------------------------------------------------------------\r\n"
                b"Traceback (most recent call last):\r\n"
                b"  File \"t.py\", line 3, in test\r\n"
                b"AssertionError: caf\xc3\xa9 \xff bad \xe6\x97\xa5\r\n"
                b"\r\n"
                b"======================================================================\n"
                b"ERROR: test_e (m.T.test_e)\n"
                b"----------------------------------------------------------------------\n"
                b"Traceback (most recent call last):\n"
                b"ValueError: two\nsecond \xf0\x9f\x98\x80\n"
                b"\n"
                b"----------------------------------------------------------------------\n"
                b"Ran 2 tests in 0.1s\n\nFAILED (failures=1, errors=1)\n"
                + self.PY_FAILURES + self.py_header("test_p") + b"E   \x1b[31mboom\x1b[0m \xc3\xa9\n"
                + self.py_header("test_q") + b"E   q\n" + self.py_header("test_orphan") + b"E   orphan\n" + self.PY_SUMMARY
                + b"FAILED t.py::test_p - boom\nFAILED t.py::test_q - q\nFAILED t.py::test_r - r\n" + self.PY_RESULT)

    def test_the_mixed_transcript_is_indexed_as_expected_in_one_piece(self):
        raw = self.mixed_transcript()
        module, sink, analyzer, records = self.analyze(raw)
        failures = [r for r in records if r["type"] == "failure"]
        self.assertEqual([(f["classname"], f["name"], f["subtest"], f["block"]) for f in failures],
                         [("m.T", "test_\u00e9", "(s='\u65e5\u672c \U0001f600')", 1), ("m.T", "test_e", None, 2),
                          ("t", "test_p", None, 3), ("t", "test_q", None, 4), ("t", "test_r", None, None)])
        self.assertEqual([self.message_of(records, f) for f in failures],
                         ["AssertionError: caf\u00e9 \udcff bad \u65e5", "ValueError: two\nsecond \U0001f600", "boom \u00e9",
                          "q", "r"])
        self.assertEqual([(b["runner"], b["outcome"]) for b in self.text_blocks(records)],
                         [("unittest", "failure"), ("unittest", "failure"), ("pytest", "failure"), ("pytest", "failure"),
                          ("pytest", "unmatched")])
        self.assertEqual(self.body_of(records, 1).encode("utf-8", "surrogateescape"),
                         raw[self.line_start(raw, 3):self.line_start(raw, 9)])
        self.assertEqual((analyzer.runner_failed, analyzer.line_count), (2 + 3, raw.count(b"\n")))

    def test_the_records_do_not_depend_on_how_the_stream_is_cut_into_chunks_seeded_partitions(self):
        import random
        raw = self.mixed_transcript()
        expected = self.analyze(raw)[3]
        rng = random.Random(20260930)
        for turn in range(24):
            sizes = [rng.randint(1, 40 if turn % 2 else 300) for _ in range(rng.randint(1, 6))]
            with self.subTest(partition=turn, sizes=sizes):
                self.assertEqual(self.analyze(raw, sizes)[3], expected)

    def test_the_records_do_not_depend_on_a_chunk_boundary_inside_a_multibyte_character_a_colour_a_header_or_a_line_end(self):
        raw = self.mixed_transcript()
        expected = self.analyze(raw)[3]
        places = {"inside e-acute": raw.index(b"caf\xc3\xa9") + 4, "inside the emoji": raw.index(b"\xf0\x9f\x98\x80") + 2,
                  "after ESC": raw.index(b"\x1b[31mFAIL") + 1, "inside the colour": raw.index(b"\x1b[31mFAIL") + 3,
                  "inside ERROR:": raw.index(b"ERROR: test_e") + 3, "inside the separator": raw.index(b"=====") + 30,
                  "between CR and LF": raw.index(b"\r\n") + 1, "before LF": raw.index(b"ValueError: two") + 15,
                  "inside a pytest banner": raw.index(b" FAILURES ") + 4, "inside the E prefix": raw.index(b"E   \x1b[31mboom") + 2}
        for name, at in places.items():
            with self.subTest(split=name):
                self.assertEqual(self.analyze(raw, [at, len(raw)])[3], expected)

    def big_block(self, size):
        """Three unittest failure blocks whose bodies hold about `size` bytes of 1000-byte lines each."""
        line = b"    " + b"y" * 995 + b"\n"
        block = (b"======================================================================\n"
                 b"FAIL: t%d (m.T.t%d)\n----------------------------------------------------------------------\n"
                 b"Traceback (most recent call last):\n  File \"t.py\", line 1, in t\n" + line * (size // 1000)
                 + b"AssertionError: end%d\n\n")
        return b"".join(block.replace(b"%d", b"%d" % n) for n in range(3))

    def test_a_16_mebibyte_block_body_is_streamed_with_the_same_bounded_memory_as_a_1_mebibyte_one(self):
        import tracemalloc
        peaks = {}
        for size in (1 << 20, 16 << 20):
            raw = self.big_block(size)
            tracemalloc.start()
            tracemalloc.reset_peak()
            module, sink, analyzer, index_path = self.run_analysis(raw, [65536])
            peaks[size] = tracemalloc.get_traced_memory()[1]
            tracemalloc.stop()
            records = [json.loads(line) for line in index_path.read_text(encoding="utf-8").splitlines()]
            for n in (1, 2, 3):
                text = self.body_of(records, n)
                start = raw.index(b"FAIL: t%d " % (n - 1))
                end = raw.index(b"\n\n", start) + 2
                self.assertEqual(hashlib.sha256(text.encode("utf-8")).hexdigest(), hashlib.sha256(raw[start:end]).hexdigest())
            self.assertEqual([self.message_of(records, f) for f in records if f["type"] == "failure"],
                             ["AssertionError: end0", "AssertionError: end1", "AssertionError: end2"])
            del records, raw
        self.assertLess(peaks[16 << 20] - peaks[1 << 20], 8 << 20, peaks)

    def test_an_unfinished_escape_sequence_in_a_message_is_held_in_bounded_memory_and_kept_exactly(self):
        import tracemalloc
        peaks = {}
        for size in (1 << 20, 16 << 20):
            raw = (b"FAIL: t (m.T.t)\n" + b"-" * 70 + b"\nTraceback (most recent call last):\n  File \"t.py\", line 1, in t\n"
                   b"AssertionError: \x1b[" + b"1" * size + b"\n\n")
            tracemalloc.start()
            tracemalloc.reset_peak()
            module, sink, analyzer, index_path = self.run_analysis(raw, [65536])
            peaks[size] = tracemalloc.get_traced_memory()[1]
            tracemalloc.stop()
            records = [json.loads(line) for line in index_path.read_text(encoding="utf-8").splitlines()]
            failure = [r for r in records if r["type"] == "failure"][0]
            self.assertEqual(self.message_of(records, failure), "AssertionError: \x1b[" + "1" * size)
            self.assertEqual(self.body_of(records, 1), raw.decode())
            del records, raw
        self.assertLess(peaks[16 << 20] - peaks[1 << 20], 8 << 20, peaks)

    def test_a_colour_sequence_of_more_than_256_parameter_characters_is_not_removed_whatever_the_chunking(self):
        raw = (b"FAIL: t (m.T.t)\n" + b"-" * 70 + b"\nTraceback (most recent call last):\n  File \"t.py\", line 1, in t\n"
               b"AssertionError: a\x1b[" + b"1" * 256 + b"mb\x1b[" + b"2" * 257 + b"mc\n\n")
        expected = "AssertionError: ab\x1b[" + "2" * 257 + "mc"                  # 256 characters is a colour, 257 is not
        for sizes in (None, [1], [5], [256], [300], [16, 4000]):
            with self.subTest(sizes=sizes):
                module, sink, analyzer, records = self.analyze(raw, sizes)
                failure = [r for r in records if r["type"] == "failure"][0]
                self.assertEqual(self.message_of(records, failure), expected)
        self.assertEqual(self.analyze(b"\x1b[" + b"1" * 256 + b"mFAIL: t (m.T.t)\n")[1].count, 1)
        self.assertEqual(self.analyze(b"\x1b[" + b"1" * 257 + b"mFAIL: t (m.T.t)\n")[1].count, 0)

    def subtest_log(self, count):
        return b"".join(b"FAIL: t (m.T.t) (i=%d)\n" % i for i in range(count))

    def test_distinct_subtest_suffixes_of_a_junit_failure_beyond_the_cap_keep_every_observation_without_an_occurrence_number(self):
        (self.root / "fixture.bin").write_bytes(self.subtest_log(40))
        (self.root / "report.xml").write_bytes(self.junit(("m.T", "t")))
        module, rc, out = self.inproc([], self.py(self.EMIT_FILE, str(self.root / "fixture.bin"), "1", str(self.root / "report.xml")),
                                      {"DEDUP_CAP": 1})
        records = self.records()
        observations = [r for r in records if r["type"] == "observation"]
        self.assertEqual([r["subtest"] for r in observations], ["(i=%d)" % i for i in range(40)])
        self.assertEqual([r["occurrence"] for r in observations], [1] + [None] * 39)      # the first key is tracked, the rest are not
        self.assertEqual(len([c for c in records if c["type"] == "coverage" and c["kind"] == "occurrences_capped"]), 1)
        lines = self.text_lines(out)
        self.assertIn("failing tests: 1 identified (junit 1, text-heuristic 0)", lines)
        self.assertEqual([l for l in lines if l.startswith("WARNING: runner")], [])
        self.assertIn("WARNING: more than 1 distinct subTest identities: later ones carry no occurrence number", lines)

    def test_the_table_of_subtest_occurrences_stays_bounded_while_distinct_suffixes_grow(self):
        import tracemalloc
        held = {}
        for count in (5000, 20000):
            raw = self.subtest_log(count)
            tracemalloc.start()
            tracemalloc.reset_peak()
            module, sink, analyzer, index_path = self.run_analysis(
                raw, [65536], cap=1, before=lambda sink: sink.failure("junit", "m.T", "t", None, {}, "m", "failure"))
            held[count] = tracemalloc.get_traced_memory()[0]
            tracemalloc.stop()
            self.assertEqual(sink.subtest_observations, count)           # every occurrence is still counted
            self.assertLessEqual(len(sink.occurrences), 1)
            del raw, sink, analyzer
        self.assertLess(held[20000] - held[5000], 512 << 10, held)

    def test_the_metadata_kept_for_twenty_thousand_pytest_blocks_is_fixed_size_per_block(self):
        import tracemalloc
        count = 20000
        raw = (self.PY_FAILURES + b"".join(self.py_header("test_%06d" % i) + b"E   boom %d\n" % i for i in range(count)) + self.PY_SUMMARY
               + b"".join(b"FAILED t.py::test_%06d - boom\n" % i for i in range(count)))
        log = self.root / "unit.log"
        log.write_bytes(raw)
        module = rc_load()
        capture = types.SimpleNamespace(segments=[types.SimpleNamespace(path=str(log), bytes=len(raw))], unwritten=0)
        index = module.Index(str(self.root / "unit.failures.jsonl"))
        sink = module.Sink(index, 4000)
        sink.stream = capture
        analyzer = module.LogAnalyzer(sink.text_hit)
        tracemalloc.start()
        tracemalloc.reset_peak()
        for at in range(0, len(raw), 65536):
            analyzer.feed(raw[at:at + 65536])
        held = tracemalloc.get_traced_memory()[0]
        tracemalloc.stop()
        analyzer.finish()
        index.close()
        self.assertEqual((sink.blocks, sink.count), (count, count))
        self.assertLess(held, 12 << 20, "%d bytes held for %d blocks and FAILED lines" % (held, count))

    def header_line(self, length):
        """An unittest header line of exactly `length` bytes (without its LF)."""
        return b"FAIL: t (" + b"a" * (length - 10) + b")"

    def test_a_header_line_of_65535_and_65536_bytes_is_identified_and_of_65537_bytes_is_declared_partially_examined(self):
        for length, identified in ((65535, True), (65536, True), (65537, False)):
            with self.subTest(length=length):
                shutil.rmtree(self.logs, ignore_errors=True)
                raw = self.header_line(length) + b"\nnext\n"
                rc, out, err = self.emit_bytes(raw, wrapper_args=["--max-bytes", "9000"])
                lines = self.text_lines(out)
                self.assertEqual("failing tests: 1 identified (junit 0, text-heuristic 1)" in lines, identified)
                self.assertEqual("failing tests not identified" in lines, not identified)
                self.assertEqual("1 lines only partially examined" in lines[-1], not identified)
                self.assertIn("· 2 log lines ·", lines[0])
                if identified:
                    self.assertEqual(self.failures()[0]["log_lines"], [1, 2])
                    self.assertEqual(self.body_of(self.records(), 1), raw.decode())

    def test_a_line_beyond_the_examination_limit_is_body_text_of_an_open_block_and_never_a_separator(self):
        raw = (b"FAIL: t (m.T.t)\n----\nTraceback (most recent call last):\n  File \"x\", line 1\n" + b"=" * 70000 + b"\n"
               b"AssertionError: after the long line\n===\ntail\n")
        rc, out, err = self.emit_bytes(raw)
        failure = self.failures()[0]
        self.assertEqual(failure["log_lines"], [1, 6])
        self.assertEqual(self.message_of(self.records(), failure), "=" * 70000 + "\nAssertionError: after the long line")
        self.assertEqual(self.body_of(self.records(), 1), self.lines_text(raw, 1, 6))
        self.assertIn("1 lines only partially examined", self.text_lines(out)[-1])

    def test_an_exception_line_beyond_the_examination_limit_still_starts_the_message(self):
        raw = (b"FAIL: t (m.T.t)\n----\nTraceback (most recent call last):\n  File \"x\", line 1\n"
               b"AssertionError: " + b"z" * 70000 + b"\nsecond line\n===\n")
        rc, out, err = self.emit_bytes(raw)
        records = self.records()
        failure = self.failures()[0]
        expected = "AssertionError: " + "z" * 70000 + "\nsecond line"
        self.assertEqual((failure["message_from"], failure["message_chars"]), ("traceback", len(expected)))
        self.assertEqual(self.message_of(records, failure), expected)

    def test_a_nine_mebibyte_line_is_streamed_in_full_and_the_failure_after_it_is_identified(self):
        raw = (b"FAIL: a (m.T.a)\n----\n" + b"z" * (9 << 20) + b"\nFAIL: b (m.T.b)\n")
        rc, out, err = self.emit_bytes(raw)
        records = self.records()
        self.assertEqual([(f["name"], f["log_lines"]) for f in self.failures()], [("a", [1, 3]), ("b", [4, 4])])
        self.assertEqual(hashlib.sha256(self.body_of(records, 1).encode()).hexdigest(),
                         hashlib.sha256(raw[:raw.index(b"FAIL: b")]).hexdigest())
        lines = self.text_lines(out)
        self.assertIn("· 4 log lines ·", lines[0])
        self.assertIn("1 lines only partially examined", lines[-1])

    def test_a_final_header_line_without_a_line_feed_is_identified_and_not_counted_as_partially_examined(self):
        rc, out, err = self.emit_bytes(b"noise\nFAIL: t (m.T.t)")
        lines = self.text_lines(out)
        self.assertIn("#1 m.T.t [text-heuristic]", lines)
        self.assertNotIn("partially examined", lines[-1])
        self.assertEqual((self.failures()[0]["log_lines"], self.body_of(self.records(), 1)), ([2, 2], "FAIL: t (m.T.t)"))

    def test_multibyte_characters_invalid_bytes_and_nul_survive_a_block_body_across_read_chunks(self):
        # a 4-byte character starts one byte before the 65536-byte read chunk boundary of the stream
        head = b"FAIL: t (m.T.t)\n----\nTraceback (most recent call last):\n"
        filler = b"  " + b"a" * (65535 - len(head) - 2)
        body = filler + "\U0001f600".encode() + b"\xff\xfe\x80\x00 tail \xc3\xa9\nAssertionError: caf\xc3\xa9 \x00\xff\n=====\n"
        raw = head + body
        rc, out, err = self.emit_bytes(raw)
        records = self.records()
        failure = self.failures()[0]
        self.assertEqual(self.body_of(records, 1).encode("utf-8", "surrogateescape"), raw[:raw.index(b"=====")])
        self.assertEqual(self.message_of(records, failure), "AssertionError: caf\u00e9 \x00\udcff")
        self.assertEqual(failure["log_lines"], [1, 5])
        lines = self.text_lines(out)
        self.assertIn("detail #1: AssertionError: caf\u00e9 \\x00\\xff", lines)
        self.assertEqual(self.only_log().read_bytes(), raw)

    def test_normalisation_forms_astral_characters_and_bidi_controls_in_identities_are_kept_distinct_and_exact(self):
        import unicodedata
        nfc, nfd = unicodedata.normalize("NFC", "caf\u00e9"), unicodedata.normalize("NFD", "caf\u00e9")
        self.assertNotEqual(nfc, nfd)
        raw = ("FAIL: t (m.%s.t)\nFAIL: t (m.%s.t)\nFAIL: t (m.\U0001f600.t)\nFAIL: t (m.a\u202eb.t)\nFAILED (failures=4)\n"
               % (nfc, nfd)).encode("utf-8")
        rc, out, err = self.emit_bytes(raw)
        self.assertEqual([f["classname"] for f in self.failures()], ["m." + nfc, "m." + nfd, "m.\U0001f600", "m.a\u202eb"])
        self.assertEqual([l for l in self.text_lines(out) if l.startswith("WARNING")], [])
        self.assertIn("#4 m.a\u202eb.t [text-heuristic]", self.text_lines(out))

    def test_a_real_file_size_limit_that_splits_the_log_leaves_a_block_that_spans_two_segments_complete_in_the_index(self):
        code = ("import os, sys\n"
                "def w(b):\n"
                "    v = memoryview(b)\n"
                "    while v: v = v[os.write(1, v):]\n"
                "w(b'ok line\\n' * 6000)\n"
                "w(b'FAIL: t (m.T.t)\\n' + b'-' * 70 + b'\\nTraceback (most recent call last):\\n  File \"x\", line 1\\n')\n"
                "w((b'  body ' + b'y' * 92 + b'\\n') * 200)\n"
                "w(b'AssertionError: end\\n\\n' + b'=' * 70 + b'\\n')\n"
                "w(b'tail\\n' * 3000)\n"
                "sys.exit(1)\n")
        expected = (b"ok line\n" * 6000 + b"FAIL: t (m.T.t)\n" + b"-" * 70 + b"\nTraceback (most recent call last):\n  File \"x\", line 1\n"
                    + (b"  body " + b"y" * 92 + b"\n") * 200 + b"AssertionError: end\n\n" + b"=" * 70 + b"\n" + b"tail\n" * 3000)
        rc, out, err = self.limited(code, 65536, ["--max-bytes", "9000"])
        self.assertEqual(rc, 1, (out, err))
        lines = self.text_lines(out)
        self.assertTrue(any(l.startswith("log continued:") for l in lines), lines)
        self.assertFalse([l for l in lines if l.startswith("failures index: INCOMPLETE")], lines)
        records = self.records()
        capture = [r for r in records if r["type"] == "capture"][0]
        self.assertEqual(len(capture["segments"]), 2)
        joined = b"".join(Path(seg["path"]).read_bytes() for seg in capture["segments"])
        self.assertEqual(joined, expected)
        self.assertLess(capture["segments"][0]["bytes"], self.line_start(expected, 6001) + 20000)
        failure = self.failures()[0]
        self.assertEqual(failure["log_lines"], [6001, 6206])
        self.assertEqual(self.body_of(records, 1), self.lines_text(expected, 6001, 6206))
        self.assertEqual(self.message_of(records, failure), "AssertionError: end")
        self.assertEqual(records[-1]["type"], "end")

    def test_a_pytest_failures_section_that_spans_two_segments_is_matched_and_complete(self):
        code = ("import os, sys\n"
                "def w(b):\n"
                "    v = memoryview(b)\n"
                "    while v: v = v[os.write(1, v):]\n"
                "w(b'ok line\\n' * 6000)\n"
                "w(b'=' * 20 + b' FAILURES ' + b'=' * 20 + b'\\n' + b'_' * 20 + b' test_big ' + b'_' * 20 + b'\\n')\n"
                "w((b'    code line ' + b'y' * 85 + b'\\n') * 200)\n"
                "w(b'E   the message\\n')\n"
                "w(b'=' * 20 + b' short test summary info ' + b'=' * 20 + b'\\nFAILED t.py::test_big - the message\\n')\n"
                "sys.exit(1)\n")
        rc, out, err = self.limited(code, 65536, ["--max-bytes", "9000"])
        records = self.records()
        capture = [r for r in records if r["type"] == "capture"][0]
        self.assertEqual(len(capture["segments"]), 2)
        joined = b"".join(Path(seg["path"]).read_bytes() for seg in capture["segments"])
        failure = self.failures()[0]
        self.assertEqual((failure["block"], failure["log_lines"], failure["summary_line"]), (1, [6002, 6203], 6205))
        self.assertEqual(self.body_of(records, 1), self.lines_text(joined, 6002, 6203))
        self.assertEqual(self.message_of(records, failure), "the message")

    # ---- R11/R12: detached descendants, a block cut by the pending prefix, index write faults ------------------------------

    @staticmethod
    def alive(pid):
        try:
            os.kill(pid, 0)
        except ProcessLookupError:
            return False
        except PermissionError:
            return True
        return True

    def wait_for(self, path, seconds=25):
        deadline = time.time() + seconds
        while time.time() < deadline:
            if Path(path).exists():
                return True
            time.sleep(0.1)
        return False

    def wait_gone(self, pid, seconds=15):
        """True once the process is gone; a worker forked by an in-process run is our own child and is reaped here."""
        deadline = time.time() + seconds
        while time.time() < deadline:
            try:
                if os.waitpid(pid, os.WNOHANG)[0] == pid:
                    return True
            except ChildProcessError:
                pass
            if not self.alive(pid):
                return True
            time.sleep(0.1)
        return False

    def finish_worker(self, out, seconds=25):
        """Wait for the worker of a CAPTURE_PENDING run to write complete.json and end; returns (stem, complete.json)."""
        match = re.search(rb"background worker pid (\d+)", out)
        self.assertIsNotNone(match, out)
        pid = int(match.group(1))
        (self.root / "worker.pid").write_text(str(pid))
        stem = str(self.only_log())[:-len(".log")]
        try:
            self.assertTrue(self.wait_for(stem + ".complete.json", seconds), "the worker never wrote complete.json")
            self.assertTrue(self.wait_gone(pid), "the worker is still alive after it wrote the sidecar")
            return stem, json.loads(Path(stem + ".complete.json").read_text())
        finally:
            try:
                os.kill(pid, signal.SIGKILL)
            except OSError:
                pass
            self.wait_gone(pid, 5)

    LEAD = ("import os, subprocess, sys\n"
            "os.write(1, sys.argv[1].encode())\n"
            "subprocess.Popen([sys.executable, '-c', sys.argv[2], sys.argv[3], sys.argv[4]], start_new_session=True)\n")
    LATE = ("import os, sys, time\n"
            "time.sleep(float(sys.argv[1]))\n"
            "os.write(1, sys.argv[2].encode())\n")

    def test_a_block_cut_by_the_pending_prefix_is_marked_and_the_final_artifacts_hold_it_complete_with_the_late_failures(self):
        rule = "-" * 70
        head = "FAIL: t1 (m.T.t1)\n%s\nTraceback (most recent call last):\n  File \"a.py\", line 1, in t1\n" % rule
        late = ("AssertionError: late message\n\n" + "=" * 70 + "\nFAIL: t2 (m.T.t2)\n%s\nTraceback (most recent call last):\n"
                "  File \"a.py\", line 2, in t2\nKeyError: 'k'\n\n%s\nRan 2 tests in 0.1s\n\nFAILED (failures=2)\n" % (rule, rule))
        module, rc, out = self.inproc([], self.py(self.LEAD, head, self.LATE, "1.5", late), {"DRAIN_SECONDS": 0.3})
        self.assertEqual(rc, 0, out)
        lines = self.text_lines(out)
        self.assertRegex(lines[0], r"^COMMAND_EXIT 0 · exit code 0 · CAPTURE_PENDING · ")
        self.assertIn("failing tests: 1 identified so far (junit 0, text-heuristic 1)", lines)
        stem = str(self.only_log())[:-len(".log")]
        early = [json.loads(l) for l in Path(stem + ".failures.jsonl").read_text().splitlines()]
        cut = [r for r in early if r["type"] == "text_block"]
        self.assertEqual([(b["log_lines"], b["ended_by"]) for b in cut], [([1, 4], "prefix_end")])
        self.assertEqual(self.body_of(early, 1), head)
        stem, complete = self.finish_worker(out)
        self.assertIs(complete["complete"], True)
        self.assertEqual((complete["status"], complete["exit_code"]), ("COMMAND_EXIT 0", 0))
        stream = (head + late).encode()
        self.assertEqual(b"".join(Path(seg["path"]).read_bytes() for seg in complete["segments"]), stream)
        final = [json.loads(l) for l in Path(stem + ".final-failures.jsonl").read_text().splitlines()]
        failures = [r for r in final if r["type"] == "failure"]
        self.assertEqual([(f["name"], f["log_lines"], self.message_of(final, f)) for f in failures],
                         [("t1", [1, 6], "AssertionError: late message"), ("t2", [8, 13], "KeyError: 'k'")])
        self.assertEqual([b["ended_by"] for b in final if b["type"] == "text_block"], ["separator", "summary"])
        self.assertEqual(self.body_of(final, 1), self.lines_text(stream, 1, 6))
        self.assertEqual(self.body_of(final, 2), self.lines_text(stream, 8, 13))
        self.assertEqual(final[-1]["type"], "end")
        summary = Path(stem + ".final-summary.txt").read_text(encoding="utf-8").splitlines()
        self.assertIn("failing tests: 2 identified (junit 0, text-heuristic 2)", summary)
        self.assertEqual([l for l in summary if l.startswith("WARNING")],
                         ["WARNING: command exited 0 but the log lists 2 text-heuristic failing tests"])      # and no runner warning

    def test_index_write_errors_in_the_middle_of_a_block_body_leave_only_whole_records_and_the_failure_is_still_listed(self):
        body = b"".join(b"  frame line %05d " % i + b"y" * 60 + b"\n" for i in range(1500))              # about 120 kB
        raw = (b"FAIL: t (m.T.t)\n----\nTraceback (most recent call last):\n" + body + b"AssertionError: boom\n===\n")
        (self.root / "fixture.bin").write_bytes(raw)
        budget = {"left": 30000}
        indexes = set()

        class OsProxy:
            def __getattr__(self, name):
                return getattr(os, name)

            def open(self, path, *args, **kwargs):
                fd = os.open(path, *args, **kwargs)
                if str(path).endswith(".failures.jsonl"):
                    indexes.add(fd)
                return fd

            def write(self, fd, data):
                if fd in indexes:
                    if budget["left"] <= 0:
                        raise OSError(errno.ENOSPC, "No space left on device")
                    data = bytes(data)[:budget["left"]]                 # a partial write, then the disk is full
                    budget["left"] -= len(data)
                return os.write(fd, data)
        module, rc, out = self.inproc(["--max-bytes", "9000"], self.py(self.EMIT_FILE, str(self.root / "fixture.bin"), "1"),
                                      {"os": OsProxy()})
        self.assertEqual(rc, 1, out)
        lines = self.text_lines(out)
        self.assertEqual(self.only_log().read_bytes(), raw)
        self.assertRegex([l for l in lines if l.startswith("failures index:")][0],
                         r"^failures index: INCOMPLETE \(ENOSPC; \d+ records written, \d+ not written(; last record torn)?\): ")
        self.assertIn("failing tests: 1 identified (junit 0, text-heuristic 1)", lines)
        self.assertIn("detail #1: AssertionError: boom", lines)
        rows = Path(str(self.only_log())[:-4] + ".failures.jsonl").read_text(encoding="utf-8").splitlines()
        parsed = [json.loads(r) for r in rows]                                       # strict: no torn record
        self.assertNotIn("end", [r["type"] for r in parsed])
        self.assertTrue([r for r in parsed if r["type"] == "body"])
        self.assertEqual([r["seq"] for r in parsed if r["type"] == "body"], list(range(len([r for r in parsed if r["type"] == "body"]))))

    # ---- R01/R02/R08/R09/R10 -------------------------------------------------------------------------------------------

    FILLER = b"progress %06d " + b"." * 60 + b"\n"                     # 80 bytes

    def filler(self, lines, start=0):
        return b"".join(self.FILLER % (start + i) for i in range(lines))

    def test_an_unittest_failure_in_the_middle_of_a_5_mebibyte_log_beyond_the_tail_keeps_identity_message_body_and_range(self):
        before, after = self.filler(35000), self.filler(35000, 35000)                     # 2.6 MB each side
        block = (b"=" * 70 + b"\nFAIL: t (m.T.t)\n" + b"-" * 70 + b"\nTraceback (most recent call last):\n  File \"x.py\", line 1, in t\n"
                 b"AssertionError: MIDDLE 1 != 2\n\n" + b"-" * 70 + b"\nRan 1 test in 0.1s\n\nFAILED (failures=1)\n")
        raw = before + block + after
        self.assertGreater(len(raw), 5 << 20)
        rc, out, err = self.emit_bytes(raw)
        records = self.records()
        failure = self.failures()[0]
        first = 35000 + 2
        self.assertEqual((failure["name"], failure["log_lines"]), ("t", [first, first + 5]))
        self.assertEqual(self.message_of(records, failure), "AssertionError: MIDDLE 1 != 2")
        self.assertEqual(self.body_of(records, 1), self.lines_text(raw, first, first + 5))
        lines = self.text_lines(out)
        self.assertIn("failing tests: 1 identified (junit 0, text-heuristic 1)", lines)
        self.assertIn("detail #1: AssertionError: MIDDLE 1 != 2", lines)
        self.assertNotIn("last lines", " ".join(lines))
        self.assertEqual([l for l in lines if l.startswith("WARNING")], [])

    def test_a_pytest_failure_in_the_middle_of_a_log_beyond_the_tail_keeps_identity_message_body_and_range(self):
        before, after = self.filler(32768), self.filler(32768, 32768)
        section = (self.PY_FAILURES + self.py_header("test_mid") + b"    def test_mid():\n>       assert 1 == 2\nE       assert 1 == 2\n\n"
                   b"t.py:3: AssertionError\n" + self.PY_SUMMARY + b"FAILED t.py::test_mid - assert 1 == 2\n"
                   b"========================= 1 failed in 0.03s ==========================\n")
        raw = before + section + after
        rc, out, err = self.emit_bytes(raw)
        records = self.records()
        failure = self.failures()[0]
        first = 32768 + 2
        self.assertEqual((failure["name"], failure["block"], failure["log_lines"], failure["summary_line"]),
                         ("test_mid", 1, [first, first + 5], first + 7))
        self.assertEqual(self.body_of(records, 1), self.lines_text(raw, first, first + 5))
        self.assertEqual(self.message_of(records, failure), "    assert 1 == 2")
        self.assertIn("detail #1: assert 1 == 2", self.text_lines(out))

    def test_a_text_block_of_a_failure_that_a_junit_report_also_lists_is_an_observation_with_its_block(self):
        raw = (self.filler(1000) + b"=" * 70 + b"\nFAIL: t (m.T.t)\n" + b"-" * 70 + b"\nTraceback (most recent call last):\n"
               b"  File \"x.py\", line 1, in t\nAssertionError: both\n\n" + b"-" * 70 + b"\nRan 1 test in 0.1s\n" + self.filler(1000))
        rc, out, err = self.emit_bytes(raw, report=self.junit(("m.T", "t")))
        records = self.records()
        lines = self.text_lines(out)
        self.assertIn("failing tests: 1 identified (junit 1, text-heuristic 0)", lines)
        self.assertIn("#1 m.T.t [junit, also in log]", lines)
        observation = [r for r in records if r["type"] == "observation"][0]
        self.assertEqual((observation["id"], observation["block"], observation["log_lines"]), (1, 1, [1002, 1007]))
        self.assertEqual(self.body_of(records, 1), self.lines_text(raw, 1002, 1007))
        self.assertEqual([(b["outcome"], b["failure"]) for b in self.text_blocks(records)], [("observation", 1)])

    @staticmethod
    def ut_block(message, header=b"FAIL: t (m.T.t)"):
        """An unittest failure block (separator line first) whose exception report is `message` (bytes)."""
        return (b"=" * 70 + b"\n" + header + b"\n" + b"-" * 70 + b"\nTraceback (most recent call last):\n"
                b"  File \"x.py\", line 1, in t\n" + message + b"\n\n")

    def test_an_invalid_byte_of_a_failure_block_is_shown_escaped_in_the_numbered_excerpt_and_cuts_are_counted_in_bytes(self):
        long_line = b"    \xff" + b"\xc3\xa9" * 120                                  # 245 bytes: the cut at 240 falls inside a pair
        raw = (b"FAIL: t (m.T.t)\n" + b"-" * 70 + b"\nTraceback (most recent call last):\n  File \"x.py\", line 1, in t\n"
               + long_line + b"\nAssertionError: bad \xff byte \\xff\n")
        rc, out, err = self.emit_bytes(raw)
        lines = self.text_lines(out)
        self.assertLessEqual(len(out), 4000)
        self.assertIn("detail #1: AssertionError: bad \\xff byte \\\\xff", lines)       # the message: the byte, then the literal text
        at = lines.index("detail #1: AssertionError: bad \\xff byte \\\\xff")
        self.assertEqual(lines[at + 1:at + 5],
                         ["    3: Traceback (most recent call last):",
                          "    4:   File \"x.py\", line 1, in t",
                          "    5:     \\xff" + "\u00e9" * 117 + "[...+6 bytes]",               # 239 bytes shown, 245 - 239 cut
                          "    6: AssertionError: bad \\xff byte \\\\xff"])
        self.assertRegex(lines[-1], r"(^|; )1 lines or messages cut(;|$)")
        records = self.records()
        self.assertEqual(self.body_of(records, 1).encode("utf-8", "surrogateescape"), raw)            # the index keeps the exact bytes
        self.assertEqual(self.message_of(records, self.failures()[0]).encode("utf-8", "surrogateescape"),
                         b"AssertionError: bad \xff byte \\xff")

    def test_the_observation_of_a_junit_failure_keeps_the_message_of_its_text_block_with_its_metadata(self):
        raw = self.ut_block(b"AssertionError: both") + b"-" * 70 + b"\nRan 1 test in 0.1s\n"
        rc, out, err = self.emit_bytes(raw, report=self.junit(("m.T", "t")))
        records = self.records()
        observation = [r for r in records if r["type"] == "observation"][0]
        self.assertEqual((observation["id"], observation["block"], observation["message"], observation["message_from"],
                          observation["message_chars"], observation["message_more"]),
                         (1, 1, "AssertionError: both", "traceback", len("AssertionError: both"), 0))
        self.assertEqual(self.message_of(records, observation), "AssertionError: both")
        self.assertEqual(self.failures()[0]["message"], "m")              # the JUnit message is its own, never borrowed

    def test_the_observation_of_a_junit_failure_keeps_a_message_of_several_chunks_recoverable(self):
        long = "x" * 40000
        expected = "AssertionError: " + long + "\nsecond"
        raw = self.ut_block(b"AssertionError: " + long.encode() + b"\nsecond") + b"-" * 70 + b"\nRan 1 test in 0.1s\n"
        rc, out, err = self.emit_bytes(raw, report=self.junit(("m.T", "t")))
        records = self.records()
        observation = [r for r in records if r["type"] == "observation"][0]
        self.assertEqual(len(observation["message"]), 16384)
        self.assertEqual((observation["message_chars"], observation["message_more"]), (len(expected), 2))
        self.assertEqual(self.message_of(records, observation), expected)
        self.assertEqual(self.failures()[0]["message"], "m")

    def test_a_duplicate_text_failure_keeps_the_message_of_its_own_block_with_its_metadata(self):
        raw = self.ut_block(b"AssertionError: first") + self.ut_block(b"AssertionError: second") + b"-" * 70 + b"\nRan 2 tests in 0.1s\n"
        rc, out, err = self.emit_bytes(raw)
        records = self.records()
        duplicate = [r for r in records if r["type"] == "duplicate"][0]
        self.assertEqual((duplicate["block"], duplicate["message"], duplicate["message_from"], duplicate["message_chars"],
                          duplicate["message_more"]), (2, "AssertionError: second", "traceback", len("AssertionError: second"), 0))
        self.assertEqual(self.message_of(records, duplicate), "AssertionError: second")
        self.assertEqual(self.message_of(records, self.failures()[0]), "AssertionError: first")

    def test_a_duplicate_text_failure_keeps_a_message_of_several_chunks_recoverable(self):
        long = "y" * 40000
        expected = "AssertionError: " + long
        raw = self.ut_block(b"AssertionError: first") + self.ut_block(expected.encode()) + b"-" * 70 + b"\nRan 2 tests in 0.1s\n"
        rc, out, err = self.emit_bytes(raw)
        records = self.records()
        duplicate = [r for r in records if r["type"] == "duplicate"][0]
        self.assertEqual(len(duplicate["message"]), 16384)
        self.assertEqual((duplicate["block"], duplicate["message_chars"], duplicate["message_more"]), (2, len(expected), 2))
        self.assertEqual(self.message_of(records, duplicate), expected)
        self.assertEqual(self.message_of(records, self.failures()[0]), "AssertionError: first")

    INTERLEAVE = ("import os\n"
                  "def w(fd, text):\n"
                  "    os.write(fd, text.encode())\n"
                  "w(1, 'out 1\\n'); w(2, 'err 1\\n')\n"
                  "w(1, 'FAIL: t (m.T.t)\\n'); w(2, '-' * 70 + '\\n'); w(1, 'Traceback (most recent call last):\\n')\n"
                  "w(2, '  File \"x.py\", line 1, in t\\n'); w(1, 'Assertion'); w(2, 'Error: mixed\\n')\n"
                  "w(1, '\\n'); w(2, '=' * 70 + '\\n'); w(1, 'tail 1\\n'); w(2, 'ERROR only on stderr\\n')\n"
                  "raise SystemExit(1)\n")

    def test_stdout_and_stderr_writes_of_one_process_are_kept_in_write_order_also_inside_a_failure_block(self):
        rc, out, err = self.wrap(self.py(self.INTERLEAVE))
        expected = ("out 1\nerr 1\nFAIL: t (m.T.t)\n" + "-" * 70 + "\nTraceback (most recent call last):\n  File \"x.py\", line 1, in t\n"
                    "AssertionError: mixed\n\n" + "=" * 70 + "\ntail 1\nERROR only on stderr\n")
        self.assertEqual(self.only_log().read_bytes().decode(), expected)
        records = self.records()
        failure = self.failures()[0]
        self.assertEqual((failure["log_lines"], self.message_of(records, failure)), ([3, 8], "AssertionError: mixed"))
        self.assertEqual(self.body_of(records, 1), self.lines_text(expected.encode(), 3, 8))

    def test_an_error_that_exists_only_on_stderr_is_shown_in_the_error_lines_when_nothing_is_identified(self):
        rc, out, err = self.wrap(self.py("import os; os.write(1, b'out\\n'); os.write(2, b'error: only on stderr\\n'); raise SystemExit(3)"))
        lines = self.text_lines(out)
        self.assertEqual(rc, 3)
        self.assertIn("failing tests not identified", lines)
        self.assertIn("2: error: only on stderr", lines)

    def check_omissions(self, out, total, listed_expected=None, details_expected=None):
        """The omission accounting of a summary, counted from the summary itself: every '#N' row, every 'detail #N' line."""
        lines = out.decode("utf-8").splitlines()
        rows = [l for l in lines if re.match(r"^#\d+ ", l)]
        details = [l for l in lines if l.startswith("detail #")]
        last = lines[-1]
        not_listed = re.search(r"(\d+) of (\d+) failing tests not listed", last)
        not_shown = re.search(r"(\d+) of (\d+) failure details not shown", last)
        self.assertEqual(len(rows) + (int(not_listed.group(1)) if not_listed else 0), total, last)
        self.assertEqual(len(details) + (int(not_shown.group(1)) if not_shown else 0), total, last)
        marker = [l for l in lines if l.startswith("[... ")]
        self.assertEqual(len(marker), 1 if not_listed else 0)
        if not_listed:
            self.assertEqual(marker[0], "[... %d more failing tests not listed; full list in the failures index]" % int(not_listed.group(1)))
        if listed_expected is not None:
            self.assertEqual(len(rows), listed_expected)
        if details_expected is not None:
            self.assertEqual(len(details), details_expected)
        return rows, details

    def test_sixty_301_and_250_subtest_failures_are_all_indexed_and_every_omission_is_counted_exactly(self):
        cases = {"sixty": (b"".join(b"FAIL: t%03d (m.T.t%03d)\n" % (i, i) for i in range(60)), 60),
                 "301 distinct": (b"".join(b"FAIL: t%03d (m.T.t%03d)\n" % (i, i) for i in range(301)), 301),
                 "250 subtests": (b"".join(b"FAIL: t (m.T.t) (i=%d)\n" % i for i in range(250)) + b"FAILED (failures=250)\n", 250)}
        for name, (raw, total) in cases.items():
            with self.subTest(case=name):
                shutil.rmtree(self.logs, ignore_errors=True)
                rc, out, err = self.emit_bytes(raw, wrapper_args=["--max-bytes", "60000"])
                self.assertLessEqual(len(out), 60000)
                rows, details = self.check_omissions(out, total, listed_expected=total, details_expected=min(total, 200))
                self.assertEqual(len(self.failures()), total)
                self.assertIn("failing tests: %d identified (junit 0, text-heuristic %d)" % (total, total), self.text_lines(out))
                self.assertEqual([l for l in self.text_lines(out) if l.startswith("WARNING")], [])
                self.assertEqual(self.records()[-1]["failing_tests"], total)
                if total > 200:
                    self.assertIn("%d of %d failure details not shown" % (total - 200, total), self.text_lines(out)[-1])

    def test_restrictive_budgets_never_overstate_what_is_listed_and_count_every_omission(self):
        raw = b"".join(b"FAIL: t%03d (m.T.t%03d)\n" % (i, i) for i in range(301))
        floor = self.minimum(self.py(self.EMIT_FILE, str(self.root / "fixture.bin"), "1"))
        for cap in (floor, floor + 500, floor + 3000, 12000):
            with self.subTest(cap=cap):
                shutil.rmtree(self.logs, ignore_errors=True)
                rc, out, err = self.emit_bytes(raw, wrapper_args=["--max-bytes", str(cap)])
                self.assertLessEqual(len(out), cap)
                self.assertTrue(out.endswith(b"\n"))
                self.check_omissions(out, 301)
                self.assertEqual(len(self.failures()), 301)

    def test_a_nonzero_exit_with_an_all_passing_report_is_declared_not_identified_with_the_error_lines_and_the_tail(self):
        report = b'<testsuites><testsuite name="s"><testcase classname="a" name="b"/></testsuite></testsuites>'
        rc, out, err = self.emit_bytes(b"line 1\nerror: the build failed\nline 3\n", code=2, report=report)
        lines = self.text_lines(out)
        self.assertEqual(rc, 2)
        self.assertIn("failing tests not identified", lines)
        self.assertIn("2: error: the build failed", lines)
        self.assertIn("last lines (3 of 3):", lines)

    def test_a_command_that_writes_nothing_leaves_an_empty_log_and_an_honest_summary_for_every_exit_status(self):
        for code in (0, 1, 2):
            with self.subTest(exit=code):
                shutil.rmtree(self.logs, ignore_errors=True)
                rc, out, err = self.wrap(self.py("raise SystemExit(%d)" % code))
                lines = self.text_lines(out)
                self.assertEqual(rc, code)
                self.assertIn("· 0 log lines · 0 log bytes", lines[0])
                self.assertIn("failing tests: none identified", lines)
                self.assertEqual(lines[-1], "omitted: nothing")
                self.assertEqual(self.only_log().read_bytes(), b"")
        with self.subTest(exit="killed by SIGKILL"):
            shutil.rmtree(self.logs, ignore_errors=True)
            rc, out, err = self.wrap(self.py("import os, signal; os.kill(os.getpid(), signal.SIGKILL)"))
            lines = self.text_lines(out)
            self.assertEqual(rc, 137)
            self.assertTrue(lines[0].startswith("SIGNAL 9 (SIGKILL) · exit code 137 · "), lines[0])
            self.assertIn("failing tests: none identified", lines)

    def test_a_command_killed_by_a_signal_in_the_middle_of_a_failure_block_keeps_the_partial_block_marked_as_cut_by_the_end_of_the_log(self):
        for sig in (signal.SIGSEGV, signal.SIGABRT, signal.SIGTERM, signal.SIGKILL):
            with self.subTest(signal=sig.name):
                shutil.rmtree(self.logs, ignore_errors=True)
                code = ("import os, resource, signal\n"
                        "resource.setrlimit(resource.RLIMIT_CORE, (0, 0))\n"
                        "signal.signal(signal.SIGTERM, signal.SIG_DFL)\n"
                        "os.write(1, b'FAIL: t (m.T.t)\\n' + b'-' * 70 + b'\\nTraceback (most recent call last):\\n  File \"x\", line 1\\nAssertionError: partly\\n')\n"
                        "os.kill(os.getpid(), signal.%s)\n" % sig.name)
                rc, out, err = self.wrap(self.py(code))
                lines = self.text_lines(out)
                self.assertEqual(rc, 128 + sig)
                self.assertTrue(lines[0].startswith("SIGNAL %d (%s) · exit code %d · " % (sig, sig.name, 128 + sig)), lines[0])
                self.assertIn("failing tests: 1 identified (junit 0, text-heuristic 1)", lines)
                self.assertIn("detail #1: AssertionError: partly", lines)
                records = self.records()
                self.assertEqual([(b["log_lines"], b["ended_by"]) for b in self.text_blocks(records)], [([1, 5], "eof")])
                self.assertEqual(self.message_of(records, self.failures()[0]), "AssertionError: partly")

    def test_a_timeout_in_the_middle_of_a_failure_block_keeps_the_partial_block_and_exits_124(self):
        code = ("import os, time\n"
                "os.write(1, b'FAIL: t (m.T.t)\\n' + b'-' * 70 + b'\\nTraceback (most recent call last):\\n  File \"x\", line 1\\nAssertionError: unfinished\\n')\n"
                "time.sleep(30)\n")
        started = time.time()
        rc, out, err = self.wrap(self.py(code), ["--timeout", "1"])
        self.assertLess(time.time() - started, 15)
        lines = self.text_lines(out)
        self.assertEqual(rc, 124)
        self.assertTrue(lines[0].startswith("TIMEOUT (TIMED OUT after 1s, command process group terminated) · exit code 124 · "), lines[0])
        self.assertIn("failing tests: 1 identified (junit 0, text-heuristic 1)", lines)
        self.assertEqual([b["ended_by"] for b in self.text_blocks()], ["eof"])
        self.assertEqual(self.message_of(self.records(), self.failures()[0]), "AssertionError: unfinished")

    def test_a_signal_to_the_wrapper_in_the_middle_of_a_failure_block_keeps_the_partial_block(self):
        ready = self.root / "ready"
        code = ("import os, time\n"
                "os.write(1, b'FAIL: t (m.T.t)\\n' + b'-' * 70 + b'\\nTraceback (most recent call last):\\n  File \"x\", line 1\\nAssertionError: interrupted\\n')\n"
                "open(%r, 'w').close()\n"
                "time.sleep(30)\n" % str(ready))
        argv = [sys.executable, str(RUN_CHECK_PY), "--log-dir", str(self.logs), "--", sys.executable, "-c", code]
        proc = subprocess.Popen(argv, cwd=str(self.cwd), env=self.env(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        try:
            self.assertTrue(self.wait_for(ready, 20), "the command never became ready")
            proc.send_signal(signal.SIGTERM)
            out, err = proc.communicate(timeout=30)
        finally:
            if proc.poll() is None:
                proc.kill()
        lines = self.text_lines(out)
        self.assertEqual(proc.returncode, 143)
        self.assertTrue(lines[0].startswith("SIGNAL 15 (SIGTERM) wrapper interrupted, command process group terminated · exit code 143"), lines[0])
        self.assertIn("failing tests: 1 identified (junit 0, text-heuristic 1)", lines)
        self.assertEqual([b["ended_by"] for b in self.text_blocks()], ["eof"])

    # ---- R12/R13: a stdout that cannot take the summary ----------------------------------------------------------------

    STDOUT_COMMAND = "import os; os.write(1, b'FAIL: t (m.T.t)\\n'); raise SystemExit(3)"

    def summary_undeliverable(self, **popen):
        argv = [sys.executable, str(RUN_CHECK_PY), "--log-dir", str(self.logs), "--", sys.executable, "-c", self.STDOUT_COMMAND]
        return subprocess.Popen(argv, cwd=str(self.cwd), env=self.env(), stderr=subprocess.PIPE, **popen)

    def check_undeliverable(self, proc):
        err = proc.stderr.read()
        proc.stderr.close()
        rc = proc.wait(timeout=30)
        self.assertEqual(rc, 3, err)
        self.assertNotIn(b"Traceback", err)
        self.assertIn(b"run_check.py: the summary could not be written to stdout", err)
        self.assertEqual(self.only_log().read_bytes(), b"FAIL: t (m.T.t)\n")
        self.assertEqual(self.records()[-1]["type"], "end")
        # stderr is then the caller's only result: it carries the result lines of the summary, and claims nothing it did not check
        lines = err.decode("utf-8").splitlines()
        stem = str(self.only_log())[:-len(".log")]
        self.assertTrue(any(re.match(r"^COMMAND_EXIT 3 · exit code 3 · \d+\.\ds · 1 log lines · 16 log bytes$", l) for l in lines), lines)
        self.assertIn("log: %s.log" % stem, lines)
        self.assertIn("capture: VERIFIED 16 bytes, sha256 %s (fsync + read-back)" % hashlib.sha256(b"FAIL: t (m.T.t)\n").hexdigest(), lines)
        self.assertIn("failures index: %s.failures.jsonl" % stem, lines)
        self.assertNotIn(b"are complete", err)

    def undeliverable(self, command, log_dir=None, limit=None):
        """Run the wrapper with a closed stdout (so that the summary cannot be written); returns (exit code, stderr text)."""
        def prepare():
            if limit:
                resource.setrlimit(resource.RLIMIT_FSIZE, (limit, limit))
            os.close(1)
        argv = [sys.executable, str(RUN_CHECK_PY), "--log-dir", str(log_dir or self.logs), "--"] + list(command)
        proc = subprocess.Popen(argv, cwd=str(self.cwd), env=self.env(), stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                                stderr=subprocess.PIPE, preexec_fn=prepare)
        err = proc.stderr.read()
        proc.stderr.close()
        rc = proc.wait(timeout=60)
        self.assertNotIn(b"Traceback", err)
        return rc, err.decode("utf-8")

    def test_a_stdout_whose_reader_is_gone_does_not_change_the_exit_code_or_raise_a_traceback(self):
        proc = self.summary_undeliverable(stdout=subprocess.PIPE)
        proc.stdout.close()                                              # the reader closes before the summary is written
        self.check_undeliverable(proc)

    def test_a_closed_stdout_does_not_change_the_exit_code_or_raise_a_traceback(self):
        proc = self.summary_undeliverable(stdout=subprocess.DEVNULL, preexec_fn=lambda: os.close(1))
        self.check_undeliverable(proc)

    @unittest.skipUnless(os.path.exists("/dev/full"), "needs /dev/full (Linux); not verified on macOS")
    def test_a_stdout_on_a_full_device_does_not_change_the_exit_code_or_raise_a_traceback(self):
        with open("/dev/full", "wb") as full:
            proc = self.summary_undeliverable(stdout=full)
            self.check_undeliverable(proc)

    def test_a_command_that_was_not_found_and_a_dead_stdout_keep_exit_127_and_say_that_the_command_did_not_run(self):
        rc, text = self.undeliverable(["/nonexistent/run-check-command"])
        lines = text.splitlines()
        self.assertEqual(rc, 127, text)
        self.assertIn("run_check.py: the summary could not be written to stdout", lines[0])
        self.assertTrue(any(l.startswith("WRAPPER_ERROR (command not found: /nonexistent/run-check-command) · exit code 127 · ")
                            for l in lines), lines)
        self.assertIn("capture: none (command did not run)", lines)
        self.assertIn("log: %s" % self.only_log(), lines)
        self.assertEqual(len([l for l in lines if l.startswith("failures index: ")]), 1, lines)
        self.assertNotIn("are complete", text)

    def test_a_log_directory_that_cannot_be_created_and_a_dead_stdout_keep_exit_125_and_say_that_no_log_exists(self):
        (self.root / "blocker").write_text("a regular file")
        rc, text = self.undeliverable([sys.executable, "-c", "pass"], log_dir=self.root / "blocker" / "logs")
        lines = text.splitlines()
        self.assertEqual(rc, 125, text)
        self.assertTrue(any(l.startswith("WRAPPER_ERROR (cannot create log: ") and " · exit code 125 · " in l for l in lines), lines)
        self.assertIn("log: none (not created)", lines)
        self.assertIn("capture: none (command did not run)", lines)
