    def test_call_ends_keep_exit_evidence_and_mapper_operations_their_stage(self):
        for fields in (["exit_code=137"], ["wait_exit_code=2", "result_exit_code=1"]):
            self.assertEqual(self.event("call_end", *fields)[0], 0)
        self.assertEqual(self.event("mapper_start", "task_index=0")[:2], (0, "1"))
        self.assertEqual(self.event("mapper", "task_index=0", "status=aborted", "stage=session", "op_seq=1")[0], 0)
        self.assertEqual(self.event("mapper", "task_index=0", "stage=nowhere")[:2], (3, "EINVAL"))

    def test_call_end_copies_its_start_and_classifies_only_provider_evidence(self):
        dims = ["member_index=1", "kind=claude", "mode=read", "executor=false", "model=m", "effort=high", "gen=2",
                "task_index=0", "split_child=false", "step=ratify", "round=1"]
        cases = (("cli_error", "Error: You exceeded your current quota SECRETQ", "quota"),
                 ("cli_error", "HTTP 401 Unauthorized SECRETA", "auth"),
                 ("cli_error", "connection reset SECRETC", "cli_error"),
                 ("timeout", "rate limit reached SECRETT", "timeout"))
        for base, evidence, want in cases:
            seq = self.event("call_start", *dims)[1]
            rc, out, err = self.event("call_end", "call_seq=" + seq, "outcome=failed", "failure_class=" + base,
                                      stdin=evidence, opts=["--evidence-stdin"])
            self.assertEqual(rc, 0, err)
            rec = self.lines(self.events_file)[-1]
            self.assertEqual(rec["failure_class"], want, evidence)
            self.assertEqual([rec[k] for k in ("member_index", "kind", "gen", "step", "round", "call_seq")],
                             [1, "claude", 2, "ratify", 1, int(seq)])
            self.assertIsInstance(rec["duration_s"], int)
        text = self.events_file.read_text()
        for secret in ("SECRETQ", "SECRETA", "SECRETC", "SECRETT", "Unauthorized", "quota SECRET"):
            self.assertNotIn(secret, text)
        self.assertEqual([r["attempt"] for r in self.lines(self.events_file) if r["ev"] == "call_end"], [1, 2, 3, 4])

    def test_ship_appends_events_and_a_summary_in_one_write_and_advances_the_cursor(self):
        for _ in range(3):
            self.event("split_failed", "task_index=0")
        writes, real = [], os.write

        def counting(fd, data):
            writes.append(bytes(data))
            return real(fd, data)
        rc, out = self.ship_inproc(4, write=counting)
        self.assertEqual(rc, 0, out)
        batch = [w for w in writes if b'"run_summary"' in w]
        self.assertEqual(len(batch), 1, "events and summary are one write")
        self.assertEqual(batch[0], self.ledger_file.read_bytes())
        recs = self.lines(self.ledger_file)
        self.assertEqual([r["ev"] for r in recs], ["split_failed"] * 3 + ["run_summary"])
        s = recs[-1]
        self.assertEqual([s[k] for k in ("seq", "last_event_seq", "exit_code", "status", "inv", "host", "run")],
                         [4, 3, 0, "done", 1, TM_HOST, TM_RUN])
        self.assertEqual(int((self.run_dir / "telemetry.shipped").read_text()), self.events_file.stat().st_size)
        self.assertEqual([stat.S_IMODE(p.stat().st_mode) for p in (self.ledger, self.ledger_file, self.run_dir / "telemetry.shipped")],
                         [0o700, 0o600, 0o600])
        rc, _ = self.ship_inproc(5)
        self.assertEqual([r["ev"] for r in self.lines(self.ledger_file)][4:], ["run_summary"], "nothing is shipped twice")

    def test_a_short_write_is_an_error_that_keeps_the_cursor_and_the_next_export_resends(self):
        for _ in range(3):
            self.event("split_failed", "task_index=0")
        real = os.write

        def short(fd, data):
            if b'"run_summary"' in data:
                return real(fd, data[: len(data) // 2])
            return real(fd, data)
        self.assertEqual(self.ship_inproc(4, write=short), (3, "EIO"))
        self.assertFalse((self.run_dir / "telemetry.shipped").exists())
        self.assertEqual(self.cli(*self.ship_args(5))[:2], (0, ""))
        parsed = []
        for line in self.ledger_file.read_text().splitlines():
            try:
                parsed.append(json.loads(line))
            except ValueError:
                pass
        self.assertEqual([r["seq"] for r in parsed if r["ev"] == "run_summary"], [5], "the torn summary never parses")
        rc, out, err = self.cli(self.ledger, script=TELEMETRY_REPORT_PY)
        self.assertEqual(rc, 0, err)
        self.assertIn("events: 3", out)
        self.assertIn("malformed or truncated lines: 1", out)

    def test_a_held_lock_times_out_as_etimedout_and_nothing_is_appended(self):
        self.event("split_failed", "task_index=0")
        self.ledger.mkdir(mode=0o700)
        holder = subprocess.Popen([sys.executable, "-c", "import fcntl,os,sys,time\n"
                                   "fd=os.open(sys.argv[1],os.O_RDWR|os.O_CREAT,0o600); fcntl.lockf(fd,fcntl.LOCK_EX)\n"
                                   "print('locked',flush=True); time.sleep(60)", str(self.ledger_file)],
                                  stdout=subprocess.PIPE, text=True)
        self.addCleanup(holder.stdout.close)
        self.addCleanup(holder.wait)
        self.addCleanup(holder.kill)
        self.assertEqual(holder.stdout.readline().strip(), "locked")
        self.assertEqual(self.ship_inproc(2, LOCK_TIMEOUT=0.3), (3, "ETIMEDOUT"))
        self.assertEqual(self.ledger_file.stat().st_size, 0)
        self.assertFalse((self.run_dir / "telemetry.shipped").exists())

    def test_a_failed_cursor_update_resends_and_the_report_counts_once(self):
        self.event("split_failed", "task_index=0")
        self.event("split_failed", "task_index=1")
        self.run_dir.chmod(0o500)   # the cursor cannot be updated after the ledger append
        self.addCleanup(self.run_dir.chmod, 0o700)
        rc, out, err = self.cli(*self.ship_args(3))
        self.run_dir.chmod(0o700)
        self.assertEqual((rc, out), (3, "EACCES"), err)
        self.assertEqual([r["ev"] for r in self.lines(self.ledger_file)], ["split_failed", "split_failed", "run_summary"])
        self.assertEqual(sorted(os.listdir(self.run_dir)), ["telemetry.jsonl"], "no temporary cursor is left")
        self.assertEqual(self.cli(*self.ship_args(4))[:2], (0, ""))
        rc, out, err = self.cli(self.ledger, script=TELEMETRY_REPORT_PY)
        self.assertIn("events: 2", out)
        self.assertIn("duplicate records (identical, counted once): 2", out)

